INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 1, E'The burden which Habakkuk the prophet did see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 2, E'O LORD, how long shall I cry, and thou wilt not hear! even cry out unto thee of violence, and thou wilt not save!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 3, E'Why dost thou shew me iniquity, and cause me to behold grievance? for spoiling and violence are before me: and there are that raise up strife and contention.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 4, E'Therefore the law is slacked, and judgment doth never go forth: for the wicked doth compass about the righteous; therefore wrong judgment proceedeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 5, E'Behold ye among the heathen, and regard, and wonder marvellously: for I will work a work in your days, which ye will not believe, though it be told you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 6, E'For, lo, I raise up the Chaldeans, that bitter and hasty nation, which shall march through the breadth of the land, to possess the dwellingplaces that are not theirs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 7, E'They are terrible and dreadful: their judgment and their dignity shall proceed of themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 8, E'Their horses also are swifter than the leopards, and are more fierce than the evening wolves: and their horsemen shall spread themselves, and their horsemen shall come from far; they shall fly as the eagle that hasteth to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 9, E'They shall come all for violence: their faces shall sup up as the east wind, and they shall gather the captivity as the sand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 10, E'And they shall scoff at the kings, and the princes shall be a scorn unto them: they shall deride every strong hold; for they shall heap dust, and take it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 11, E'Then shall his mind change, and he shall pass over, and offend, imputing this his power unto his god.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 12, E'Art thou not from everlasting, O LORD my God, mine Holy One? we shall not die. O LORD, thou hast ordained them for judgment; and, O mighty God, thou hast established them for correction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 13, E'Thou art of purer eyes than to behold evil, and canst not look on iniquity: wherefore lookest thou upon them that deal treacherously, and holdest thy tongue when the wicked devoureth the man that is more righteous than he?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 14, E'And makest men as the fishes of the sea, as the creeping things, that have no ruler over them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 15, E'They take up all of them with the angle, they catch them in their net, and gather them in their drag: therefore they rejoice and are glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 16, E'Therefore they sacrifice unto their net, and burn incense unto their drag; because by them their portion is fat, and their meat plenteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 1, 17, E'Shall they therefore empty their net, and not spare continually to slay the nations?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 1, E'I will stand upon my watch, and set me upon the tower, and will watch to see what he will say unto me, and what I shall answer when I am reproved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 2, E'And the LORD answered me, and said, Write the vision, and make it plain upon tables, that he may run that readeth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 3, E'For the vision is yet for an appointed time, but at the end it shall speak, and not lie: though it tarry, wait for it; because it will surely come, it will not tarry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 4, E'Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 5, E'Yea also, because he transgresseth by wine, he is a proud man, neither keepeth at home, who enlargeth his desire as hell, and is as death, and cannot be satisfied, but gathereth unto him all nations, and heapeth unto him all people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 6, E'Shall not all these take up a parable against him, and a taunting proverb against him, and say, Woe to him that increaseth that which is not his! how long? and to him that ladeth himself with thick clay!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 7, E'Shall they not rise up suddenly that shall bite thee, and awake that shall vex thee, and thou shalt be for booties unto them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 8, E'Because thou hast spoiled many nations, all the remnant of the people shall spoil thee; because of menâ€™s blood, and for the violence of the land, of the city, and of all that dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 9, E'Woe to him that coveteth an evil covetousness to his house, that he may set his nest on high, that he may be delivered from the power of evil!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 10, E'Thou hast consulted shame to thy house by cutting off many people, and hast sinned against thy soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 11, E'For the stone shall cry out of the wall, and the beam out of the timber shall answer it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 12, E'Woe to him that buildeth a town with blood, and stablisheth a city by iniquity!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 13, E'Behold, is it not of the LORD of hosts that the people shall labour in the very fire, and the people shall weary themselves for very vanity?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 14, E'For the earth shall be filled with the knowledge of the glory of the LORD, as the waters cover the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 15, E'Woe unto him that giveth his neighbour drink, that puttest thy bottle to him, and makest him drunken also, that thou mayest look on their nakedness!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 16, E'Thou art filled with shame for glory: drink thou also, and let thy foreskin be uncovered: the cup of the LORDâ€™s right hand shall be turned unto thee, and shameful spewing shall be on thy glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 17, E'For the violence of Lebanon shall cover thee, and the spoil of beasts, which made them afraid, because of menâ€™s blood, and for the violence of the land, of the city, and of all that dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 18, E'What profiteth the graven image that the maker thereof hath graven it; the molten image, and a teacher of lies, that the maker of his work trusteth therein, to make dumb idols?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 19, E'Woe unto him that saith to the wood, Awake; to the dumb stone, Arise, it shall teach! Behold, it is laid over with gold and silver, and there is no breath at all in the midst of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 2, 20, E'But the LORD is in his holy temple: let all the earth keep silence before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 1, E'A prayer of Habakkuk the prophet upon Shigionoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 2, E'O LORD, I have heard thy speech, and was afraid: O LORD, revive thy work in the midst of the years, in the midst of the years make known; in wrath remember mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 3, E'God came from Teman, and the Holy One from mount Paran. Selah. His glory covered the heavens, and the earth was full of his praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 4, E'And his brightness was as the light; he had horns coming out of his hand: and there was the hiding of his power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 5, E'Before him went the pestilence, and burning coals went forth at his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 6, E'He stood, and measured the earth: he beheld, and drove asunder the nations; and the everlasting mountains were scattered, the perpetual hills did bow: his ways are everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 7, E'I saw the tents of Cushan in affliction: and the curtains of the land of Midian did tremble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 8, E'Was the LORD displeased against the rivers? was thine anger against the rivers? was thy wrath against the sea, that thou didst ride upon thine horses and thy chariots of salvation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 9, E'Thy bow was made quite naked, according to the oaths of the tribes, even thy word. Selah. Thou didst cleave the earth with rivers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 10, E'The mountains saw thee, and they trembled: the overflowing of the water passed by: the deep uttered his voice, and lifted up his hands on high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 11, E'The sun and moon stood still in their habitation: at the light of thine arrows they went, and at the shining of thy glittering spear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 12, E'Thou didst march through the land in indignation, thou didst thresh the heathen in anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 13, E'Thou wentest forth for the salvation of thy people, even for salvation with thine anointed; thou woundedst the head out of the house of the wicked, by discovering the foundation unto the neck. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 14, E'Thou didst strike through with his staves the head of his villages: they came out as a whirlwind to scatter me: their rejoicing was as to devour the poor secretly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 15, E'Thou didst walk through the sea with thine horses, through the heap of great waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 16, E'When I heard, my belly trembled; my lips quivered at the voice: rottenness entered into my bones, and I trembled in myself, that I might rest in the day of trouble: when he cometh up unto the people, he will invade them with his troops.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 17, E'Although the fig tree shall not blossom, neither shall fruit be in the vines; the labour of the olive shall fail, and the fields shall yield no meat; the flock shall be cut off from the fold, and there shall be no herd in the stalls:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 18, E'Yet I will rejoice in the LORD, I will joy in the God of my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '6a515b6b-8b2e-4211-b19d-fd114f953abd', 3, 19, E'The LORD God is my strength, and he will make my feet like hindsâ€™ feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Habakkuk') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 1, E'The word of the LORD which came unto Zephaniah the son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hizkiah, in the days of Josiah the son of Amon, king of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 2, E'I will utterly consume all things from off the land, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 3, E'I will consume man and beast; I will consume the fowls of the heaven, and the fishes of the sea, and the stumbling blocks with the wicked: and I will cut off man from off the land, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 4, E'I will also stretch out mine hand upon Judah, and upon all the inhabitants of Jerusalem; and I will cut off the remnant of Baal from this place, and the name of the Chemarims with the priests;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 5, E'And them that worship the host of heaven upon the housetops; and them that worship and that swear by the LORD, and that swear by Malcham;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 6, E'And them that are turned back from the LORD; and those that have not sought the LORD, nor enquired for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 7, E'Hold thy peace at the presence of the Lord GOD: for the day of the LORD is at hand: for the LORD hath prepared a sacrifice, he hath bid his guests.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 8, E'And it shall come to pass in the day of the LORDâ€™s sacrifice, that I will punish the princes, and the kingâ€™s children, and all such as are clothed with strange apparel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 9, E'In the same day also will I punish all those that leap on the threshold, which fill their mastersâ€™ houses with violence and deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 10, E'And it shall come to pass in that day, saith the LORD, that there shall be the noise of a cry from the fish gate, and an howling from the second, and a great crashing from the hills.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 11, E'Howl, ye inhabitants of Maktesh, for all the merchant people are cut down; all they that bear silver are cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 12, E'And it shall come to pass at that time, that I will search Jerusalem with candles, and punish the men that are settled on their lees: that say in their heart, The LORD will not do good, neither will he do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 13, E'Therefore their goods shall become a booty, and their houses a desolation: they shall also build houses, but not inhabit them; and they shall plant vineyards, but not drink the wine thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 14, E'The great day of the LORD is near, it is near, and hasteth greatly, even the voice of the day of the LORD: the mighty man shall cry there bitterly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 15, E'That day is a day of wrath, a day of trouble and distress, a day of wasteness and desolation, a day of darkness and gloominess, a day of clouds and thick darkness,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 16, E'A day of the trumpet and alarm against the fenced cities, and against the high towers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 17, E'And I will bring distress upon men, that they shall walk like blind men, because they have sinned against the LORD: and their blood shall be poured out as dust, and their flesh as the dung.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 1, 18, E'Neither their silver nor their gold shall be able to deliver them in the day of the LORDâ€™s wrath; but the whole land shall be devoured by the fire of his jealousy: for he shall make even a speedy riddance of all them that dwell in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 1, E'Gather yourselves together, yea, gather together, O nation not desired;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 2, E'Before the decree bring forth, before the day pass as the chaff, before the fierce anger of the LORD come upon you, before the day of the LORDâ€™s anger come upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 3, E'Seek ye the LORD, all ye meek of the earth, which have wrought his judgment; seek righteousness, seek meekness: it may be ye shall be hid in the day of the LORDâ€™s anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 4, E'For Gaza shall be forsaken, and Ashkelon a desolation: they shall drive out Ashdod at the noon day, and Ekron shall be rooted up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 5, E'Woe unto the inhabitants of the sea coast, the nation of the Cherethites! the word of the LORD is against you; O Canaan, the land of the Philistines, I will even destroy thee, that there shall be no inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 6, E'And the sea coast shall be dwellings and cottages for shepherds, and folds for flocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 7, E'And the coast shall be for the remnant of the house of Judah; they shall feed thereupon: in the houses of Ashkelon shall they lie down in the evening: for the LORD their God shall visit them, and turn away their captivity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 8, E'I have heard the reproach of Moab, and the revilings of the children of Ammon, whereby they have reproached my people, and magnified themselves against their border.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 9, E'Therefore as I live, saith the LORD of hosts, the God of Israel, Surely Moab shall be as Sodom, and the children of Ammon as Gomorrah, even the breeding of nettles, and saltpits, and a perpetual desolation: the residue of my people shall spoil them, and the remnant of my people shall possess them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 10, E'This shall they have for their pride, because they have reproached and magnified themselves against the people of the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 11, E'The LORD will be terrible unto them: for he will famish all the gods of the earth; and men shall worship him, every one from his place, even all the isles of the heathen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 12, E'Ye Ethiopians also, ye shall be slain by my sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 13, E'And he will stretch out his hand against the north, and destroy Assyria; and will make Nineveh a desolation, and dry like a wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 14, E'And flocks shall lie down in the midst of her, all the beasts of the nations: both the cormorant and the bittern shall lodge in the upper lintels of it; their voice shall sing in the windows; desolation shall be in the thresholds: for he shall uncover the cedar work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 2, 15, E'This is the rejoicing city that dwelt carelessly, that said in her heart, I am, and there is none beside me: how is she become a desolation, a place for beasts to lie down in! every one that passeth by her shall hiss, and wag his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 1, E'Woe to her that is filthy and polluted, to the oppressing city!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 2, E'She obeyed not the voice; she received not correction; she trusted not in the LORD; she drew not near to her God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 3, E'Her princes within her are roaring lions; her judges are evening wolves; they gnaw not the bones till the morrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 4, E'Her prophets are light and treacherous persons: her priests have polluted the sanctuary, they have done violence to the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 5, E'The just LORD is in the midst thereof; he will not do iniquity: every morning doth he bring his judgment to light, he faileth not; but the unjust knoweth no shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 6, E'I have cut off the nations: their towers are desolate; I made their streets waste, that none passeth by: their cities are destroyed, so that there is no man, that there is none inhabitant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 7, E'I said, Surely thou wilt fear me, thou wilt receive instruction; so their dwelling should not be cut off, howsoever I punished them: but they rose early, and corrupted all their doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 8, E'Therefore wait ye upon me, saith the LORD, until the day that I rise up to the prey: for my determination is to gather the nations, that I may assemble the kingdoms, to pour upon them mine indignation, even all my fierce anger: for all the earth shall be devoured with the fire of my jealousy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 9, E'For then will I turn to the people a pure language, that they may all call upon the name of the LORD, to serve him with one consent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 10, E'From beyond the rivers of Ethiopia my suppliants, even the daughter of my dispersed, shall bring mine offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 11, E'In that day shalt thou not be ashamed for all thy doings, wherein thou hast transgressed against me: for then I will take away out of the midst of thee them that rejoice in thy pride, and thou shalt no more be haughty because of my holy mountain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 12, E'I will also leave in the midst of thee an afflicted and poor people, and they shall trust in the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 13, E'The remnant of Israel shall not do iniquity, nor speak lies; neither shall a deceitful tongue be found in their mouth: for they shall feed and lie down, and none shall make them afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 14, E'Sing, O daughter of Zion; shout, O Israel; be glad and rejoice with all the heart, O daughter of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 15, E'The LORD hath taken away thy judgments, he hath cast out thine enemy: the king of Israel, even the LORD, is in the midst of thee: thou shalt not see evil any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 16, E'In that day it shall be said to Jerusalem, Fear thou not: and to Zion, Let not thine hands be slack.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 17, E'The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 18, E'I will gather them that are sorrowful for the solemn assembly, who are of thee, to whom the reproach of it was a burden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 19, E'Behold, at that time I will undo all that afflict thee: and I will save her that halteth, and gather her that was driven out; and I will get them praise and fame in every land where they have been put to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '701f86c4-1785-493d-80e4-ae6b8584cfff', 3, 20, E'At that time will I bring you again, even in the time that I gather you: for I will make you a name and a praise among all people of the earth, when I turn back your captivity before your eyes, saith the LORD.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Zephaniah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 1, E'In the second year of Darius the king, in the sixth month, in the first day of the month, came the word of the LORD by Haggai the prophet unto Zerubbabel the son of Shealtiel, governor of Judah, and to Joshua the son of Josedech, the high priest, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 2, E'Thus speaketh the LORD of hosts, saying, This people say, The time is not come, the time that the LORDâ€™s house should be built.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 3, E'Then came the word of the LORD by Haggai the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 4, E'Is it time for you, O ye, to dwell in your cieled houses, and this house lie waste?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 5, E'Now therefore thus saith the LORD of hosts; Consider your ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 6, E'Ye have sown much, and bring in little; ye eat, but ye have not enough; ye drink, but ye are not filled with drink; ye clothe you, but there is none warm; and he that earneth wages earneth wages to put it into a bag with holes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 7, E'Thus saith the LORD of hosts; Consider your ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 8, E'Go up to the mountain, and bring wood, and build the house; and I will take pleasure in it, and I will be glorified, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 9, E'Ye looked for much, and lo, it came to little; and when ye brought it home, I did blow upon it. Why? saith the LORD of hosts. Because of mine house that is waste, and ye run every man unto his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 10, E'Therefore the heaven over you is stayed from dew, and the earth is stayed from her fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 11, E'And I called for a drought upon the land, and upon the mountains, and upon the corn, and upon the new wine, and upon the oil, and upon that which the ground bringeth forth, and upon men, and upon cattle, and upon all the labour of the hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 12, E'Then Zerubbabel the son of Shealtiel, and Joshua the son of Josedech, the high priest, with all the remnant of the people, obeyed the voice of the LORD their God, and the words of Haggai the prophet, as the LORD their God had sent him, and the people did fear before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 13, E'Then spake Haggai the LORDâ€™s messenger in the LORDâ€™s message unto the people, saying, I am with you, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 14, E'And the LORD stirred up the spirit of Zerubbabel the son of Shealtiel, governor of Judah, and the spirit of Joshua the son of Josedech, the high priest, and the spirit of all the remnant of the people; and they came and did work in the house of the LORD of hosts, their God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 1, 15, E'In the four and twentieth day of the sixth month, in the second year of Darius the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 1, E'In the seventh month, in the one and twentieth day of the month, came the word of the LORD by the prophet Haggai, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 2, E'Speak now to Zerubbabel the son of Shealtiel, governor of Judah, and to Joshua the son of Josedech, the high priest, and to the residue of the people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 3, E'Who is left among you that saw this house in her first glory? and how do ye see it now? is it not in your eyes in comparison of it as nothing?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 4, E'Yet now be strong, O Zerubbabel, saith the LORD; and be strong, O Joshua, son of Josedech, the high priest; and be strong, all ye people of the land, saith the LORD, and work: for I am with you, saith the LORD of hosts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 5, E'According to the word that I covenanted with you when ye came out of Egypt, so my spirit remaineth among you: fear ye not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 6, E'For thus saith the LORD of hosts; Yet once, it is a little while, and I will shake the heavens, and the earth, and the sea, and the dry land;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 7, E'And I will shake all nations, and the desire of all nations shall come: and I will fill this house with glory, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 8, E'The silver is mine, and the gold is mine, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 9, E'The glory of this latter house shall be greater than of the former, saith the LORD of hosts: and in this place will I give peace, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 10, E'In the four and twentieth day of the ninth month, in the second year of Darius, came the word of the LORD by Haggai the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 11, E'Thus saith the LORD of hosts; Ask now the priests concerning the law, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 12, E'If one bear holy flesh in the skirt of his garment, and with his skirt do touch bread, or pottage, or wine, or oil, or any meat, shall it be holy? And the priests answered and said, No.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 13, E'Then said Haggai, If one that is unclean by a dead body touch any of these, shall it be unclean? And the priests answered and said, It shall be unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 14, E'Then answered Haggai, and said, So is this people, and so is this nation before me, saith the LORD; and so is every work of their hands; and that which they offer there is unclean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 15, E'And now, I pray you, consider from this day and upward, from before a stone was laid upon a stone in the temple of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 16, E'Since those days were, when one came to an heap of twenty measures, there were but ten: when one came to the pressfat for to draw out fifty vessels out of the press, there were but twenty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 17, E'I smote you with blasting and with mildew and with hail in all the labours of your hands; yet ye turned not to me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 18, E'Consider now from this day and upward, from the four and twentieth day of the ninth month, even from the day that the foundation of the LORDâ€™s temple was laid, consider it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 19, E'Is the seed yet in the barn? yea, as yet the vine, and the fig tree, and the pomegranate, and the olive tree, hath not brought forth: from this day will I bless you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 20, E'And again the word of the LORD came unto Haggai in the four and twentieth day of the month, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 21, E'Speak to Zerubbabel, governor of Judah, saying, I will shake the heavens and the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 22, E'And I will overthrow the throne of kingdoms, and I will destroy the strength of the kingdoms of the heathen; and I will overthrow the chariots, and those that ride in them; and the horses and their riders shall come down, every one by the sword of his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '1bd53a6f-f507-48fd-9dab-a217bb1d970c', 2, 23, E'In that day, saith the LORD of hosts, will I take thee, O Zerubbabel, my servant, the son of Shealtiel, saith the LORD, and will make thee as a signet: for I have chosen thee, saith the LORD of hosts.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Haggai') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 1, E'In the eighth month, in the second year of Darius, came the word of the LORD unto Zechariah, the son of Berechiah, the son of Iddo the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 2, E'The LORD hath been sore displeased with your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 3, E'Therefore say thou unto them, Thus saith the LORD of hosts; Turn ye unto me, saith the LORD of hosts, and I will turn unto you, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 4, E'Be ye not as your fathers, unto whom the former prophets have cried, saying, Thus saith the LORD of hosts; Turn ye now from your evil ways, and from your evil doings: but they did not hear, nor hearken unto me, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 5, E'Your fathers, where are they? and the prophets, do they live for ever?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 6, E'But my words and my statutes, which I commanded my servants the prophets, did they not take hold of your fathers? and they returned and said, Like as the LORD of hosts thought to do unto us, according to our ways, and according to our doings, so hath he dealt with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 7, E'Upon the four and twentieth day of the eleventh month, which is the month Sebat, in the second year of Darius, came the word of the LORD unto Zechariah, the son of Berechiah, the son of Iddo the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 8, E'I saw by night, and behold a man riding upon a red horse, and he stood among the myrtle trees that were in the bottom; and behind him were there red horses, speckled, and white.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 9, E'Then said I, O my lord, what are these? And the angel that talked with me said unto me, I will shew thee what these be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 10, E'And the man that stood among the myrtle trees answered and said, These are they whom the LORD hath sent to walk to and fro through the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 11, E'And they answered the angel of the LORD that stood among the myrtle trees, and said, We have walked to and fro through the earth, and, behold, all the earth sitteth still, and is at rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 12, E'Then the angel of the LORD answered and said, O LORD of hosts, how long wilt thou not have mercy on Jerusalem and on the cities of Judah, against which thou hast had indignation these threescore and ten years?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 13, E'And the LORD answered the angel that talked with me with good words and comfortable words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 14, E'So the angel that communed with me said unto me, Cry thou, saying, Thus saith the LORD of hosts; I am jealous for Jerusalem and for Zion with a great jealousy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 15, E'And I am very sore displeased with the heathen that are at ease: for I was but a little displeased, and they helped forward the affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 16, E'Therefore thus saith the LORD; I am returned to Jerusalem with mercies: my house shall be built in it, saith the LORD of hosts, and a line shall be stretched forth upon Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 17, E'Cry yet, saying, Thus saith the LORD of hosts; My cities through prosperity shall yet be spread abroad; and the LORD shall yet comfort Zion, and shall yet choose Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 18, E'Then lifted I up mine eyes, and saw, and behold four horns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 19, E'And I said unto the angel that talked with me, What be these? And he answered me, These are the horns which have scattered Judah, Israel, and Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 20, E'And the LORD shewed me four carpenters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 1, 21, E'Then said I, What come these to do? And he spake, saying, These are the horns which have scattered Judah, so that no man did lift up his head: but these are come to fray them, to cast out the horns of the Gentiles, which lifted up their horn over the land of Judah to scatter it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 1, E'I lifted up mine eyes again, and looked, and behold a man with a measuring line in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 2, E'Then said I, Whither goest thou? And he said unto me, To measure Jerusalem, to see what is the breadth thereof, and what is the length thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 3, E'And, behold, the angel that talked with me went forth, and another angel went out to meet him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 4, E'And said unto him, Run, speak to this young man, saying, Jerusalem shall be inhabited as towns without walls for the multitude of men and cattle therein:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 5, E'For I, saith the LORD, will be unto her a wall of fire round about, and will be the glory in the midst of her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 6, E'Ho, ho, come forth, and flee from the land of the north, saith the LORD: for I have spread you abroad as the four winds of the heaven, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 7, E'Deliver thyself, O Zion, that dwellest with the daughter of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 8, E'For thus saith the LORD of hosts; After the glory hath he sent me unto the nations which spoiled you: for he that toucheth you toucheth the apple of his eye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 9, E'For, behold, I will shake mine hand upon them, and they shall be a spoil to their servants: and ye shall know that the LORD of hosts hath sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 10, E'Sing and rejoice, O daughter of Zion: for, lo, I come, and I will dwell in the midst of thee, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 11, E'And many nations shall be joined to the LORD in that day, and shall be my people: and I will dwell in the midst of thee, and thou shalt know that the LORD of hosts hath sent me unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 12, E'And the LORD shall inherit Judah his portion in the holy land, and shall choose Jerusalem again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 2, 13, E'Be silent, O all flesh, before the LORD: for he is raised up out of his holy habitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 1, E'And he shewed me Joshua the high priest standing before the angel of the LORD, and Satan standing at his right hand to resist him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 2, E'And the LORD said unto Satan, The LORD rebuke thee, O Satan; even the LORD that hath chosen Jerusalem rebuke thee: is not this a brand plucked out of the fire?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 3, E'Now Joshua was clothed with filthy garments, and stood before the angel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 4, E'And he answered and spake unto those that stood before him, saying, Take away the filthy garments from him. And unto him he said, Behold, I have caused thine iniquity to pass from thee, and I will clothe thee with change of raiment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 5, E'And I said, Let them set a fair mitre upon his head. So they set a fair mitre upon his head, and clothed him with garments. And the angel of the LORD stood by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 6, E'And the angel of the LORD protested unto Joshua, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 7, E'Thus saith the LORD of hosts; If thou wilt walk in my ways, and if thou wilt keep my charge, then thou shalt also judge my house, and shalt also keep my courts, and I will give thee places to walk among these that stand by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 8, E'Hear now, O Joshua the high priest, thou, and thy fellows that sit before thee: for they are men wondered at: for, behold, I will bring forth my servant the BRANCH.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 9, E'For behold the stone that I have laid before Joshua; upon one stone shall be seven eyes: behold, I will engrave the graving thereof, saith the LORD of hosts, and I will remove the iniquity of that land in one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 3, 10, E'In that day, saith the LORD of hosts, shall ye call every man his neighbour under the vine and under the fig tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 1, E'And the angel that talked with me came again, and waked me, as a man that is wakened out of his sleep,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 2, E'And said unto me, What seest thou? And I said, I have looked, and behold a candlestick all of gold, with a bowl upon the top of it, and his seven lamps thereon, and seven pipes to the seven lamps, which are upon the top thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 3, E'And two olive trees by it, one upon the right side of the bowl, and the other upon the left side thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 4, E'So I answered and spake to the angel that talked with me, saying, What are these, my lord?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 5, E'Then the angel that talked with me answered and said unto me, Knowest thou not what these be? And I said, No, my lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 6, E'Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 7, E'Who art thou, O great mountain? before Zerubbabel thou shalt become a plain: and he shall bring forth the headstone thereof with shoutings, crying, Grace, grace unto it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 8, E'Moreover the word of the LORD came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 9, E'The hands of Zerubbabel have laid the foundation of this house; his hands shall also finish it; and thou shalt know that the LORD of hosts hath sent me unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 10, E'For who hath despised the day of small things? for they shall rejoice, and shall see the plummet in the hand of Zerubbabel with those seven; they are the eyes of the LORD, which run to and fro through the whole earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 11, E'Then answered I, and said unto him, What are these two olive trees upon the right side of the candlestick and upon the left side thereof?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 12, E'And I answered again, and said unto him, What be these two olive branches which through the two golden pipes empty the golden oil out of themselves?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 13, E'And he answered me and said, Knowest thou not what these be? And I said, No, my lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 4, 14, E'Then said he, These are the two anointed ones, that stand by the LORD of the whole earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 1, E'Then I turned, and lifted up mine eyes, and looked, and behold a flying roll.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 2, E'And he said unto me, What seest thou? And I answered, I see a flying roll; the length thereof is twenty cubits, and the breadth thereof ten cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 3, E'Then said he unto me, This is the curse that goeth forth over the face of the whole earth: for every one that stealeth shall be cut off as on this side according to it; and every one that sweareth shall be cut off as on that side according to it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 4, E'I will bring it forth, saith the LORD of hosts, and it shall enter into the house of the thief, and into the house of him that sweareth falsely by my name: and it shall remain in the midst of his house, and shall consume it with the timber thereof and the stones thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 5, E'Then the angel that talked with me went forth, and said unto me, Lift up now thine eyes, and see what is this that goeth forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 6, E'And I said, What is it? And he said, This is an ephah that goeth forth. He said moreover, This is their resemblance through all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 7, E'And, behold, there was lifted up a talent of lead: and this is a woman that sitteth in the midst of the ephah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 8, E'And he said, This is wickedness. And he cast it into the midst of the ephah; and he cast the weight of lead upon the mouth thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 9, E'Then lifted I up mine eyes, and looked, and, behold, there came out two women, and the wind was in their wings; for they had wings like the wings of a stork: and they lifted up the ephah between the earth and the heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 10, E'Then said I to the angel that talked with me, Whither do these bear the ephah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 5, 11, E'And he said unto me, To build it an house in the land of Shinar: and it shall be established, and set there upon her own base.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 1, E'And I turned, and lifted up mine eyes, and looked, and, behold, there came four chariots out from between two mountains; and the mountains were mountains of brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 2, E'In the first chariot were red horses; and in the second chariot black horses;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 3, E'And in the third chariot white horses; and in the fourth chariot grisled and bay horses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 4, E'Then I answered and said unto the angel that talked with me, What are these, my lord?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 5, E'And the angel answered and said unto me, These are the four spirits of the heavens, which go forth from standing before the LORD of all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 6, E'The black horses which are therein go forth into the north country; and the white go forth after them; and the grisled go forth toward the south country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 7, E'And the bay went forth, and sought to go that they might walk to and fro through the earth: and he said, Get you hence, walk to and fro through the earth. So they walked to and fro through the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 8, E'Then cried he upon me, and spake unto me, saying, Behold, these that go toward the north country have quieted my spirit in the north country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 9, E'And the word of the LORD came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 10, E'Take of them of the captivity, even of Heldai, of Tobijah, and of Jedaiah, which are come from Babylon, and come thou the same day, and go into the house of Josiah the son of Zephaniah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 11, E'Then take silver and gold, and make crowns, and set them upon the head of Joshua the son of Josedech, the high priest;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 12, E'And speak unto him, saying, Thus speaketh the LORD of hosts, saying, Behold the man whose name is The BRANCH; and he shall grow up out of his place, and he shall build the temple of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 13, E'Even he shall build the temple of the LORD; and he shall bear the glory, and shall sit and rule upon his throne; and he shall be a priest upon his throne: and the counsel of peace shall be between them both.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 14, E'And the crowns shall be to Helem, and to Tobijah, and to Jedaiah, and to Hen the son of Zephaniah, for a memorial in the temple of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 6, 15, E'And they that are far off shall come and build in the temple of the LORD, and ye shall know that the LORD of hosts hath sent me unto you. And this shall come to pass, if ye will diligently obey the voice of the LORD your God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 1, E'And it came to pass in the fourth year of king Darius, that the word of the LORD came unto Zechariah in the fourth day of the ninth month, even in Chisleu;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 2, E'When they had sent unto the house of God Sherezer and Regemmelech, and their men, to pray before the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 3, E'And to speak unto the priests which were in the house of the LORD of hosts, and to the prophets, saying, Should I weep in the fifth month, separating myself, as I have done these so many years?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 4, E'Then came the word of the LORD of hosts unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 5, E'Speak unto all the people of the land, and to the priests, saying, When ye fasted and mourned in the fifth and seventh month, even those seventy years, did ye at all fast unto me, even to me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 6, E'And when ye did eat, and when ye did drink, did not ye eat for yourselves, and drink for yourselves?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 7, E'Should ye not hear the words which the LORD hath cried by the former prophets, when Jerusalem was inhabited and in prosperity, and the cities thereof round about her, when men inhabited the south and the plain?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 8, E'And the word of the LORD came unto Zechariah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 9, E'Thus speaketh the LORD of hosts, saying, Execute true judgment, and shew mercy and compassions every man to his brother:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 10, E'And oppress not the widow, nor the fatherless, the stranger, nor the poor; and let none of you imagine evil against his brother in your heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 11, E'But they refused to hearken, and pulled away the shoulder, and stopped their ears, that they should not hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 12, E'Yea, they made their hearts as an adamant stone, lest they should hear the law, and the words which the LORD of hosts hath sent in his spirit by the former prophets: therefore came a great wrath from the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 13, E'Therefore it is come to pass, that as he cried, and they would not hear; so they cried, and I would not hear, saith the LORD of hosts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 7, 14, E'But I scattered them with a whirlwind among all the nations whom they knew not. Thus the land was desolate after them, that no man passed through nor returned: for they laid the pleasant land desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 1, E'Again the word of the LORD of hosts came to me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 2, E'Thus saith the LORD of hosts; I was jealous for Zion with great jealousy, and I was jealous for her with great fury.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Zechariah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 3, E'Thus saith the LORD; I am returned unto Zion, and will dwell in the midst of Jerusalem: and Jerusalem shall be called a city of truth; and the mountain of the LORD of hosts the holy mountain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 4, E'Thus saith the LORD of hosts; There shall yet old men and old women dwell in the streets of Jerusalem, and every man with his staff in his hand for very age.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 5, E'And the streets of the city shall be full of boys and girls playing in the streets thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 6, E'Thus saith the LORD of hosts; If it be marvellous in the eyes of the remnant of this people in these days, should it also be marvellous in mine eyes? saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 7, E'Thus saith the LORD of hosts; Behold, I will save my people from the east country, and from the west country;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 8, E'And I will bring them, and they shall dwell in the midst of Jerusalem: and they shall be my people, and I will be their God, in truth and in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 9, E'Thus saith the LORD of hosts; Let your hands be strong, ye that hear in these days these words by the mouth of the prophets, which were in the day that the foundation of the house of the LORD of hosts was laid, that the temple might be built.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 10, E'For before these days there was no hire for man, nor any hire for beast; neither was there any peace to him that went out or came in because of the affliction: for I set all men every one against his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 11, E'But now I will not be unto the residue of this people as in the former days, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 12, E'For the seed shall be prosperous; the vine shall give her fruit, and the ground shall give her increase, and the heavens shall give their dew; and I will cause the remnant of this people to possess all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 13, E'And it shall come to pass, that as ye were a curse among the heathen, O house of Judah, and house of Israel; so will I save you, and ye shall be a blessing: fear not, but let your hands be strong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 14, E'For thus saith the LORD of hosts; As I thought to punish you, when your fathers provoked me to wrath, saith the LORD of hosts, and I repented not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 15, E'So again have I thought in these days to do well unto Jerusalem and to the house of Judah: fear ye not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 16, E'These are the things that ye shall do; Speak ye every man the truth to his neighbour; execute the judgment of truth and peace in your gates:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 17, E'And let none of you imagine evil in your hearts against his neighbour; and love no false oath: for all these are things that I hate, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 18, E'And the word of the LORD of hosts came unto me, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 19, E'Thus saith the LORD of hosts; The fast of the fourth month, and the fast of the fifth, and the fast of the seventh, and the fast of the tenth, shall be to the house of Judah joy and gladness, and cheerful feasts; therefore love the truth and peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 20, E'Thus saith the LORD of hosts; It shall yet come to pass, that there shall come people, and the inhabitants of many cities:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 21, E'And the inhabitants of one city shall go to another, saying, Let us go speedily to pray before the LORD, and to seek the LORD of hosts: I will go also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 22, E'Yea, many people and strong nations shall come to seek the LORD of hosts in Jerusalem, and to pray before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 8, 23, E'Thus saith the LORD of hosts; In those days it shall come to pass, that ten men shall take hold out of all languages of the nations, even shall take hold of the skirt of him that is a Jew, saying, We will go with you: for we have heard that God is with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 1, E'The burden of the word of the LORD in the land of Hadrach, and Damascus shall be the rest thereof: when the eyes of man, as of all the tribes of Israel, shall be toward the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 2, E'And Hamath also shall border thereby; Tyrus, and Zidon, though it be very wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 3, E'And Tyrus did build herself a strong hold, and heaped up silver as the dust, and fine gold as the mire of the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 4, E'Behold, the LORD will cast her out, and he will smite her power in the sea; and she shall be devoured with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 5, E'Ashkelon shall see it, and fear; Gaza also shall see it, and be very sorrowful, and Ekron; for her expectation shall be ashamed; and the king shall perish from Gaza, and Ashkelon shall not be inhabited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 6, E'And a bastard shall dwell in Ashdod, and I will cut off the pride of the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 7, E'And I will take away his blood out of his mouth, and his abominations from between his teeth: but he that remaineth, even he, shall be for our God, and he shall be as a governor in Judah, and Ekron as a Jebusite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 8, E'And I will encamp about mine house because of the army, because of him that passeth by, and because of him that returneth: and no oppressor shall pass through them any more: for now have I seen with mine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 9, E'Rejoice greatly, O daughter of Zion; shout, O daughter of Jerusalem: behold, thy King cometh unto thee: he is just, and having salvation; lowly, and riding upon an ass, and upon a colt the foal of an ass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 10, E'And I will cut off the chariot from Ephraim, and the horse from Jerusalem, and the battle bow shall be cut off: and he shall speak peace unto the heathen: and his dominion shall be from sea even to sea, and from the river even to the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 11, E'As for thee also, by the blood of thy covenant I have sent forth thy prisoners out of the pit wherein is no water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 12, E'Turn you to the strong hold, ye prisoners of hope: even to day do I declare that I will render double unto thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 13, E'When I have bent Judah for me, filled the bow with Ephraim, and raised up thy sons, O Zion, against thy sons, O Greece, and made thee as the sword of a mighty man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 14, E'And the LORD shall be seen over them, and his arrow shall go forth as the lightning: and the LORD God shall blow the trumpet, and shall go with whirlwinds of the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 15, E'The LORD of hosts shall defend them; and they shall devour, and subdue with sling stones; and they shall drink, and make a noise as through wine; and they shall be filled like bowls, and as the corners of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 16, E'And the LORD their God shall save them in that day as the flock of his people: for they shall be as the stones of a crown, lifted up as an ensign upon his land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 9, 17, E'For how great is his goodness, and how great is his beauty! corn shall make the young men cheerful, and new wine the maids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 1, E'Ask ye of the LORD rain in the time of the latter rain; so the LORD shall make bright clouds, and give them showers of rain, to every one grass in the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 2, E'For the idols have spoken vanity, and the diviners have seen a lie, and have told false dreams; they comfort in vain: therefore they went their way as a flock, they were troubled, because there was no shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 3, E'Mine anger was kindled against the shepherds, and I punished the goats: for the LORD of hosts hath visited his flock the house of Judah, and hath made them as his goodly horse in the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 4, E'Out of him came forth the corner, out of him the nail, out of him the battle bow, out of him every oppressor together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 5, E'And they shall be as mighty men, which tread down their enemies in the mire of the streets in the battle: and they shall fight, because the LORD is with them, and the riders on horses shall be confounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 6, E'And I will strengthen the house of Judah, and I will save the house of Joseph, and I will bring them again to place them; for I have mercy upon them: and they shall be as though I had not cast them off: for I am the LORD their God, and will hear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 7, E'And they of Ephraim shall be like a mighty man, and their heart shall rejoice as through wine: yea, their children shall see it, and be glad; their heart shall rejoice in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 8, E'I will hiss for them, and gather them; for I have redeemed them: and they shall increase as they have increased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 9, E'And I will sow them among the people: and they shall remember me in far countries; and they shall live with their children, and turn again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 10, E'I will bring them again also out of the land of Egypt, and gather them out of Assyria; and I will bring them into the land of Gilead and Lebanon; and place shall not be found for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 11, E'And he shall pass through the sea with affliction, and shall smite the waves in the sea, and all the deeps of the river shall dry up: and the pride of Assyria shall be brought down, and the sceptre of Egypt shall depart away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 10, 12, E'And I will strengthen them in the LORD; and they shall walk up and down in his name, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 1, E'Open thy doors, O Lebanon, that the fire may devour thy cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 2, E'Howl, fir tree; for the cedar is fallen; because the mighty are spoiled: howl, O ye oaks of Bashan; for the forest of the vintage is come down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 3, E'There is a voice of the howling of the shepherds; for their glory is spoiled: a voice of the roaring of young lions; for the pride of Jordan is spoiled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 4, E'Thus saith the LORD my God; Feed the flock of the slaughter;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 5, E'Whose possessors slay them, and hold themselves not guilty: and they that sell them say, Blessed be the LORD; for I am rich: and their own shepherds pity them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 6, E'For I will no more pity the inhabitants of the land, saith the LORD: but, lo, I will deliver the men every one into his neighbourâ€™s hand, and into the hand of his king: and they shall smite the land, and out of their hand I will not deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 7, E'And I will feed the flock of slaughter, even you, O poor of the flock. And I took unto me two staves; the one I called Beauty, and the other I called Bands; and I fed the flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 8, E'Three shepherds also I cut off in one month; and my soul lothed them, and their soul also abhorred me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 9, E'Then said I, I will not feed you: that that dieth, let it die; and that that is to be cut off, let it be cut off; and let the rest eat every one the flesh of another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 10, E'And I took my staff, even Beauty, and cut it asunder, that I might break my covenant which I had made with all the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 11, E'And it was broken in that day: and so the poor of the flock that waited upon me knew that it was the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 12, E'And I said unto them, If ye think good, give me my price; and if not, forbear. So they weighed for my price thirty pieces of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 13, E'And the LORD said unto me, Cast it unto the potter: a goodly price that I was prised at of them. And I took the thirty pieces of silver, and cast them to the potter in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 14, E'Then I cut asunder mine other staff, even Bands, that I might break the brotherhood between Judah and Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 15, E'And the LORD said unto me, Take unto thee yet the instruments of a foolish shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 16, E'For, lo, I will raise up a shepherd in the land, which shall not visit those that be cut off, neither shall seek the young one, nor heal that that is broken, nor feed that that standeth still: but he shall eat the flesh of the fat, and tear their claws in pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 11, 17, E'Woe to the idol shepherd that leaveth the flock! the sword shall be upon his arm, and upon his right eye: his arm shall be clean dried up, and his right eye shall be utterly darkened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 1, E'The burden of the word of the LORD for Israel, saith the LORD, which stretcheth forth the heavens, and layeth the foundation of the earth, and formeth the spirit of man within him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 2, E'Behold, I will make Jerusalem a cup of trembling unto all the people round about, when they shall be in the siege both against Judah and against Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 3, E'And in that day will I make Jerusalem a burdensome stone for all people: all that burden themselves with it shall be cut in pieces, though all the people of the earth be gathered together against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 4, E'In that day, saith the LORD, I will smite every horse with astonishment, and his rider with madness: and I will open mine eyes upon the house of Judah, and will smite every horse of the people with blindness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 5, E'And the governors of Judah shall say in their heart, The inhabitants of Jerusalem shall be my strength in the LORD of hosts their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 6, E'In that day will I make the governors of Judah like an hearth of fire among the wood, and like a torch of fire in a sheaf; and they shall devour all the people round about, on the right hand and on the left: and Jerusalem shall be inhabited again in her own place, even in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 7, E'The LORD also shall save the tents of Judah first, that the glory of the house of David and the glory of the inhabitants of Jerusalem do not magnify themselves against Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 8, E'In that day shall the LORD defend the inhabitants of Jerusalem; and he that is feeble among them at that day shall be as David; and the house of David shall be as God, as the angel of the LORD before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 9, E'And it shall come to pass in that day, that I will seek to destroy all the nations that come against Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 10, E'And I will pour upon the house of David, and upon the inhabitants of Jerusalem, the spirit of grace and of supplications: and they shall look upon me whom they have pierced, and they shall mourn for him, as one mourneth for his only son, and shall be in bitterness for him, as one that is in bitterness for his firstborn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 11, E'In that day shall there be a great mourning in Jerusalem, as the mourning of Hadadrimmon in the valley of Megiddon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 12, E'And the land shall mourn, every family apart; the family of the house of David apart, and their wives apart; the family of the house of Nathan apart, and their wives apart;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 13, E'The family of the house of Levi apart, and their wives apart; the family of Shimei apart, and their wives apart;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 12, 14, E'All the families that remain, every family apart, and their wives apart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 1, E'In that day there shall be a fountain opened to the house of David and to the inhabitants of Jerusalem for sin and for uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 2, E'And it shall come to pass in that day, saith the LORD of hosts, that I will cut off the names of the idols out of the land, and they shall no more be remembered: and also I will cause the prophets and the unclean spirit to pass out of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 3, E'And it shall come to pass, that when any shall yet prophesy, then his father and his mother that begat him shall say unto him, Thou shalt not live; for thou speakest lies in the name of the LORD: and his father and his mother that begat him shall thrust him through when he prophesieth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 4, E'And it shall come to pass in that day, that the prophets shall be ashamed every one of his vision, when he hath prophesied; neither shall they wear a rough garment to deceive:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 5, E'But he shall say, I am no prophet, I am an husbandman; for man taught me to keep cattle from my youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 6, E'And one shall say unto him, What are these wounds in thine hands? Then he shall answer, Those with which I was wounded in the house of my friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 7, E'Awake, O sword, against my shepherd, and against the man that is my fellow, saith the LORD of hosts: smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 8, E'And it shall come to pass, that in all the land, saith the LORD, two parts therein shall be cut off and die; but the third shall be left therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 13, 9, E'And I will bring the third part through the fire, and will refine them as silver is refined, and will try them as gold is tried: they shall call on my name, and I will hear them: I will say, It is my people: and they shall say, The LORD is my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 1, E'Behold, the day of the LORD cometh, and thy spoil shall be divided in the midst of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 2, E'For I will gather all nations against Jerusalem to battle; and the city shall be taken, and the houses rifled, and the women ravished; and half of the city shall go forth into captivity, and the residue of the people shall not be cut off from the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 3, E'Then shall the LORD go forth, and fight against those nations, as when he fought in the day of battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 4, E'And his feet shall stand in that day upon the mount of Olives, which is before Jerusalem on the east, and the mount of Olives shall cleave in the midst thereof toward the east and toward the west, and there shall be a very great valley; and half of the mountain shall remove toward the north, and half of it toward the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 5, E'And ye shall flee to the valley of the mountains; for the valley of the mountains shall reach unto Azal: yea, ye shall flee, like as ye fled from before the earthquake in the days of Uzziah king of Judah: and the LORD my God shall come, and all the saints with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 6, E'And it shall come to pass in that day, that the light shall not be clear, nor dark:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 7, E'But it shall be one day which shall be known to the LORD, not day, nor night: but it shall come to pass, that at evening time it shall be light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 8, E'And it shall be in that day, that living waters shall go out from Jerusalem; half of them toward the former sea, and half of them toward the hinder sea: in summer and in winter shall it be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 9, E'And the LORD shall be king over all the earth: in that day shall there be one LORD, and his name one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 10, E'All the land shall be turned as a plain from Geba to Rimmon south of Jerusalem: and it shall be lifted up, and inhabited in her place, from Benjaminâ€™s gate unto the place of the first gate, unto the corner gate, and from the tower of Hananeel unto the kingâ€™s winepresses.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Zechariah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 11, E'And men shall dwell in it, and there shall be no more utter destruction; but Jerusalem shall be safely inhabited.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 12, E'And this shall be the plague wherewith the LORD will smite all the people that have fought against Jerusalem; Their flesh shall consume away while they stand upon their feet, and their eyes shall consume away in their holes, and their tongue shall consume away in their mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 13, E'And it shall come to pass in that day, that a great tumult from the LORD shall be among them; and they shall lay hold every one on the hand of his neighbour, and his hand shall rise up against the hand of his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 14, E'And Judah also shall fight at Jerusalem; and the wealth of all the heathen round about shall be gathered together, gold, and silver, and apparel, in great abundance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 15, E'And so shall be the plague of the horse, of the mule, of the camel, and of the ass, and of all the beasts that shall be in these tents, as this plague.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 16, E'And it shall come to pass, that every one that is left of all the nations which came against Jerusalem shall even go up from year to year to worship the King, the LORD of hosts, and to keep the feast of tabernacles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 17, E'And it shall be, that whoso will not come up of all the families of the earth unto Jerusalem to worship the King, the LORD of hosts, even upon them shall be no rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 18, E'And if the family of Egypt go not up, and come not, that have no rain; there shall be the plague, wherewith the LORD will smite the heathen that come not up to keep the feast of tabernacles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 19, E'This shall be the punishment of Egypt, and the punishment of all nations that come not up to keep the feast of tabernacles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 20, E'In that day shall there be upon the bells of the horses, HOLINESS UNTO THE LORD; and the pots in the LORDâ€™s house shall be like the bowls before the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '0f07dd5a-af04-47a8-bb9b-5cede1037e79', 14, 21, E'Yea, every pot in Jerusalem and in Judah shall be holiness unto the LORD of hosts: and all they that sacrifice shall come and take of them, and seethe therein: and in that day there shall be no more the Canaanite in the house of the LORD of hosts.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Zechariah') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 1, E'The burden of the word of the LORD to Israel by Malachi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 2, E'I have loved you, saith the LORD. Yet ye say, Wherein hast thou loved us? Was not Esau Jacobâ€™s brother? saith the LORD: yet I loved Jacob,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 3, E'And I hated Esau, and laid his mountains and his heritage waste for the dragons of the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 4, E'Whereas Edom saith, We are impoverished, but we will return and build the desolate places; thus saith the LORD of hosts, They shall build, but I will throw down; and they shall call them, The border of wickedness, and, The people against whom the LORD hath indignation for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 5, E'And your eyes shall see, and ye shall say, The LORD will be magnified from the border of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 6, E'A son honoureth his father, and a servant his master: if then I be a father, where is mine honour? and if I be a master, where is my fear? saith the LORD of hosts unto you, O priests, that despise my name. And ye say, Wherein have we despised thy name?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 7, E'Ye offer polluted bread upon mine altar; and ye say, Wherein have we polluted thee? In that ye say, The table of the LORD is contemptible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 8, E'And if ye offer the blind for sacrifice, is it not evil? and if ye offer the lame and sick, is it not evil? offer it now unto thy governor; will he be pleased with thee, or accept thy person? saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 9, E'And now, I pray you, beseech God that he will be gracious unto us: this hath been by your means: will he regard your persons? saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 10, E'Who is there even among you that would shut the doors for nought? neither do ye kindle fire on mine altar for nought. I have no pleasure in you, saith the LORD of hosts, neither will I accept an offering at your hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 11, E'For from the rising of the sun even unto the going down of the same my name shall be great among the Gentiles; and in every place incense shall be offered unto my name, and a pure offering: for my name shall be great among the heathen, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 12, E'But ye have profaned it, in that ye say, The table of the LORD is polluted; and the fruit thereof, even his meat, is contemptible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 13, E'Ye said also, Behold, what a weariness is it! and ye have snuffed at it, saith the LORD of hosts; and ye brought that which was torn, and the lame, and the sick; thus ye brought an offering: should I accept this of your hand? saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 1, 14, E'But cursed be the deceiver, which hath in his flock a male, and voweth, and sacrificeth unto the LORD a corrupt thing: for I am a great King, saith the LORD of hosts, and my name is dreadful among the heathen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 1, E'And now, O ye priests, this commandment is for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 2, E'If ye will not hear, and if ye will not lay it to heart, to give glory unto my name, saith the LORD of hosts, I will even send a curse upon you, and I will curse your blessings: yea, I have cursed them already, because ye do not lay it to heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 3, E'Behold, I will corrupt your seed, and spread dung upon your faces, even the dung of your solemn feasts; and one shall take you away with it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 4, E'And ye shall know that I have sent this commandment unto you, that my covenant might be with Levi, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 5, E'My covenant was with him of life and peace; and I gave them to him for the fear wherewith he feared me, and was afraid before my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 6, E'The law of truth was in his mouth, and iniquity was not found in his lips: he walked with me in peace and equity, and did turn many away from iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 7, E'For the priestâ€™s lips should keep knowledge, and they should seek the law at his mouth: for he is the messenger of the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 8, E'But ye are departed out of the way; ye have caused many to stumble at the law; ye have corrupted the covenant of Levi, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 9, E'Therefore have I also made you contemptible and base before all the people, according as ye have not kept my ways, but have been partial in the law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 10, E'Have we not all one father? hath not one God created us? why do we deal treacherously every man against his brother, by profaning the covenant of our fathers?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 11, E'Judah hath dealt treacherously, and an abomination is committed in Israel and in Jerusalem; for Judah hath profaned the holiness of the LORD which he loved, and hath married the daughter of a strange god.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 12, E'The LORD will cut off the man that doeth this, the master and the scholar, out of the tabernacles of Jacob, and him that offereth an offering unto the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 13, E'And this have ye done again, covering the altar of the LORD with tears, with weeping, and with crying out, insomuch that he regardeth not the offering any more, or receiveth it with good will at your hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 14, E'Yet ye say, Wherefore? Because the LORD hath been witness between thee and the wife of thy youth, against whom thou hast dealt treacherously: yet is she thy companion, and the wife of thy covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 15, E'And did not he make one? Yet had he the residue of the spirit. And wherefore one? That he might seek a godly seed. Therefore take heed to your spirit, and let none deal treacherously against the wife of his youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 16, E'For the LORD, the God of Israel, saith that he hateth putting away: for one covereth violence with his garment, saith the LORD of hosts: therefore take heed to your spirit, that ye deal not treacherously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 2, 17, E'Ye have wearied the LORD with your words. Yet ye say, Wherein have we wearied him? When ye say, Every one that doeth evil is good in the sight of the LORD, and he delighteth in them; or, Where is the God of judgment?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 1, E'Behold, I will send my messenger, and he shall prepare the way before me: and the LORD, whom ye seek, shall suddenly come to his temple, even the messenger of the covenant, whom ye delight in: behold, he shall come, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 2, E'But who may abide the day of his coming? and who shall stand when he appeareth? for he is like a refinerâ€™s fire, and like fullersâ€™ soap:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 3, E'And he shall sit as a refiner and purifier of silver: and he shall purify the sons of Levi, and purge them as gold and silver, that they may offer unto the LORD an offering in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 4, E'Then shall the offering of Judah and Jerusalem be pleasant unto the LORD, as in the days of old, and as in former years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 5, E'And I will come near to you to judgment; and I will be a swift witness against the sorcerers, and against the adulterers, and against false swearers, and against those that oppress the hireling in his wages, the widow, and the fatherless, and that turn aside the stranger from his right, and fear not me, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 6, E'For I am the LORD, I change not; therefore ye sons of Jacob are not consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 7, E'Even from the days of your fathers ye are gone away from mine ordinances, and have not kept them. Return unto me, and I will return unto you, saith the LORD of hosts. But ye said, Wherein shall we return?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 8, E'Will a man rob God? Yet ye have robbed me. But ye say, Wherein have we robbed thee? In tithes and offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 9, E'Ye are cursed with a curse: for ye have robbed me, even this whole nation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 10, E'Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 11, E'And I will rebuke the devourer for your sakes, and he shall not destroy the fruits of your ground; neither shall your vine cast her fruit before the time in the field, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 12, E'And all nations shall call you blessed: for ye shall be a delightsome land, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 13, E'Your words have been stout against me, saith the LORD. Yet ye say, What have we spoken so much against thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 14, E'Ye have said, It is vain to serve God: and what profit is it that we have kept his ordinance, and that we have walked mournfully before the LORD of hosts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 15, E'And now we call the proud happy; yea, they that work wickedness are set up; yea, they that tempt God are even delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 16, E'Then they that feared the LORD spake often one to another: and the LORD hearkened, and heard it, and a book of remembrance was written before him for them that feared the LORD, and that thought upon his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 17, E'And they shall be mine, saith the LORD of hosts, in that day when I make up my jewels; and I will spare them, as a man spareth his own son that serveth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 3, 18, E'Then shall ye return, and discern between the righteous and the wicked, between him that serveth God and him that serveth him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 4, 1, E'For, behold, the day cometh, that shall burn as an oven; and all the proud, yea, and all that do wickedly, shall be stubble: and the day that cometh shall burn them up, saith the LORD of hosts, that it shall leave them neither root nor branch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 4, 2, E'But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 4, 3, E'And ye shall tread down the wicked; for they shall be ashes under the soles of your feet in the day that I shall do this, saith the LORD of hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 4, 4, E'Remember ye the law of Moses my servant, which I commanded unto him in Horeb for all Israel, with the statutes and judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 4, 5, E'Behold, I will send you Elijah the prophet before the coming of the great and dreadful day of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'fdb759af-0714-4535-8be9-8ead7ef564c0', 4, 6, E'And he shall turn the heart of the fathers to the children, and the heart of the children to their fathers, lest I come and smite the earth with a curse.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Malachi') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 1, E'The book of the generation of Jesus Christ, the son of David, the son of Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 2, E'Abraham begat Isaac; and Isaac begat Jacob; and Jacob begat Judas and his brethren;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 3, E'And Judas begat Phares and Zara of Thamar; and Phares begat Esrom; and Esrom begat Aram;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 4, E'And Aram begat Aminadab; and Aminadab begat Naasson; and Naasson begat Salmon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 5, E'And Salmon begat Booz of Rachab; and Booz begat Obed of Ruth; and Obed begat Jesse;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 6, E'And Jesse begat David the king; and David the king begat Solomon of her that had been the wife of Urias;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 7, E'And Solomon begat Roboam; and Roboam begat Abia; and Abia begat Asa;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 8, E'And Asa begat Josaphat; and Josaphat begat Joram; and Joram begat Ozias;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 9, E'And Ozias begat Joatham; and Joatham begat Achaz; and Achaz begat Ezekias;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 10, E'And Ezekias begat Manasses; and Manasses begat Amon; and Amon begat Josias;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 11, E'And Josias begat Jechonias and his brethren, about the time they were carried away to Babylon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 12, E'And after they were brought to Babylon, Jechonias begat Salathiel; and Salathiel begat Zorobabel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 13, E'And Zorobabel begat Abiud; and Abiud begat Eliakim; and Eliakim begat Azor;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 14, E'And Azor begat Sadoc; and Sadoc begat Achim; and Achim begat Eliud;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 15, E'And Eliud begat Eleazar; and Eleazar begat Matthan; and Matthan begat Jacob;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 16, E'And Jacob begat Joseph the husband of Mary, of whom was born Jesus, who is called Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 17, E'So all the generations from Abraham to David are fourteen generations; and from David until the carrying away into Babylon are fourteen generations; and from the carrying away into Babylon unto Christ are fourteen generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 18, E'Now the birth of Jesus Christ was on this wise: When as his mother Mary was espoused to Joseph, before they came together, she was found with child of the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 19, E'Then Joseph her husband, being a just man, and not willing to make her a publick example, was minded to put her away privily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 20, E'But while he thought on these things, behold, the angel of the LORD appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 21, E'And she shall bring forth a son, and thou shalt call his name JESUS: for he shall save his people from their sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 22, E'Now all this was done, that it might be fulfilled which was spoken of the Lord by the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 23, E'Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 24, E'Then Joseph being raised from sleep did as the angel of the Lord had bidden him, and took unto him his wife:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 1, 25, E'And knew her not till she had brought forth her firstborn son: and he called his name JESUS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 1, E'Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 2, E'Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 3, E'When Herod the king had heard these things, he was troubled, and all Jerusalem with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 4, E'And when he had gathered all the chief priests and scribes of the people together, he demanded of them where Christ should be born.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 5, E'And they said unto him, In Bethlehem of Judaea: for thus it is written by the prophet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 6, E'And thou Bethlehem, in the land of Juda, art not the least among the princes of Juda: for out of thee shall come a Governor, that shall rule my people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 7, E'Then Herod, when he had privily called the wise men, enquired of them diligently what time the star appeared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 8, E'And he sent them to Bethlehem, and said, Go and search diligently for the young child; and when ye have found him, bring me word again, that I may come and worship him also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 9, E'When they had heard the king, they departed; and, lo, the star, which they saw in the east, went before them, till it came and stood over where the young child was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 10, E'When they saw the star, they rejoiced with exceeding great joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 11, E'And when they were come into the house, they saw the young child with Mary his mother, and fell down, and worshipped him: and when they had opened their treasures, they presented unto him gifts; gold, and frankincense, and myrrh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 12, E'And being warned of God in a dream that they should not return to Herod, they departed into their own country another way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 13, E'And when they were departed, behold, the angel of the Lord appeareth to Joseph in a dream, saying, Arise, and take the young child and his mother, and flee into Egypt, and be thou there until I bring thee word: for Herod will seek the young child to destroy him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 14, E'When he arose, he took the young child and his mother by night, and departed into Egypt:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 15, E'And was there until the death of Herod: that it might be fulfilled which was spoken of the Lord by the prophet, saying, Out of Egypt have I called my son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 16, E'Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently enquired of the wise men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 17, E'Then was fulfilled that which was spoken by Jeremy the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 18, E'In Rama was there a voice heard, lamentation, and weeping, and great mourning, Rachel weeping for her children, and would not be comforted, because they are not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 19, E'But when Herod was dead, behold, an angel of the Lord appeareth in a dream to Joseph in Egypt,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 20, E'Saying, Arise, and take the young child and his mother, and go into the land of Israel: for they are dead which sought the young childâ€™s life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 21, E'And he arose, and took the young child and his mother, and came into the land of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 22, E'But when he heard that Archelaus did reign in Judaea in the room of his father Herod, he was afraid to go thither: notwithstanding, being warned of God in a dream, he turned aside into the parts of Galilee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 2, 23, E'And he came and dwelt in a city called Nazareth: that it might be fulfilled which was spoken by the prophets, He shall be called a Nazarene.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 1, E'In those days came John the Baptist, preaching in the wilderness of Judaea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 2, E'And saying, Repent ye: for the kingdom of heaven is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 3, E'For this is he that was spoken of by the prophet Esaias, saying, The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 4, E'And the same John had his raiment of camelâ€™s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 5, E'Then went out to him Jerusalem, and all Judaea, and all the region round about Jordan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 6, E'And were baptized of him in Jordan, confessing their sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 7, E'But when he saw many of the Pharisees and Sadducees come to his baptism, he said unto them, O generation of vipers, who hath warned you to flee from the wrath to come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 8, E'Bring forth therefore fruits meet for repentance:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 9, E'And think not to say within yourselves, We have Abraham to our father: for I say unto you, that God is able of these stones to raise up children unto Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 10, E'And now also the axe is laid unto the root of the trees: therefore every tree which bringeth not forth good fruit is hewn down, and cast into the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 11, E'I indeed baptize you with water unto repentance: but he that cometh after me is mightier than I, whose shoes I am not worthy to bear: he shall baptize you with the Holy Ghost, and with fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 12, E'Whose fan is in his hand, and he will throughly purge his floor, and gather his wheat into the garner; but he will burn up the chaff with unquenchable fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 13, E'Then cometh Jesus from Galilee to Jordan unto John, to be baptized of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 14, E'But John forbad him, saying, I have need to be baptized of thee, and comest thou to me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 15, E'And Jesus answering said unto him, Suffer it to be so now: for thus it becometh us to fulfil all righteousness. Then he suffered him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 16, E'And Jesus, when he was baptized, went up straightway out of the water: and, lo, the heavens were opened unto him, and he saw the Spirit of God descending like a dove, and lighting upon him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 3, 17, E'And lo a voice from heaven, saying, This is my beloved Son, in whom I am well pleased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 1, E'Then was Jesus led up of the Spirit into the wilderness to be tempted of the devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 2, E'And when he had fasted forty days and forty nights, he was afterward an hungred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 3, E'And when the tempter came to him, he said, If thou be the Son of God, command that these stones be made bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 4, E'But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 5, E'Then the devil taketh him up into the holy city, and setteth him on a pinnacle of the temple,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 6, E'And saith unto him, If thou be the Son of God, cast thyself down: for it is written, He shall give his angels charge concerning thee: and in their hands they shall bear thee up, lest at any time thou dash thy foot against a stone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 7, E'Jesus said unto him, It is written again, Thou shalt not tempt the Lord thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 8, E'Again, the devil taketh him up into an exceeding high mountain, and sheweth him all the kingdoms of the world, and the glory of them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 9, E'And saith unto him, All these things will I give thee, if thou wilt fall down and worship me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 10, E'Then saith Jesus unto him, Get thee hence, Satan: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 11, E'Then the devil leaveth him, and, behold, angels came and ministered unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 12, E'Now when Jesus had heard that John was cast into prison, he departed into Galilee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 13, E'And leaving Nazareth, he came and dwelt in Capernaum, which is upon the sea coast, in the borders of Zabulon and Nephthalim:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 14, E'That it might be fulfilled which was spoken by Esaias the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 15, E'The land of Zabulon, and the land of Nephthalim, by the way of the sea, beyond Jordan, Galilee of the Gentiles;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 16, E'The people which sat in darkness saw great light; and to them which sat in the region and shadow of death light is sprung up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 17, E'From that time Jesus began to preach, and to say, Repent: for the kingdom of heaven is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 18, E'And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 19, E'And he saith unto them, Follow me, and I will make you fishers of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 20, E'And they straightway left their nets, and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 21, E'And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 22, E'And they immediately left the ship and their father, and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 23, E'And Jesus went about all Galilee, teaching in their synagogues, and preaching the gospel of the kingdom, and healing all manner of sickness and all manner of disease among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 24, E'And his fame went throughout all Syria: and they brought unto him all sick people that were taken with divers diseases and torments, and those which were possessed with devils, and those which were lunatick, and those that had the palsy; and he healed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 4, 25, E'And there followed him great multitudes of people from Galilee, and from Decapolis, and from Jerusalem, and from Judaea, and from beyond Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 1, E'And seeing the multitudes, he went up into a mountain: and when he was set, his disciples came unto him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 2, E'And he opened his mouth, and taught them, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 3, E'Blessed are the poor in spirit: for theirs is the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 4, E'Blessed are they that mourn: for they shall be comforted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 5, E'Blessed are the meek: for they shall inherit the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 6, E'Blessed are they which do hunger and thirst after righteousness: for they shall be filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 7, E'Blessed are the merciful: for they shall obtain mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 8, E'Blessed are the pure in heart: for they shall see God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 9, E'Blessed are the peacemakers: for they shall be called the children of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 10, E'Blessed are they which are persecuted for righteousnessâ€™ sake: for theirs is the kingdom of heaven.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 11, E'Blessed are ye, when men shall revile you, and persecute you, and shall say all manner of evil against you falsely, for my sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 12, E'Rejoice, and be exceeding glad: for great is your reward in heaven: for so persecuted they the prophets which were before you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 13, E'Ye are the salt of the earth: but if the salt have lost his savour, wherewith shall it be salted? it is thenceforth good for nothing, but to be cast out, and to be trodden under foot of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 14, E'Ye are the light of the world. A city that is set on an hill cannot be hid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 15, E'Neither do men light a candle, and put it under a bushel, but on a candlestick; and it giveth light unto all that are in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 16, E'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 17, E'Think not that I am come to destroy the law, or the prophets: I am not come to destroy, but to fulfil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 18, E'For verily I say unto you, Till heaven and earth pass, one jot or one tittle shall in no wise pass from the law, till all be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 19, E'Whosoever therefore shall break one of these least commandments, and shall teach men so, he shall be called the least in the kingdom of heaven: but whosoever shall do and teach them, the same shall be called great in the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 20, E'For I say unto you, That except your righteousness shall exceed the righteousness of the scribes and Pharisees, ye shall in no case enter into the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 21, E'Ye have heard that it was said by them of old time, Thou shalt not kill; and whosoever shall kill shall be in danger of the judgment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 22, E'But I say unto you, That whosoever is angry with his brother without a cause shall be in danger of the judgment: and whosoever shall say to his brother, Raca, shall be in danger of the council: but whosoever shall say, Thou fool, shall be in danger of hell fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 23, E'Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath ought against thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 24, E'Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 25, E'Agree with thine adversary quickly, whiles thou art in the way with him; lest at any time the adversary deliver thee to the judge, and the judge deliver thee to the officer, and thou be cast into prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 26, E'Verily I say unto thee, Thou shalt by no means come out thence, till thou hast paid the uttermost farthing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 27, E'Ye have heard that it was said by them of old time, Thou shalt not commit adultery:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 28, E'But I say unto you, That whosoever looketh on a woman to lust after her hath committed adultery with her already in his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 29, E'And if thy right eye offend thee, pluck it out, and cast it from thee: for it is profitable for thee that one of thy members should perish, and not that thy whole body should be cast into hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 30, E'And if thy right hand offend thee, cut it off, and cast it from thee: for it is profitable for thee that one of thy members should perish, and not that thy whole body should be cast into hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 31, E'It hath been said, Whosoever shall put away his wife, let him give her a writing of divorcement:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 32, E'But I say unto you, That whosoever shall put away his wife, saving for the cause of fornication, causeth her to commit adultery: and whosoever shall marry her that is divorced committeth adultery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 33, E'Again, ye have heard that it hath been said by them of old time, Thou shalt not forswear thyself, but shalt perform unto the Lord thine oaths:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 34, E'But I say unto you, Swear not at all; neither by heaven; for it is Godâ€™s throne:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 35, E'Nor by the earth; for it is his footstool: neither by Jerusalem; for it is the city of the great King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 36, E'Neither shalt thou swear by thy head, because thou canst not make one hair white or black.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 37, E'But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 38, E'Ye have heard that it hath been said, An eye for an eye, and a tooth for a tooth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 39, E'But I say unto you, That ye resist not evil: but whosoever shall smite thee on thy right cheek, turn to him the other also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 40, E'And if any man will sue thee at the law, and take away thy coat, let him have thy cloak also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 41, E'And whosoever shall compel thee to go a mile, go with him twain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 42, E'Give to him that asketh thee, and from him that would borrow of thee turn not thou away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 43, E'Ye have heard that it hath been said, Thou shalt love thy neighbour, and hate thine enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 44, E'But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 45, E'That ye may be the children of your Father which is in heaven: for he maketh his sun to rise on the evil and on the good, and sendeth rain on the just and on the unjust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 46, E'For if ye love them which love you, what reward have ye? do not even the publicans the same?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 47, E'And if ye salute your brethren only, what do ye more than others? do not even the publicans so?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 5, 48, E'Be ye therefore perfect, even as your Father which is in heaven is perfect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 1, E'Take heed that ye do not your alms before men, to be seen of them: otherwise ye have no reward of your Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 2, E'Therefore when thou doest thine alms, do not sound a trumpet before thee, as the hypocrites do in the synagogues and in the streets, that they may have glory of men. Verily I say unto you, They have their reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 3, E'But when thou doest alms, let not thy left hand know what thy right hand doeth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 4, E'That thine alms may be in secret: and thy Father which seeth in secret himself shall reward thee openly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 5, E'And when thou prayest, thou shalt not be as the hypocrites are: for they love to pray standing in the synagogues and in the corners of the streets, that they may be seen of men. Verily I say unto you, They have their reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 6, E'But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 7, E'But when ye pray, use not vain repetitions, as the heathen do: for they think that they shall be heard for their much speaking.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 8, E'Be not ye therefore like unto them: for your Father knoweth what things ye have need of, before ye ask him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 9, E'After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 10, E'Thy kingdom come. Thy will be done in earth, as it is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 11, E'Give us this day our daily bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 12, E'And forgive us our debts, as we forgive our debtors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 13, E'And lead us not into temptation, but deliver us from evil: For thine is the kingdom, and the power, and the glory, for ever. Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 14, E'For if ye forgive men their trespasses, your heavenly Father will also forgive you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 15, E'But if ye forgive not men their trespasses, neither will your Father forgive your trespasses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 16, E'Moreover when ye fast, be not, as the hypocrites, of a sad countenance: for they disfigure their faces, that they may appear unto men to fast. Verily I say unto you, They have their reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 17, E'But thou, when thou fastest, anoint thine head, and wash thy face;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 18, E'That thou appear not unto men to fast, but unto thy Father which is in secret: and thy Father, which seeth in secret, shall reward thee openly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 19, E'Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 20, E'But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 21, E'For where your treasure is, there will your heart be also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 22, E'The light of the body is the eye: if therefore thine eye be single, thy whole body shall be full of light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 23, E'But if thine eye be evil, thy whole body shall be full of darkness. If therefore the light that is in thee be darkness, how great is that darkness!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 24, E'No man can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 25, E'Therefore I say unto you, Take no thought for your life, what ye shall eat, or what ye shall drink; nor yet for your body, what ye shall put on. Is not the life more than meat, and the body than raiment?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 26, E'Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 27, E'Which of you by taking thought can add one cubit unto his stature?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 28, E'And why take ye thought for raiment? Consider the lilies of the field, how they grow; they toil not, neither do they spin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 29, E'And yet I say unto you, That even Solomon in all his glory was not arrayed like one of these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 30, E'Wherefore, if God so clothe the grass of the field, which to day is, and to morrow is cast into the oven, shall he not much more clothe you, O ye of little faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 31, E'Therefore take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 32, E'(For after all these things do the Gentiles seek:) for your heavenly Father knoweth that ye have need of all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 33, E'But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 6, 34, E'Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 1, E'Judge not, that ye be not judged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 2, E'For with what judgment ye judge, ye shall be judged: and with what measure ye mete, it shall be measured to you again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 3, E'And why beholdest thou the mote that is in thy brotherâ€™s eye, but considerest not the beam that is in thine own eye?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 4, E'Or how wilt thou say to thy brother, Let me pull out the mote out of thine eye; and, behold, a beam is in thine own eye?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 5, E'Thou hypocrite, first cast out the beam out of thine own eye; and then shalt thou see clearly to cast out the mote out of thy brotherâ€™s eye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 6, E'Give not that which is holy unto the dogs, neither cast ye your pearls before swine, lest they trample them under their feet, and turn again and rend you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 7, E'Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 8, E'For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 9, E'Or what man is there of you, whom if his son ask bread, will he give him a stone?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 10, E'Or if he ask a fish, will he give him a serpent?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 11, E'If ye then, being evil, know how to give good gifts unto your children, how much more shall your Father which is in heaven give good things to them that ask him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 12, E'Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 13, E'Enter ye in at the strait gate: for wide is the gate, and broad is the way, that leadeth to destruction, and many there be which go in thereat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 14, E'Because strait is the gate, and narrow is the way, which leadeth unto life, and few there be that find it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 15, E'Beware of false prophets, which come to you in sheepâ€™s clothing, but inwardly they are ravening wolves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 16, E'Ye shall know them by their fruits. Do men gather grapes of thorns, or figs of thistles?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 17, E'Even so every good tree bringeth forth good fruit; but a corrupt tree bringeth forth evil fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 18, E'A good tree cannot bring forth evil fruit, neither can a corrupt tree bring forth good fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 19, E'Every tree that bringeth not forth good fruit is hewn down, and cast into the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 20, E'Wherefore by their fruits ye shall know them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 21, E'Not every one that saith unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that doeth the will of my Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 22, E'Many will say to me in that day, Lord, Lord, have we not prophesied in thy name? and in thy name have cast out devils? and in thy name done many wonderful works?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 23, E'And then will I profess unto them, I never knew you: depart from me, ye that work iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 24, E'Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 25, E'And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell not: for it was founded upon a rock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 26, E'And every one that heareth these sayings of mine, and doeth them not, shall be likened unto a foolish man, which built his house upon the sand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 27, E'And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell: and great was the fall of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 28, E'And it came to pass, when Jesus had ended these sayings, the people were astonished at his doctrine:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 7, 29, E'For he taught them as one having authority, and not as the scribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 1, E'When he was come down from the mountain, great multitudes followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 2, E'And, behold, there came a leper and worshipped him, saying, Lord, if thou wilt, thou canst make me clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 3, E'And Jesus put forth his hand, and touched him, saying, I will; be thou clean. And immediately his leprosy was cleansed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 4, E'And Jesus saith unto him, See thou tell no man; but go thy way, shew thyself to the priest, and offer the gift that Moses commanded, for a testimony unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 5, E'And when Jesus was entered into Capernaum, there came unto him a centurion, beseeching him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 6, E'And saying, Lord, my servant lieth at home sick of the palsy, grievously tormented.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 7, E'And Jesus saith unto him, I will come and heal him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 8, E'The centurion answered and said, Lord, I am not worthy that thou shouldest come under my roof: but speak the word only, and my servant shall be healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 9, E'For I am a man under authority, having soldiers under me: and I say to this man, Go, and he goeth; and to another, Come, and he cometh; and to my servant, Do this, and he doeth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 10, E'When Jesus heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 11, E'And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 12, E'But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 13, E'And Jesus said unto the centurion, Go thy way; and as thou hast believed, so be it done unto thee. And his servant was healed in the selfsame hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 14, E'And when Jesus was come into Peterâ€™s house, he saw his wifeâ€™s mother laid, and sick of a fever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 15, E'And he touched her hand, and the fever left her: and she arose, and ministered unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 16, E'When the even was come, they brought unto him many that were possessed with devils: and he cast out the spirits with his word, and healed all that were sick:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 17, E'That it might be fulfilled which was spoken by Esaias the prophet, saying, Himself took our infirmities, and bare our sicknesses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 18, E'Now when Jesus saw great multitudes about him, he gave commandment to depart unto the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 19, E'And a certain scribe came, and said unto him, Master, I will follow thee whithersoever thou goest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 20, E'And Jesus saith unto him, The foxes have holes, and the birds of the air have nests; but the Son of man hath not where to lay his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 21, E'And another of his disciples said unto him, Lord, suffer me first to go and bury my father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 22, E'But Jesus said unto him, Follow me; and let the dead bury their dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 23, E'And when he was entered into a ship, his disciples followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 24, E'And, behold, there arose a great tempest in the sea, insomuch that the ship was covered with the waves: but he was asleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 25, E'And his disciples came to him, and awoke him, saying, Lord, save us: we perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 26, E'And he saith unto them, Why are ye fearful, O ye of little faith? Then he arose, and rebuked the winds and the sea; and there was a great calm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 27, E'But the men marvelled, saying, What manner of man is this, that even the winds and the sea obey him!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 28, E'And when he was come to the other side into the country of the Gergesenes, there met him two possessed with devils, coming out of the tombs, exceeding fierce, so that no man might pass by that way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 29, E'And, behold, they cried out, saying, What have we to do with thee, Jesus, thou Son of God? art thou come hither to torment us before the time?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 30, E'And there was a good way off from them an herd of many swine feeding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 31, E'So the devils besought him, saying, If thou cast us out, suffer us to go away into the herd of swine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 32, E'And he said unto them, Go. And when they were come out, they went into the herd of swine: and, behold, the whole herd of swine ran violently down a steep place into the sea, and perished in the waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 33, E'And they that kept them fled, and went their ways into the city, and told every thing, and what was befallen to the possessed of the devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 8, 34, E'And, behold, the whole city came out to meet Jesus: and when they saw him, they besought him that he would depart out of their coasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 1, E'And he entered into a ship, and passed over, and came into his own city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 2, E'And, behold, they brought to him a man sick of the palsy, lying on a bed: and Jesus seeing their faith said unto the sick of the palsy; Son, be of good cheer; thy sins be forgiven thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 3, E'And, behold, certain of the scribes said within themselves, This man blasphemeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 4, E'And Jesus knowing their thoughts said, Wherefore think ye evil in your hearts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 5, E'For whether is easier, to say, Thy sins be forgiven thee; or to say, Arise, and walk?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 6, E'But that ye may know that the Son of man hath power on earth to forgive sins, (then saith he to the sick of the palsy,) Arise, take up thy bed, and go unto thine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 7, E'And he arose, and departed to his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 8, E'But when the multitudes saw it, they marvelled, and glorified God, which had given such power unto men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 9, E'And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 10, E'And it came to pass, as Jesus sat at meat in the house, behold, many publicans and sinners came and sat down with him and his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 11, E'And when the Pharisees saw it, they said unto his disciples, Why eateth your Master with publicans and sinners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 12, E'But when Jesus heard that, he said unto them, They that be whole need not a physician, but they that are sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 13, E'But go ye and learn what that meaneth, I will have mercy, and not sacrifice: for I am not come to call the righteous, but sinners to repentance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 14, E'Then came to him the disciples of John, saying, Why do we and the Pharisees fast oft, but thy disciples fast not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 15, E'And Jesus said unto them, Can the children of the bridechamber mourn, as long as the bridegroom is with them? but the days will come, when the bridegroom shall be taken from them, and then shall they fast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 16, E'No man putteth a piece of new cloth unto an old garment, for that which is put in to fill it up taketh from the garment, and the rent is made worse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 17, E'Neither do men put new wine into old bottles: else the bottles break, and the wine runneth out, and the bottles perish: but they put new wine into new bottles, and both are preserved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 18, E'While he spake these things unto them, behold, there came a certain ruler, and worshipped him, saying, My daughter is even now dead: but come and lay thy hand upon her, and she shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 19, E'And Jesus arose, and followed him, and so did his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 20, E'And, behold, a woman, which was diseased with an issue of blood twelve years, came behind him, and touched the hem of his garment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 21, E'For she said within herself, If I may but touch his garment, I shall be whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 22, E'But Jesus turned him about, and when he saw her, he said, Daughter, be of good comfort; thy faith hath made thee whole. And the woman was made whole from that hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 23, E'And when Jesus came into the rulerâ€™s house, and saw the minstrels and the people making a noise,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 24, E'He said unto them, Give place: for the maid is not dead, but sleepeth. And they laughed him to scorn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 25, E'But when the people were put forth, he went in, and took her by the hand, and the maid arose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 26, E'And the fame hereof went abroad into all that land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 27, E'And when Jesus departed thence, two blind men followed him, crying, and saying, Thou son of David, have mercy on us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 28, E'And when he was come into the house, the blind men came to him: and Jesus saith unto them, Believe ye that I am able to do this? They said unto him, Yea, Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 29, E'Then touched he their eyes, saying, According to your faith be it unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 30, E'And their eyes were opened; and Jesus straitly charged them, saying, See that no man know it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 31, E'But they, when they were departed, spread abroad his fame in all that country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 32, E'As they went out, behold, they brought to him a dumb man possessed with a devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 33, E'And when the devil was cast out, the dumb spake: and the multitudes marvelled, saying, It was never so seen in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 34, E'But the Pharisees said, He casteth out devils through the prince of the devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 35, E'And Jesus went about all the cities and villages, teaching in their synagogues, and preaching the gospel of the kingdom, and healing every sickness and every disease among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 36, E'But when he saw the multitudes, he was moved with compassion on them, because they fainted, and were scattered abroad, as sheep having no shepherd.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 37, E'Then saith he unto his disciples, The harvest truly is plenteous, but the labourers are few;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 9, 38, E'Pray ye therefore the Lord of the harvest, that he will send forth labourers into his harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 1, E'And when he had called unto him his twelve disciples, he gave them power against unclean spirits, to cast them out, and to heal all manner of sickness and all manner of disease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 2, E'Now the names of the twelve apostles are these; The first, Simon, who is called Peter, and Andrew his brother; James the son of Zebedee, and John his brother;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 3, E'Philip, and Bartholomew; Thomas, and Matthew the publican; James the son of Alphaeus, and Lebbaeus, whose surname was Thaddaeus;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 4, E'Simon the Canaanite, and Judas Iscariot, who also betrayed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 5, E'These twelve Jesus sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 6, E'But go rather to the lost sheep of the house of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 7, E'And as ye go, preach, saying, The kingdom of heaven is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 8, E'Heal the sick, cleanse the lepers, raise the dead, cast out devils: freely ye have received, freely give.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 9, E'Provide neither gold, nor silver, nor brass in your purses,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 10, E'Nor scrip for your journey, neither two coats, neither shoes, nor yet staves: for the workman is worthy of his meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 11, E'And into whatsoever city or town ye shall enter, enquire who in it is worthy; and there abide till ye go thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 12, E'And when ye come into an house, salute it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 13, E'And if the house be worthy, let your peace come upon it: but if it be not worthy, let your peace return to you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 14, E'And whosoever shall not receive you, nor hear your words, when ye depart out of that house or city, shake off the dust of your feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 15, E'Verily I say unto you, It shall be more tolerable for the land of Sodom and Gomorrha in the day of judgment, than for that city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 16, E'Behold, I send you forth as sheep in the midst of wolves: be ye therefore wise as serpents, and harmless as doves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 17, E'But beware of men: for they will deliver you up to the councils, and they will scourge you in their synagogues;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 18, E'And ye shall be brought before governors and kings for my sake, for a testimony against them and the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 19, E'But when they deliver you up, take no thought how or what ye shall speak: for it shall be given you in that same hour what ye shall speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 20, E'For it is not ye that speak, but the Spirit of your Father which speaketh in you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 21, E'And the brother shall deliver up the brother to death, and the father the child: and the children shall rise up against their parents, and cause them to be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 22, E'And ye shall be hated of all men for my nameâ€™s sake: but he that endureth to the end shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 23, E'But when they persecute you in this city, flee ye into another: for verily I say unto you, Ye shall not have gone over the cities of Israel, till the Son of man be come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 24, E'The disciple is not above his master, nor the servant above his lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 25, E'It is enough for the disciple that he be as his master, and the servant as his lord. If they have called the master of the house Beelzebub, how much more shall they call them of his household?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 26, E'Fear them not therefore: for there is nothing covered, that shall not be revealed; and hid, that shall not be known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 27, E'What I tell you in darkness, that speak ye in light: and what ye hear in the ear, that preach ye upon the housetops.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 28, E'And fear not them which kill the body, but are not able to kill the soul: but rather fear him which is able to destroy both soul and body in hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 29, E'Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 30, E'But the very hairs of your head are all numbered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 31, E'Fear ye not therefore, ye are of more value than many sparrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 32, E'Whosoever therefore shall confess me before men, him will I confess also before my Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 33, E'But whosoever shall deny me before men, him will I also deny before my Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 34, E'Think not that I am come to send peace on earth: I came not to send peace, but a sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 35, E'For I am come to set a man at variance against his father, and the daughter against her mother, and the daughter in law against her mother in law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 36, E'And a manâ€™s foes shall be they of his own household.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 37, E'He that loveth father or mother more than me is not worthy of me: and he that loveth son or daughter more than me is not worthy of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 38, E'And he that taketh not his cross, and followeth after me, is not worthy of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 39, E'He that findeth his life shall lose it: and he that loseth his life for my sake shall find it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 40, E'He that receiveth you receiveth me, and he that receiveth me receiveth him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 41, E'He that receiveth a prophet in the name of a prophet shall receive a prophetâ€™s reward; and he that receiveth a righteous man in the name of a righteous man shall receive a righteous manâ€™s reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 10, 42, E'And whosoever shall give to drink unto one of these little ones a cup of cold water only in the name of a disciple, verily I say unto you, he shall in no wise lose his reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 1, E'And it came to pass, when Jesus had made an end of commanding his twelve disciples, he departed thence to teach and to preach in their cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 2, E'Now when John had heard in the prison the works of Christ, he sent two of his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 3, E'And said unto him, Art thou he that should come, or do we look for another?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 4, E'Jesus answered and said unto them, Go and shew John again those things which ye do hear and see:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 5, E'The blind receive their sight, and the lame walk, the lepers are cleansed, and the deaf hear, the dead are raised up, and the poor have the gospel preached to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 6, E'And blessed is he, whosoever shall not be offended in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 7, E'And as they departed, Jesus began to say unto the multitudes concerning John, What went ye out into the wilderness to see? A reed shaken with the wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 8, E'But what went ye out for to see? A man clothed in soft raiment? behold, they that wear soft clothing are in kingsâ€™ houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 9, E'But what went ye out for to see? A prophet? yea, I say unto you, and more than a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 10, E'For this is he, of whom it is written, Behold, I send my messenger before thy face, which shall prepare thy way before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 11, E'Verily I say unto you, Among them that are born of women there hath not risen a greater than John the Baptist: notwithstanding he that is least in the kingdom of heaven is greater than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 12, E'And from the days of John the Baptist until now the kingdom of heaven suffereth violence, and the violent take it by force.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 13, E'For all the prophets and the law prophesied until John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 14, E'And if ye will receive it, this is Elias, which was for to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 15, E'He that hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 16, E'But whereunto shall I liken this generation? It is like unto children sitting in the markets, and calling unto their fellows,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 17, E'And saying, We have piped unto you, and ye have not danced; we have mourned unto you, and ye have not lamented.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 18, E'For John came neither eating nor drinking, and they say, He hath a devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 19, E'The Son of man came eating and drinking, and they say, Behold a man gluttonous, and a winebibber, a friend of publicans and sinners. But wisdom is justified of her children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 20, E'Then began he to upbraid the cities wherein most of his mighty works were done, because they repented not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 21, E'Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works, which were done in you, had been done in Tyre and Sidon, they would have repented long ago in sackcloth and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 22, E'But I say unto you, It shall be more tolerable for Tyre and Sidon at the day of judgment, than for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 23, E'And thou, Capernaum, which art exalted unto heaven, shalt be brought down to hell: for if the mighty works, which have been done in thee, had been done in Sodom, it would have remained until this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 24, E'But I say unto you, That it shall be more tolerable for the land of Sodom in the day of judgment, than for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 25, E'At that time Jesus answered and said, I thank thee, O Father, Lord of heaven and earth, because thou hast hid these things from the wise and prudent, and hast revealed them unto babes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 26, E'Even so, Father: for so it seemed good in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 27, E'All things are delivered unto me of my Father: and no man knoweth the Son, but the Father; neither knoweth any man the Father, save the Son, and he to whomsoever the Son will reveal him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 28, E'Come unto me, all ye that labour and are heavy laden, and I will give you rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 29, E'Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 11, 30, E'For my yoke is easy, and my burden is light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 1, E'At that time Jesus went on the sabbath day through the corn; and his disciples were an hungred, and began to pluck the ears of corn, and to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 2, E'But when the Pharisees saw it, they said unto him, Behold, thy disciples do that which is not lawful to do upon the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 3, E'But he said unto them, Have ye not read what David did, when he was an hungred, and they that were with him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 4, E'How he entered into the house of God, and did eat the shewbread, which was not lawful for him to eat, neither for them which were with him, but only for the priests?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 5, E'Or have ye not read in the law, how that on the sabbath days the priests in the temple profane the sabbath, and are blameless?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 6, E'But I say unto you, That in this place is one greater than the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 7, E'But if ye had known what this meaneth, I will have mercy, and not sacrifice, ye would not have condemned the guiltless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 8, E'For the Son of man is Lord even of the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 9, E'And when he was departed thence, he went into their synagogue:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 10, E'And, behold, there was a man which had his hand withered. And they asked him, saying, Is it lawful to heal on the sabbath days? that they might accuse him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 11, E'And he said unto them, What man shall there be among you, that shall have one sheep, and if it fall into a pit on the sabbath day, will he not lay hold on it, and lift it out?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 12, E'How much then is a man better than a sheep? Wherefore it is lawful to do well on the sabbath days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 13, E'Then saith he to the man, Stretch forth thine hand. And he stretched it forth; and it was restored whole, like as the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 14, E'Then the Pharisees went out, and held a council against him, how they might destroy him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 15, E'But when Jesus knew it, he withdrew himself from thence: and great multitudes followed him, and he healed them all;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 16, E'And charged them that they should not make him known:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 17, E'That it might be fulfilled which was spoken by Esaias the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 18, E'Behold my servant, whom I have chosen; my beloved, in whom my soul is well pleased: I will put my spirit upon him, and he shall shew judgment to the Gentiles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 19, E'He shall not strive, nor cry; neither shall any man hear his voice in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 20, E'A bruised reed shall he not break, and smoking flax shall he not quench, till he send forth judgment unto victory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 21, E'And in his name shall the Gentiles trust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 22, E'Then was brought unto him one possessed with a devil, blind, and dumb: and he healed him, insomuch that the blind and dumb both spake and saw.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 23, E'And all the people were amazed, and said, Is not this the son of David?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 24, E'But when the Pharisees heard it, they said, This fellow doth not cast out devils, but by Beelzebub the prince of the devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 25, E'And Jesus knew their thoughts, and said unto them, Every kingdom divided against itself is brought to desolation; and every city or house divided against itself shall not stand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 26, E'And if Satan cast out Satan, he is divided against himself; how shall then his kingdom stand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 27, E'And if I by Beelzebub cast out devils, by whom do your children cast them out? therefore they shall be your judges.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 28, E'But if I cast out devils by the Spirit of God, then the kingdom of God is come unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 29, E'Or else how can one enter into a strong manâ€™s house, and spoil his goods, except he first bind the strong man? and then he will spoil his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 30, E'He that is not with me is against me; and he that gathereth not with me scattereth abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 31, E'Wherefore I say unto you, All manner of sin and blasphemy shall be forgiven unto men: but the blasphemy against the Holy Ghost shall not be forgiven unto men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 32, E'And whosoever speaketh a word against the Son of man, it shall be forgiven him: but whosoever speaketh against the Holy Ghost, it shall not be forgiven him, neither in this world, neither in the world to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 33, E'Either make the tree good, and his fruit good; or else make the tree corrupt, and his fruit corrupt: for the tree is known by his fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 34, E'O generation of vipers, how can ye, being evil, speak good things? for out of the abundance of the heart the mouth speaketh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 35, E'A good man out of the good treasure of the heart bringeth forth good things: and an evil man out of the evil treasure bringeth forth evil things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 36, E'But I say unto you, That every idle word that men shall speak, they shall give account thereof in the day of judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 37, E'For by thy words thou shalt be justified, and by thy words thou shalt be condemned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 38, E'Then certain of the scribes and of the Pharisees answered, saying, Master, we would see a sign from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 39, E'But he answered and said unto them, An evil and adulterous generation seeketh after a sign; and there shall no sign be given to it, but the sign of the prophet Jonas:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 40, E'For as Jonas was three days and three nights in the whaleâ€™s belly; so shall the Son of man be three days and three nights in the heart of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 41, E'The men of Nineveh shall rise in judgment with this generation, and shall condemn it: because they repented at the preaching of Jonas; and, behold, a greater than Jonas is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 42, E'The queen of the south shall rise up in the judgment with this generation, and shall condemn it: for she came from the uttermost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 43, E'When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest, and findeth none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 44, E'Then he saith, I will return into my house from whence I came out; and when he is come, he findeth it empty, swept, and garnished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 45, E'Then goeth he, and taketh with himself seven other spirits more wicked than himself, and they enter in and dwell there: and the last state of that man is worse than the first. Even so shall it be also unto this wicked generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 46, E'While he yet talked to the people, behold, his mother and his brethren stood without, desiring to speak with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 47, E'Then one said unto him, Behold, thy mother and thy brethren stand without, desiring to speak with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 48, E'But he answered and said unto him that told him, Who is my mother? and who are my brethren?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 49, E'And he stretched forth his hand toward his disciples, and said, Behold my mother and my brethren!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 12, 50, E'For whosoever shall do the will of my Father which is in heaven, the same is my brother, and sister, and mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 1, E'The same day went Jesus out of the house, and sat by the sea side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 2, E'And great multitudes were gathered together unto him, so that he went into a ship, and sat; and the whole multitude stood on the shore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 3, E'And he spake many things unto them in parables, saying, Behold, a sower went forth to sow;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 4, E'And when he sowed, some seeds fell by the way side, and the fowls came and devoured them up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 5, E'Some fell upon stony places, where they had not much earth: and forthwith they sprung up, because they had no deepness of earth:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 6, E'And when the sun was up, they were scorched; and because they had no root, they withered away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 7, E'And some fell among thorns; and the thorns sprung up, and choked them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 8, E'But other fell into good ground, and brought forth fruit, some an hundredfold, some sixtyfold, some thirtyfold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 9, E'Who hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 10, E'And the disciples came, and said unto him, Why speakest thou unto them in parables?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 11, E'He answered and said unto them, Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 12, E'For whosoever hath, to him shall be given, and he shall have more abundance: but whosoever hath not, from him shall be taken away even that he hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 13, E'Therefore speak I to them in parables: because they seeing see not; and hearing they hear not, neither do they understand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 14, E'And in them is fulfilled the prophecy of Esaias, which saith, By hearing ye shall hear, and shall not understand; and seeing ye shall see, and shall not perceive:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 15, E'For this peopleâ€™s heart is waxed gross, and their ears are dull of hearing, and their eyes they have closed; lest at any time they should see with their eyes and hear with their ears, and should understand with their heart, and should be converted, and I should heal them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 16, E'But blessed are your eyes, for they see: and your ears, for they hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 17, E'For verily I say unto you, That many prophets and righteous men have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 18, E'Hear ye therefore the parable of the sower.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 19, E'When any one heareth the word of the kingdom, and understandeth it not, then cometh the wicked one, and catcheth away that which was sown in his heart. This is he which received seed by the way side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 20, E'But he that received the seed into stony places, the same is he that heareth the word, and anon with joy receiveth it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 21, E'Yet hath he not root in himself, but dureth for a while: for when tribulation or persecution ariseth because of the word, by and by he is offended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 22, E'He also that received seed among the thorns is he that heareth the word; and the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 23, E'But he that received seed into the good ground is he that heareth the word, and understandeth it; which also beareth fruit, and bringeth forth, some an hundredfold, some sixty, some thirty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 24, E'Another parable put he forth unto them, saying, The kingdom of heaven is likened unto a man which sowed good seed in his field:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 25, E'But while men slept, his enemy came and sowed tares among the wheat, and went his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 26, E'But when the blade was sprung up, and brought forth fruit, then appeared the tares also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 27, E'So the servants of the householder came and said unto him, Sir, didst not thou sow good seed in thy field? from whence then hath it tares?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 28, E'He said unto them, An enemy hath done this. The servants said unto him, Wilt thou then that we go and gather them up?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 29, E'But he said, Nay; lest while ye gather up the tares, ye root up also the wheat with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 30, E'Let both grow together until the harvest: and in the time of harvest I will say to the reapers, Gather ye together first the tares, and bind them in bundles to burn them: but gather the wheat into my barn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 31, E'Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 32, E'Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 33, E'Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 34, E'All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 35, E'That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 36, E'Then Jesus sent the multitude away, and went into the house: and his disciples came unto him, saying, Declare unto us the parable of the tares of the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 37, E'He answered and said unto them, He that soweth the good seed is the Son of man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 38, E'The field is the world; the good seed are the children of the kingdom; but the tares are the children of the wicked one;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 39, E'The enemy that sowed them is the devil; the harvest is the end of the world; and the reapers are the angels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 40, E'As therefore the tares are gathered and burned in the fire; so shall it be in the end of this world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 41, E'The Son of man shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 42, E'And shall cast them into a furnace of fire: there shall be wailing and gnashing of teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 43, E'Then shall the righteous shine forth as the sun in the kingdom of their Father. Who hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 44, E'Again, the kingdom of heaven is like unto treasure hid in a field; the which when a man hath found, he hideth, and for joy thereof goeth and selleth all that he hath, and buyeth that field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 45, E'Again, the kingdom of heaven is like unto a merchant man, seeking goodly pearls:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 46, E'Who, when he had found one pearl of great price, went and sold all that he had, and bought it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 47, E'Again, the kingdom of heaven is like unto a net, that was cast into the sea, and gathered of every kind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 48, E'Which, when it was full, they drew to shore, and sat down, and gathered the good into vessels, but cast the bad away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 49, E'So shall it be at the end of the world: the angels shall come forth, and sever the wicked from among the just,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 50, E'And shall cast them into the furnace of fire: there shall be wailing and gnashing of teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 51, E'Jesus saith unto them, Have ye understood all these things? They say unto him, Yea, Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 52, E'Then said he unto them, Therefore every scribe which is instructed unto the kingdom of heaven is like unto a man that is an householder, which bringeth forth out of his treasure things new and old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 53, E'And it came to pass, that when Jesus had finished these parables, he departed thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 54, E'And when he was come into his own country, he taught them in their synagogue, insomuch that they were astonished, and said, Whence hath this man this wisdom, and these mighty works?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 55, E'Is not this the carpenterâ€™s son? is not his mother called Mary? and his brethren, James, and Joses, and Simon, and Judas?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 56, E'And his sisters, are they not all with us? Whence then hath this man all these things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 57, E'And they were offended in him. But Jesus said unto them, A prophet is not without honour, save in his own country, and in his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 13, 58, E'And he did not many mighty works there because of their unbelief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 1, E'At that time Herod the tetrarch heard of the fame of Jesus,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 2, E'And said unto his servants, This is John the Baptist; he is risen from the dead; and therefore mighty works do shew forth themselves in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 3, E'For Herod had laid hold on John, and bound him, and put him in prison for Herodiasâ€™ sake, his brother Philipâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 4, E'For John said unto him, It is not lawful for thee to have her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 5, E'And when he would have put him to death, he feared the multitude, because they counted him as a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 6, E'But when Herodâ€™s birthday was kept, the daughter of Herodias danced before them, and pleased Herod.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 7, E'Whereupon he promised with an oath to give her whatsoever she would ask.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 8, E'And she, being before instructed of her mother, said, Give me here John Baptistâ€™s head in a charger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 9, E'And the king was sorry: nevertheless for the oathâ€™s sake, and them which sat with him at meat, he commanded it to be given her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 10, E'And he sent, and beheaded John in the prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 11, E'And his head was brought in a charger, and given to the damsel: and she brought it to her mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 12, E'And his disciples came, and took up the body, and buried it, and went and told Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 13, E'When Jesus heard of it, he departed thence by ship into a desert place apart: and when the people had heard thereof, they followed him on foot out of the cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 14, E'And Jesus went forth, and saw a great multitude, and was moved with compassion toward them, and he healed their sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 15, E'And when it was evening, his disciples came to him, saying, This is a desert place, and the time is now past; send the multitude away, that they may go into the villages, and buy themselves victuals.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 16, E'But Jesus said unto them, They need not depart; give ye them to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 17, E'And they say unto him, We have here but five loaves, and two fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 18, E'He said, Bring them hither to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 19, E'And he commanded the multitude to sit down on the grass, and took the five loaves, and the two fishes, and looking up to heaven, he blessed, and brake, and gave the loaves to his disciples, and the disciples to the multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 20, E'And they did all eat, and were filled: and they took up of the fragments that remained twelve baskets full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 21, E'And they that had eaten were about five thousand men, beside women and children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 22, E'And straightway Jesus constrained his disciples to get into a ship, and to go before him unto the other side, while he sent the multitudes away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 23, E'And when he had sent the multitudes away, he went up into a mountain apart to pray: and when the evening was come, he was there alone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 24, E'But the ship was now in the midst of the sea, tossed with waves: for the wind was contrary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 25, E'And in the fourth watch of the night Jesus went unto them, walking on the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 26, E'And when the disciples saw him walking on the sea, they were troubled, saying, It is a spirit; and they cried out for fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 27, E'But straightway Jesus spake unto them, saying, Be of good cheer; it is I; be not afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 28, E'And Peter answered him and said, Lord, if it be thou, bid me come unto thee on the water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 29, E'And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 30, E'But when he saw the wind boisterous, he was afraid; and beginning to sink, he cried, saying, Lord, save me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 31, E'And immediately Jesus stretched forth his hand, and caught him, and said unto him, O thou of little faith, wherefore didst thou doubt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 32, E'And when they were come into the ship, the wind ceased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 33, E'Then they that were in the ship came and worshipped him, saying, Of a truth thou art the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 34, E'And when they were gone over, they came into the land of Gennesaret.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 35, E'And when the men of that place had knowledge of him, they sent out into all that country round about, and brought unto him all that were diseased;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 14, 36, E'And besought him that they might only touch the hem of his garment: and as many as touched were made perfectly whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 1, E'Then came to Jesus scribes and Pharisees, which were of Jerusalem, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 2, E'Why do thy disciples transgress the tradition of the elders? for they wash not their hands when they eat bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 3, E'But he answered and said unto them, Why do ye also transgress the commandment of God by your tradition?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 4, E'For God commanded, saying, Honour thy father and mother: and, He that curseth father or mother, let him die the death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 5, E'But ye say, Whosoever shall say to his father or his mother, It is a gift, by whatsoever thou mightest be profited by me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 6, E'And honour not his father or his mother, he shall be free. Thus have ye made the commandment of God of none effect by your tradition.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 7, E'Ye hypocrites, well did Esaias prophesy of you, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 8, E'This people draweth nigh unto me with their mouth, and honoureth me with their lips; but their heart is far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 9, E'But in vain they do worship me, teaching for doctrines the commandments of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 10, E'And he called the multitude, and said unto them, Hear, and understand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 11, E'Not that which goeth into the mouth defileth a man; but that which cometh out of the mouth, this defileth a man.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 12, E'Then came his disciples, and said unto him, Knowest thou that the Pharisees were offended, after they heard this saying?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 13, E'But he answered and said, Every plant, which my heavenly Father hath not planted, shall be rooted up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 14, E'Let them alone: they be blind leaders of the blind. And if the blind lead the blind, both shall fall into the ditch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 15, E'Then answered Peter and said unto him, Declare unto us this parable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 16, E'And Jesus said, Are ye also yet without understanding?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 17, E'Do not ye yet understand, that whatsoever entereth in at the mouth goeth into the belly, and is cast out into the draught?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 18, E'But those things which proceed out of the mouth come forth from the heart; and they defile the man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 19, E'For out of the heart proceed evil thoughts, murders, adulteries, fornications, thefts, false witness, blasphemies:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 20, E'These are the things which defile a man: but to eat with unwashen hands defileth not a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 21, E'Then Jesus went thence, and departed into the coasts of Tyre and Sidon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 22, E'And, behold, a woman of Canaan came out of the same coasts, and cried unto him, saying, Have mercy on me, O Lord, thou son of David; my daughter is grievously vexed with a devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 23, E'But he answered her not a word. And his disciples came and besought him, saying, Send her away; for she crieth after us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 24, E'But he answered and said, I am not sent but unto the lost sheep of the house of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 25, E'Then came she and worshipped him, saying, Lord, help me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 26, E'But he answered and said, It is not meet to take the childrenâ€™s bread, and to cast it to dogs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 27, E'And she said, Truth, Lord: yet the dogs eat of the crumbs which fall from their mastersâ€™ table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 28, E'Then Jesus answered and said unto her, O woman, great is thy faith: be it unto thee even as thou wilt. And her daughter was made whole from that very hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 29, E'And Jesus departed from thence, and came nigh unto the sea of Galilee; and went up into a mountain, and sat down there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 30, E'And great multitudes came unto him, having with them those that were lame, blind, dumb, maimed, and many others, and cast them down at Jesusâ€™ feet; and he healed them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 31, E'Insomuch that the multitude wondered, when they saw the dumb to speak, the maimed to be whole, the lame to walk, and the blind to see: and they glorified the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 32, E'Then Jesus called his disciples unto him, and said, I have compassion on the multitude, because they continue with me now three days, and have nothing to eat: and I will not send them away fasting, lest they faint in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 33, E'And his disciples say unto him, Whence should we have so much bread in the wilderness, as to fill so great a multitude?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 34, E'And Jesus saith unto them, How many loaves have ye? And they said, Seven, and a few little fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 35, E'And he commanded the multitude to sit down on the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 36, E'And he took the seven loaves and the fishes, and gave thanks, and brake them, and gave to his disciples, and the disciples to the multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 37, E'And they did all eat, and were filled: and they took up of the broken meat that was left seven baskets full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 38, E'And they that did eat were four thousand men, beside women and children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 15, 39, E'And he sent away the multitude, and took ship, and came into the coasts of Magdala.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 1, E'The Pharisees also with the Sadducees came, and tempting desired him that he would shew them a sign from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 2, E'He answered and said unto them, When it is evening, ye say, It will be fair weather: for the sky is red.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 3, E'And in the morning, It will be foul weather to day: for the sky is red and lowring. O ye hypocrites, ye can discern the face of the sky; but can ye not discern the signs of the times?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 4, E'A wicked and adulterous generation seeketh after a sign; and there shall no sign be given unto it, but the sign of the prophet Jonas. And he left them, and departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 5, E'And when his disciples were come to the other side, they had forgotten to take bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 6, E'Then Jesus said unto them, Take heed and beware of the leaven of the Pharisees and of the Sadducees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 7, E'And they reasoned among themselves, saying, It is because we have taken no bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 8, E'Which when Jesus perceived, he said unto them, O ye of little faith, why reason ye among yourselves, because ye have brought no bread?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 9, E'Do ye not yet understand, neither remember the five loaves of the five thousand, and how many baskets ye took up?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 10, E'Neither the seven loaves of the four thousand, and how many baskets ye took up?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 11, E'How is it that ye do not understand that I spake it not to you concerning bread, that ye should beware of the leaven of the Pharisees and of the Sadducees?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 12, E'Then understood they how that he bade them not beware of the leaven of bread, but of the doctrine of the Pharisees and of the Sadducees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 13, E'When Jesus came into the coasts of Caesarea Philippi, he asked his disciples, saying, Whom do men say that I the Son of man am?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 14, E'And they said, Some say that thou art John the Baptist: some, Elias; and others, Jeremias, or one of the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 15, E'He saith unto them, But whom say ye that I am?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 16, E'And Simon Peter answered and said, Thou art the Christ, the Son of the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 17, E'And Jesus answered and said unto him, Blessed art thou, Simon Barjona: for flesh and blood hath not revealed it unto thee, but my Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 18, E'And I say also unto thee, That thou art Peter, and upon this rock I will build my church; and the gates of hell shall not prevail against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 19, E'And I will give unto thee the keys of the kingdom of heaven: and whatsoever thou shalt bind on earth shall be bound in heaven: and whatsoever thou shalt loose on earth shall be loosed in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 20, E'Then charged he his disciples that they should tell no man that he was Jesus the Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 21, E'From that time forth began Jesus to shew unto his disciples, how that he must go unto Jerusalem, and suffer many things of the elders and chief priests and scribes, and be killed, and be raised again the third day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 22, E'Then Peter took him, and began to rebuke him, saying, Be it far from thee, Lord: this shall not be unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 23, E'But he turned, and said unto Peter, Get thee behind me, Satan: thou art an offence unto me: for thou savourest not the things that be of God, but those that be of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 24, E'Then said Jesus unto his disciples, If any man will come after me, let him deny himself, and take up his cross, and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 25, E'For whosoever will save his life shall lose it: and whosoever will lose his life for my sake shall find it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 26, E'For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 27, E'For the Son of man shall come in the glory of his Father with his angels; and then he shall reward every man according to his works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 16, 28, E'Verily I say unto you, There be some standing here, which shall not taste of death, till they see the Son of man coming in his kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 1, E'And after six days Jesus taketh Peter, James, and John his brother, and bringeth them up into an high mountain apart,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 2, E'And was transfigured before them: and his face did shine as the sun, and his raiment was white as the light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 3, E'And, behold, there appeared unto them Moses and Elias talking with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 4, E'Then answered Peter, and said unto Jesus, Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles; one for thee, and one for Moses, and one for Elias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 5, E'While he yet spake, behold, a bright cloud overshadowed them: and behold a voice out of the cloud, which said, This is my beloved Son, in whom I am well pleased; hear ye him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 6, E'And when the disciples heard it, they fell on their face, and were sore afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 7, E'And Jesus came and touched them, and said, Arise, and be not afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 8, E'And when they had lifted up their eyes, they saw no man, save Jesus only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 9, E'And as they came down from the mountain, Jesus charged them, saying, Tell the vision to no man, until the Son of man be risen again from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 10, E'And his disciples asked him, saying, Why then say the scribes that Elias must first come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 11, E'And Jesus answered and said unto them, Elias truly shall first come, and restore all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 12, E'But I say unto you, That Elias is come already, and they knew him not, but have done unto him whatsoever they listed. Likewise shall also the Son of man suffer of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 13, E'Then the disciples understood that he spake unto them of John the Baptist.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 14, E'And when they were come to the multitude, there came to him a certain man, kneeling down to him, and saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 15, E'Lord, have mercy on my son: for he is lunatick, and sore vexed: for ofttimes he falleth into the fire, and oft into the water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 16, E'And I brought him to thy disciples, and they could not cure him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 17, E'Then Jesus answered and said, O faithless and perverse generation, how long shall I be with you? how long shall I suffer you? bring him hither to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 18, E'And Jesus rebuked the devil; and he departed out of him: and the child was cured from that very hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 19, E'Then came the disciples to Jesus apart, and said, Why could not we cast him out?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 20, E'And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 21, E'Howbeit this kind goeth not out but by prayer and fasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 22, E'And while they abode in Galilee, Jesus said unto them, The Son of man shall be betrayed into the hands of men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 23, E'And they shall kill him, and the third day he shall be raised again. And they were exceeding sorry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 24, E'And when they were come to Capernaum, they that received tribute money came to Peter, and said, Doth not your master pay tribute?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 25, E'He saith, Yes. And when he was come into the house, Jesus prevented him, saying, What thinkest thou, Simon? of whom do the kings of the earth take custom or tribute? of their own children, or of strangers?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 26, E'Peter saith unto him, Of strangers. Jesus saith unto him, Then are the children free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 17, 27, E'Notwithstanding, lest we should offend them, go thou to the sea, and cast an hook, and take up the fish that first cometh up; and when thou hast opened his mouth, thou shalt find a piece of money: that take, and give unto them for me and thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 1, E'At the same time came the disciples unto Jesus, saying, Who is the greatest in the kingdom of heaven?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 2, E'And Jesus called a little child unto him, and set him in the midst of them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 3, E'And said, Verily I say unto you, Except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 4, E'Whosoever therefore shall humble himself as this little child, the same is greatest in the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 5, E'And whoso shall receive one such little child in my name receiveth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 6, E'But whoso shall offend one of these little ones which believe in me, it were better for him that a millstone were hanged about his neck, and that he were drowned in the depth of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 7, E'Woe unto the world because of offences! for it must needs be that offences come; but woe to that man by whom the offence cometh!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 8, E'Wherefore if thy hand or thy foot offend thee, cut them off, and cast them from thee: it is better for thee to enter into life halt or maimed, rather than having two hands or two feet to be cast into everlasting fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 9, E'And if thine eye offend thee, pluck it out, and cast it from thee: it is better for thee to enter into life with one eye, rather than having two eyes to be cast into hell fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 10, E'Take heed that ye despise not one of these little ones; for I say unto you, That in heaven their angels do always behold the face of my Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 11, E'For the Son of man is come to save that which was lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 12, E'How think ye? if a man have an hundred sheep, and one of them be gone astray, doth he not leave the ninety and nine, and goeth into the mountains, and seeketh that which is gone astray?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 13, E'And if so be that he find it, verily I say unto you, he rejoiceth more of that sheep, than of the ninety and nine which went not astray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 14, E'Even so it is not the will of your Father which is in heaven, that one of these little ones should perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 15, E'Moreover if thy brother shall trespass against thee, go and tell him his fault between thee and him alone: if he shall hear thee, thou hast gained thy brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 16, E'But if he will not hear thee, then take with thee one or two more, that in the mouth of two or three witnesses every word may be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 17, E'And if he shall neglect to hear them, tell it unto the church: but if he neglect to hear the church, let him be unto thee as an heathen man and a publican.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 18, E'Verily I say unto you, Whatsoever ye shall bind on earth shall be bound in heaven: and whatsoever ye shall loose on earth shall be loosed in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 19, E'Again I say unto you, That if two of you shall agree on earth as touching any thing that they shall ask, it shall be done for them of my Father which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 20, E'For where two or three are gathered together in my name, there am I in the midst of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 21, E'Then came Peter to him, and said, Lord, how oft shall my brother sin against me, and I forgive him? till seven times?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 22, E'Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 23, E'Therefore is the kingdom of heaven likened unto a certain king, which would take account of his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 24, E'And when he had begun to reckon, one was brought unto him, which owed him ten thousand talents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 25, E'But forasmuch as he had not to pay, his lord commanded him to be sold, and his wife, and children, and all that he had, and payment to be made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 26, E'The servant therefore fell down, and worshipped him, saying, Lord, have patience with me, and I will pay thee all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 27, E'Then the lord of that servant was moved with compassion, and loosed him, and forgave him the debt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 28, E'But the same servant went out, and found one of his fellowservants, which owed him an hundred pence: and he laid hands on him, and took him by the throat, saying, Pay me that thou owest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 29, E'And his fellowservant fell down at his feet, and besought him, saying, Have patience with me, and I will pay thee all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 30, E'And he would not: but went and cast him into prison, till he should pay the debt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 31, E'So when his fellowservants saw what was done, they were very sorry, and came and told unto their lord all that was done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 32, E'Then his lord, after that he had called him, said unto him, O thou wicked servant, I forgave thee all that debt, because thou desiredst me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 33, E'Shouldest not thou also have had compassion on thy fellowservant, even as I had pity on thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 34, E'And his lord was wroth, and delivered him to the tormentors, till he should pay all that was due unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 18, 35, E'So likewise shall my heavenly Father do also unto you, if ye from your hearts forgive not every one his brother their trespasses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 1, E'And it came to pass, that when Jesus had finished these sayings, he departed from Galilee, and came into the coasts of Judaea beyond Jordan;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 2, E'And great multitudes followed him; and he healed them there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 3, E'The Pharisees also came unto him, tempting him, and saying unto him, Is it lawful for a man to put away his wife for every cause?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 4, E'And he answered and said unto them, Have ye not read, that he which made them at the beginning made them male and female,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 5, E'And said, For this cause shall a man leave father and mother, and shall cleave to his wife: and they twain shall be one flesh?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 6, E'Wherefore they are no more twain, but one flesh. What therefore God hath joined together, let not man put asunder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 7, E'They say unto him, Why did Moses then command to give a writing of divorcement, and to put her away?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 8, E'He saith unto them, Moses because of the hardness of your hearts suffered you to put away your wives: but from the beginning it was not so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 9, E'And I say unto you, Whosoever shall put away his wife, except it be for fornication, and shall marry another, committeth adultery: and whoso marrieth her which is put away doth commit adultery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 10, E'His disciples say unto him, If the case of the man be so with his wife, it is not good to marry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 11, E'But he said unto them, All men cannot receive this saying, save they to whom it is given.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 12, E'For there are some eunuchs, which were so born from their motherâ€™s womb: and there are some eunuchs, which were made eunuchs of men: and there be eunuchs, which have made themselves eunuchs for the kingdom of heavenâ€™s sake. He that is able to receive it, let him receive it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 13, E'Then were there brought unto him little children, that he should put his hands on them, and pray: and the disciples rebuked them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 14, E'But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 15, E'And he laid his hands on them, and departed thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 16, E'And, behold, one came and said unto him, Good Master, what good thing shall I do, that I may have eternal life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 17, E'And he said unto him, Why callest thou me good? there is none good but one, that is, God: but if thou wilt enter into life, keep the commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 18, E'He saith unto him, Which? Jesus said, Thou shalt do no murder, Thou shalt not commit adultery, Thou shalt not steal, Thou shalt not bear false witness,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 19, E'Honour thy father and thy mother: and, Thou shalt love thy neighbour as thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 20, E'The young man saith unto him, All these things have I kept from my youth up: what lack I yet?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 21, E'Jesus said unto him, If thou wilt be perfect, go and sell that thou hast, and give to the poor, and thou shalt have treasure in heaven: and come and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 22, E'But when the young man heard that saying, he went away sorrowful: for he had great possessions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 23, E'Then said Jesus unto his disciples, Verily I say unto you, That a rich man shall hardly enter into the kingdom of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 24, E'And again I say unto you, It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 25, E'When his disciples heard it, they were exceedingly amazed, saying, Who then can be saved?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 26, E'But Jesus beheld them, and said unto them, With men this is impossible; but with God all things are possible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 27, E'Then answered Peter and said unto him, Behold, we have forsaken all, and followed thee; what shall we have therefore?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 28, E'And Jesus said unto them, Verily I say unto you, That ye which have followed me, in the regeneration when the Son of man shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 29, E'And every one that hath forsaken houses, or brethren, or sisters, or father, or mother, or wife, or children, or lands, for my nameâ€™s sake, shall receive an hundredfold, and shall inherit everlasting life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 19, 30, E'But many that are first shall be last; and the last shall be first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 1, E'For the kingdom of heaven is like unto a man that is an householder, which went out early in the morning to hire labourers into his vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 2, E'And when he had agreed with the labourers for a penny a day, he sent them into his vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 3, E'And he went out about the third hour, and saw others standing idle in the marketplace,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 4, E'And said unto them; Go ye also into the vineyard, and whatsoever is right I will give you. And they went their way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 5, E'Again he went out about the sixth and ninth hour, and did likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 6, E'And about the eleventh hour he went out, and found others standing idle, and saith unto them, Why stand ye here all the day idle?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 7, E'They say unto him, Because no man hath hired us. He saith unto them, Go ye also into the vineyard; and whatsoever is right, that shall ye receive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 8, E'So when even was come, the lord of the vineyard saith unto his steward, Call the labourers, and give them their hire, beginning from the last unto the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 9, E'And when they came that were hired about the eleventh hour, they received every man a penny.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 10, E'But when the first came, they supposed that they should have received more; and they likewise received every man a penny.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 11, E'And when they had received it, they murmured against the goodman of the house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 12, E'Saying, These last have wrought but one hour, and thou hast made them equal unto us, which have borne the burden and heat of the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 13, E'But he answered one of them, and said, Friend, I do thee no wrong: didst not thou agree with me for a penny?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 14, E'Take that thine is, and go thy way: I will give unto this last, even as unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 15, E'Is it not lawful for me to do what I will with mine own? Is thine eye evil, because I am good?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 16, E'So the last shall be first, and the first last: for many be called, but few chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 17, E'And Jesus going up to Jerusalem took the twelve disciples apart in the way, and said unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 18, E'Behold, we go up to Jerusalem; and the Son of man shall be betrayed unto the chief priests and unto the scribes, and they shall condemn him to death,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 19, E'And shall deliver him to the Gentiles to mock, and to scourge, and to crucify him: and the third day he shall rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 20, E'Then came to him the mother of Zebedeeâ€™s children with her sons, worshipping him, and desiring a certain thing of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 21, E'And he said unto her, What wilt thou? She saith unto him, Grant that these my two sons may sit, the one on thy right hand, and the other on the left, in thy kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 22, E'But Jesus answered and said, Ye know not what ye ask. Are ye able to drink of the cup that I shall drink of, and to be baptized with the baptism that I am baptized with? They say unto him, We are able.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 23, E'And he saith unto them, Ye shall drink indeed of my cup, and be baptized with the baptism that I am baptized with: but to sit on my right hand, and on my left, is not mine to give, but it shall be given to them for whom it is prepared of my Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 24, E'And when the ten heard it, they were moved with indignation against the two brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 25, E'But Jesus called them unto him, and said, Ye know that the princes of the Gentiles exercise dominion over them, and they that are great exercise authority upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 26, E'But it shall not be so among you: but whosoever will be great among you, let him be your minister;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 27, E'And whosoever will be chief among you, let him be your servant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 28, E'Even as the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 29, E'And as they departed from Jericho, a great multitude followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 30, E'And, behold, two blind men sitting by the way side, when they heard that Jesus passed by, cried out, saying, Have mercy on us, O Lord, thou son of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 31, E'And the multitude rebuked them, because they should hold their peace: but they cried the more, saying, Have mercy on us, O Lord, thou son of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 32, E'And Jesus stood still, and called them, and said, What will ye that I shall do unto you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 33, E'They say unto him, Lord, that our eyes may be opened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 20, 34, E'So Jesus had compassion on them, and touched their eyes: and immediately their eyes received sight, and they followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 1, E'And when they drew nigh unto Jerusalem, and were come to Bethphage, unto the mount of Olives, then sent Jesus two disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 2, E'Saying unto them, Go into the village over against you, and straightway ye shall find an ass tied, and a colt with her: loose them, and bring them unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 3, E'And if any man say ought unto you, ye shall say, The Lord hath need of them; and straightway he will send them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 4, E'All this was done, that it might be fulfilled which was spoken by the prophet, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 5, E'Tell ye the daughter of Sion, Behold, thy King cometh unto thee, meek, and sitting upon an ass, and a colt the foal of an ass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 6, E'And the disciples went, and did as Jesus commanded them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 7, E'And brought the ass, and the colt, and put on them their clothes, and they set him thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 8, E'And a very great multitude spread their garments in the way; others cut down branches from the trees, and strawed them in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 9, E'And the multitudes that went before, and that followed, cried, saying, Hosanna to the son of David: Blessed is he that cometh in the name of the Lord; Hosanna in the highest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 10, E'And when he was come into Jerusalem, all the city was moved, saying, Who is this?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 11, E'And the multitude said, This is Jesus the prophet of Nazareth of Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 12, E'And Jesus went into the temple of God, and cast out all them that sold and bought in the temple, and overthrew the tables of the moneychangers, and the seats of them that sold doves,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 13, E'And said unto them, It is written, My house shall be called the house of prayer; but ye have made it a den of thieves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 14, E'And the blind and the lame came to him in the temple; and he healed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 15, E'And when the chief priests and scribes saw the wonderful things that he did, and the children crying in the temple, and saying, Hosanna to the son of David; they were sore displeased,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 16, E'And said unto him, Hearest thou what these say? And Jesus saith unto them, Yea; have ye never read, Out of the mouth of babes and sucklings thou hast perfected praise?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 17, E'And he left them, and went out of the city into Bethany; and he lodged there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 18, E'Now in the morning as he returned into the city, he hungered.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 19, E'And when he saw a fig tree in the way, he came to it, and found nothing thereon, but leaves only, and said unto it, Let no fruit grow on thee henceforward for ever. And presently the fig tree withered away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 20, E'And when the disciples saw it, they marvelled, saying, How soon is the fig tree withered away!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 21, E'Jesus answered and said unto them, Verily I say unto you, If ye have faith, and doubt not, ye shall not only do this which is done to the fig tree, but also if ye shall say unto this mountain, Be thou removed, and be thou cast into the sea; it shall be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 22, E'And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 23, E'And when he was come into the temple, the chief priests and the elders of the people came unto him as he was teaching, and said, By what authority doest thou these things? and who gave thee this authority?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 24, E'And Jesus answered and said unto them, I also will ask you one thing, which if ye tell me, I in like wise will tell you by what authority I do these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 25, E'The baptism of John, whence was it? from heaven, or of men? And they reasoned with themselves, saying, If we shall say, From heaven; he will say unto us, Why did ye not then believe him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 26, E'But if we shall say, Of men; we fear the people; for all hold John as a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 27, E'And they answered Jesus, and said, We cannot tell. And he said unto them, Neither tell I you by what authority I do these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 28, E'But what think ye? A certain man had two sons; and he came to the first, and said, Son, go work to day in my vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 29, E'He answered and said, I will not: but afterward he repented, and went.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 30, E'And he came to the second, and said likewise. And he answered and said, I go, sir: and went not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 31, E'Whether of them twain did the will of his father? They say unto him, The first. Jesus saith unto them, Verily I say unto you, That the publicans and the harlots go into the kingdom of God before you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 32, E'For John came unto you in the way of righteousness, and ye believed him not: but the publicans and the harlots believed him: and ye, when ye had seen it, repented not afterward, that ye might believe him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 33, E'Hear another parable: There was a certain householder, which planted a vineyard, and hedged it round about, and digged a winepress in it, and built a tower, and let it out to husbandmen, and went into a far country:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 34, E'And when the time of the fruit drew near, he sent his servants to the husbandmen, that they might receive the fruits of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 35, E'And the husbandmen took his servants, and beat one, and killed another, and stoned another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 36, E'Again, he sent other servants more than the first: and they did unto them likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 37, E'But last of all he sent unto them his son, saying, They will reverence my son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 38, E'But when the husbandmen saw the son, they said among themselves, This is the heir; come, let us kill him, and let us seize on his inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 39, E'And they caught him, and cast him out of the vineyard, and slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 40, E'When the lord therefore of the vineyard cometh, what will he do unto those husbandmen?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 41, E'They say unto him, He will miserably destroy those wicked men, and will let out his vineyard unto other husbandmen, which shall render him the fruits in their seasons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 42, E'Jesus saith unto them, Did ye never read in the scriptures, The stone which the builders rejected, the same is become the head of the corner: this is the Lordâ€™s doing, and it is marvellous in our eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 43, E'Therefore say I unto you, The kingdom of God shall be taken from you, and given to a nation bringing forth the fruits thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 44, E'And whosoever shall fall on this stone shall be broken: but on whomsoever it shall fall, it will grind him to powder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 45, E'And when the chief priests and Pharisees had heard his parables, they perceived that he spake of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 21, 46, E'But when they sought to lay hands on him, they feared the multitude, because they took him for a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 1, E'And Jesus answered and spake unto them again by parables, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 2, E'The kingdom of heaven is like unto a certain king, which made a marriage for his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 3, E'And sent forth his servants to call them that were bidden to the wedding: and they would not come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 4, E'Again, he sent forth other servants, saying, Tell them which are bidden, Behold, I have prepared my dinner: my oxen and my fatlings are killed, and all things are ready: come unto the marriage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 5, E'But they made light of it, and went their ways, one to his farm, another to his merchandise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 6, E'And the remnant took his servants, and entreated them spitefully, and slew them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 7, E'But when the king heard thereof, he was wroth: and he sent forth his armies, and destroyed those murderers, and burned up their city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 8, E'Then saith he to his servants, The wedding is ready, but they which were bidden were not worthy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 9, E'Go ye therefore into the highways, and as many as ye shall find, bid to the marriage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 10, E'So those servants went out into the highways, and gathered together all as many as they found, both bad and good: and the wedding was furnished with guests.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 11, E'And when the king came in to see the guests, he saw there a man which had not on a wedding garment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 12, E'And he saith unto him, Friend, how camest thou in hither not having a wedding garment? And he was speechless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 13, E'Then said the king to the servants, Bind him hand and foot, and take him away, and cast him into outer darkness; there shall be weeping and gnashing of teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 14, E'For many are called, but few are chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 15, E'Then went the Pharisees, and took counsel how they might entangle him in his talk.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 16, E'And they sent out unto him their disciples with the Herodians, saying, Master, we know that thou art true, and teachest the way of God in truth, neither carest thou for any man: for thou regardest not the person of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 17, E'Tell us therefore, What thinkest thou? Is it lawful to give tribute unto Caesar, or not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 18, E'But Jesus perceived their wickedness, and said, Why tempt ye me, ye hypocrites?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 19, E'Shew me the tribute money. And they brought unto him a penny.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 20, E'And he saith unto them, Whose is this image and superscription?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 21, E'They say unto him, Caesarâ€™s. Then saith he unto them, Render therefore unto Caesar the things which are Caesarâ€™s; and unto God the things that are Godâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 22, E'When they had heard these words, they marvelled, and left him, and went their way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 23, E'The same day came to him the Sadducees, which say that there is no resurrection, and asked him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 24, E'Saying, Master, Moses said, If a man die, having no children, his brother shall marry his wife, and raise up seed unto his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 25, E'Now there were with us seven brethren: and the first, when he had married a wife, deceased, and, having no issue, left his wife unto his brother:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 26, E'Likewise the second also, and the third, unto the seventh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 27, E'And last of all the woman died also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 28, E'Therefore in the resurrection whose wife shall she be of the seven? for they all had her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 29, E'Jesus answered and said unto them, Ye do err, not knowing the scriptures, nor the power of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 30, E'For in the resurrection they neither marry, nor are given in marriage, but are as the angels of God in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 31, E'But as touching the resurrection of the dead, have ye not read that which was spoken unto you by God, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 32, E'I am the God of Abraham, and the God of Isaac, and the God of Jacob? God is not the God of the dead, but of the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 33, E'And when the multitude heard this, they were astonished at his doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 34, E'But when the Pharisees had heard that he had put the Sadducees to silence, they were gathered together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 35, E'Then one of them, which was a lawyer, asked him a question, tempting him, and saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 36, E'Master, which is the great commandment in the law?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 37, E'Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 38, E'This is the first and great commandment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 39, E'And the second is like unto it, Thou shalt love thy neighbour as thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 40, E'On these two commandments hang all the law and the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 41, E'While the Pharisees were gathered together, Jesus asked them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 42, E'Saying, What think ye of Christ? whose son is he? They say unto him, The son of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 43, E'He saith unto them, How then doth David in spirit call him Lord, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 44, E'The LORD said unto my Lord, Sit thou on my right hand, till I make thine enemies thy footstool?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 45, E'If David then call him Lord, how is he his son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 22, 46, E'And no man was able to answer him a word, neither durst any man from that day forth ask him any more questions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 1, E'Then spake Jesus to the multitude, and to his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 2, E'Saying, The scribes and the Pharisees sit in Mosesâ€™ seat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 3, E'All therefore whatsoever they bid you observe, that observe and do; but do not ye after their works: for they say, and do not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 4, E'For they bind heavy burdens and grievous to be borne, and lay them on menâ€™s shoulders; but they themselves will not move them with one of their fingers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 5, E'But all their works they do for to be seen of men: they make broad their phylacteries, and enlarge the borders of their garments,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 6, E'And love the uppermost rooms at feasts, and the chief seats in the synagogues,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 7, E'And greetings in the markets, and to be called of men, Rabbi, Rabbi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 8, E'But be not ye called Rabbi: for one is your Master, even Christ; and all ye are brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 9, E'And call no man your father upon the earth: for one is your Father, which is in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 10, E'Neither be ye called masters: for one is your Master, even Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 11, E'But he that is greatest among you shall be your servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 12, E'And whosoever shall exalt himself shall be abased; and he that shall humble himself shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 13, E'But woe unto you, scribes and Pharisees, hypocrites! for ye shut up the kingdom of heaven against men: for ye neither go in yourselves, neither suffer ye them that are entering to go in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 14, E'Woe unto you, scribes and Pharisees, hypocrites! for ye devour widowsâ€™ houses, and for a pretence make long prayer: therefore ye shall receive the greater damnation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 15, E'Woe unto you, scribes and Pharisees, hypocrites! for ye compass sea and land to make one proselyte, and when he is made, ye make him twofold more the child of hell than yourselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 16, E'Woe unto you, ye blind guides, which say, Whosoever shall swear by the temple, it is nothing; but whosoever shall swear by the gold of the temple, he is a debtor!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 17, E'Ye fools and blind: for whether is greater, the gold, or the temple that sanctifieth the gold?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 18, E'And, Whosoever shall swear by the altar, it is nothing; but whosoever sweareth by the gift that is upon it, he is guilty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 19, E'Ye fools and blind: for whether is greater, the gift, or the altar that sanctifieth the gift?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 20, E'Whoso therefore shall swear by the altar, sweareth by it, and by all things thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 21, E'And whoso shall swear by the temple, sweareth by it, and by him that dwelleth therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 22, E'And he that shall swear by heaven, sweareth by the throne of God, and by him that sitteth thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 23, E'Woe unto you, scribes and Pharisees, hypocrites! for ye pay tithe of mint and anise and cummin, and have omitted the weightier matters of the law, judgment, mercy, and faith: these ought ye to have done, and not to leave the other undone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 24, E'Ye blind guides, which strain at a gnat, and swallow a camel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 25, E'Woe unto you, scribes and Pharisees, hypocrites! for ye make clean the outside of the cup and of the platter, but within they are full of extortion and excess.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 26, E'Thou blind Pharisee, cleanse first that which is within the cup and platter, that the outside of them may be clean also.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 27, E'Woe unto you, scribes and Pharisees, hypocrites! for ye are like unto whited sepulchres, which indeed appear beautiful outward, but are within full of dead menâ€™s bones, and of all uncleanness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 28, E'Even so ye also outwardly appear righteous unto men, but within ye are full of hypocrisy and iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 29, E'Woe unto you, scribes and Pharisees, hypocrites! because ye build the tombs of the prophets, and garnish the sepulchres of the righteous,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 30, E'And say, If we had been in the days of our fathers, we would not have been partakers with them in the blood of the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 31, E'Wherefore ye be witnesses unto yourselves, that ye are the children of them which killed the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 32, E'Fill ye up then the measure of your fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 33, E'Ye serpents, ye generation of vipers, how can ye escape the damnation of hell?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 34, E'Wherefore, behold, I send unto you prophets, and wise men, and scribes: and some of them ye shall kill and crucify; and some of them shall ye scourge in your synagogues, and persecute them from city to city:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 35, E'That upon you may come all the righteous blood shed upon the earth, from the blood of righteous Abel unto the blood of Zacharias son of Barachias, whom ye slew between the temple and the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 36, E'Verily I say unto you, All these things shall come upon this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 37, E'O Jerusalem, Jerusalem, thou that killest the prophets, and stonest them which are sent unto thee, how often would I have gathered thy children together, even as a hen gathereth her chickens under her wings, and ye would not!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 38, E'Behold, your house is left unto you desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 23, 39, E'For I say unto you, Ye shall not see me henceforth, till ye shall say, Blessed is he that cometh in the name of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 1, E'And Jesus went out, and departed from the temple: and his disciples came to him for to shew him the buildings of the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 2, E'And Jesus said unto them, See ye not all these things? verily I say unto you, There shall not be left here one stone upon another, that shall not be thrown down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 3, E'And as he sat upon the mount of Olives, the disciples came unto him privately, saying, Tell us, when shall these things be? and what shall be the sign of thy coming, and of the end of the world?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 4, E'And Jesus answered and said unto them, Take heed that no man deceive you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 5, E'For many shall come in my name, saying, I am Christ; and shall deceive many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 6, E'And ye shall hear of wars and rumours of wars: see that ye be not troubled: for all these things must come to pass, but the end is not yet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 7, E'For nation shall rise against nation, and kingdom against kingdom: and there shall be famines, and pestilences, and earthquakes, in divers places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 8, E'All these are the beginning of sorrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 9, E'Then shall they deliver you up to be afflicted, and shall kill you: and ye shall be hated of all nations for my nameâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 10, E'And then shall many be offended, and shall betray one another, and shall hate one another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 11, E'And many false prophets shall rise, and shall deceive many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 12, E'And because iniquity shall abound, the love of many shall wax cold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 13, E'But he that shall endure unto the end, the same shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 14, E'And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 15, E'When ye therefore shall see the abomination of desolation, spoken of by Daniel the prophet, stand in the holy place, (whoso readeth, let him understand:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 16, E'Then let them which be in Judaea flee into the mountains:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 17, E'Let him which is on the housetop not come down to take any thing out of his house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 18, E'Neither let him which is in the field return back to take his clothes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 19, E'And woe unto them that are with child, and to them that give suck in those days!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 20, E'But pray ye that your flight be not in the winter, neither on the sabbath day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 21, E'For then shall be great tribulation, such as was not since the beginning of the world to this time, no, nor ever shall be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 22, E'And except those days should be shortened, there should no flesh be saved: but for the electâ€™s sake those days shall be shortened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 23, E'Then if any man shall say unto you, Lo, here is Christ, or there; believe it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 24, E'For there shall arise false Christs, and false prophets, and shall shew great signs and wonders; insomuch that, if it were possible, they shall deceive the very elect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 25, E'Behold, I have told you before.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 26, E'Wherefore if they shall say unto you, Behold, he is in the desert; go not forth: behold, he is in the secret chambers; believe it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 27, E'For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of man be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 28, E'For wheresoever the carcase is, there will the eagles be gathered together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 29, E'Immediately after the tribulation of those days shall the sun be darkened, and the moon shall not give her light, and the stars shall fall from heaven, and the powers of the heavens shall be shaken:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 30, E'And then shall appear the sign of the Son of man in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of man coming in the clouds of heaven with power and great glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 31, E'And he shall send his angels with a great sound of a trumpet, and they shall gather together his elect from the four winds, from one end of heaven to the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 32, E'Now learn a parable of the fig tree; When his branch is yet tender, and putteth forth leaves, ye know that summer is nigh:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 33, E'So likewise ye, when ye shall see all these things, know that it is near, even at the doors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 34, E'Verily I say unto you, This generation shall not pass, till all these things be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 35, E'Heaven and earth shall pass away, but my words shall not pass away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 36, E'But of that day and hour knoweth no man, no, not the angels of heaven, but my Father only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 37, E'But as the days of Noe were, so shall also the coming of the Son of man be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 38, E'For as in the days that were before the flood they were eating and drinking, marrying and giving in marriage, until the day that Noe entered into the ark,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 39, E'And knew not until the flood came, and took them all away; so shall also the coming of the Son of man be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 40, E'Then shall two be in the field; the one shall be taken, and the other left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 41, E'Two women shall be grinding at the mill; the one shall be taken, and the other left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 42, E'Watch therefore: for ye know not what hour your Lord doth come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 43, E'But know this, that if the goodman of the house had known in what watch the thief would come, he would have watched, and would not have suffered his house to be broken up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 44, E'Therefore be ye also ready: for in such an hour as ye think not the Son of man cometh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 45, E'Who then is a faithful and wise servant, whom his lord hath made ruler over his household, to give them meat in due season?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 46, E'Blessed is that servant, whom his lord when he cometh shall find so doing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 47, E'Verily I say unto you, That he shall make him ruler over all his goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 48, E'But and if that evil servant shall say in his heart, My lord delayeth his coming;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 49, E'And shall begin to smite his fellowservants, and to eat and drink with the drunken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 50, E'The lord of that servant shall come in a day when he looketh not for him, and in an hour that he is not aware of,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 24, 51, E'And shall cut him asunder, and appoint him his portion with the hypocrites: there shall be weeping and gnashing of teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 1, E'Then shall the kingdom of heaven be likened unto ten virgins, which took their lamps, and went forth to meet the bridegroom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 2, E'And five of them were wise, and five were foolish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 3, E'They that were foolish took their lamps, and took no oil with them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 4, E'But the wise took oil in their vessels with their lamps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 5, E'While the bridegroom tarried, they all slumbered and slept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 6, E'And at midnight there was a cry made, Behold, the bridegroom cometh; go ye out to meet him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 7, E'Then all those virgins arose, and trimmed their lamps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 8, E'And the foolish said unto the wise, Give us of your oil; for our lamps are gone out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 9, E'But the wise answered, saying, Not so; lest there be not enough for us and you: but go ye rather to them that sell, and buy for yourselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 10, E'And while they went to buy, the bridegroom came; and they that were ready went in with him to the marriage: and the door was shut.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 11, E'Afterward came also the other virgins, saying, Lord, Lord, open to us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 12, E'But he answered and said, Verily I say unto you, I know you not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 13, E'Watch therefore, for ye know neither the day nor the hour wherein the Son of man cometh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 14, E'For the kingdom of heaven is as a man travelling into a far country, who called his own servants, and delivered unto them his goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 15, E'And unto one he gave five talents, to another two, and to another one; to every man according to his several ability; and straightway took his journey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 16, E'Then he that had received the five talents went and traded with the same, and made them other five talents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 17, E'And likewise he that had received two, he also gained other two.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 18, E'But he that had received one went and digged in the earth, and hid his lordâ€™s money.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 19, E'After a long time the lord of those servants cometh, and reckoneth with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 20, E'And so he that had received five talents came and brought other five talents, saying, Lord, thou deliveredst unto me five talents: behold, I have gained beside them five talents more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 21, E'His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 22, E'He also that had received two talents came and said, Lord, thou deliveredst unto me two talents: behold, I have gained two other talents beside them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 23, E'His lord said unto him, Well done, good and faithful servant; thou hast been faithful over a few things, I will make thee ruler over many things: enter thou into the joy of thy lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 24, E'Then he which had received the one talent came and said, Lord, I knew thee that thou art an hard man, reaping where thou hast not sown, and gathering where thou hast not strawed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 25, E'And I was afraid, and went and hid thy talent in the earth: lo, there thou hast that is thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 26, E'His lord answered and said unto him, Thou wicked and slothful servant, thou knewest that I reap where I sowed not, and gather where I have not strawed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 27, E'Thou oughtest therefore to have put my money to the exchangers, and then at my coming I should have received mine own with usury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 28, E'Take therefore the talent from him, and give it unto him which hath ten talents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 29, E'For unto every one that hath shall be given, and he shall have abundance: but from him that hath not shall be taken away even that which he hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 30, E'And cast ye the unprofitable servant into outer darkness: there shall be weeping and gnashing of teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 31, E'When the Son of man shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 32, E'And before him shall be gathered all nations: and he shall separate them one from another, as a shepherd divideth his sheep from the goats:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 33, E'And he shall set the sheep on his right hand, but the goats on the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 34, E'Then shall the King say unto them on his right hand, Come, ye blessed of my Father, inherit the kingdom prepared for you from the foundation of the world:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 35, E'For I was an hungred, and ye gave me meat: I was thirsty, and ye gave me drink: I was a stranger, and ye took me in:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 36, E'Naked, and ye clothed me: I was sick, and ye visited me: I was in prison, and ye came unto me.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 37, E'Then shall the righteous answer him, saying, Lord, when saw we thee an hungred, and fed thee? or thirsty, and gave thee drink?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 38, E'When saw we thee a stranger, and took thee in? or naked, and clothed thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 39, E'Or when saw we thee sick, or in prison, and came unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 40, E'And the King shall answer and say unto them, Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 41, E'Then shall he say also unto them on the left hand, Depart from me, ye cursed, into everlasting fire, prepared for the devil and his angels:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 42, E'For I was an hungred, and ye gave me no meat: I was thirsty, and ye gave me no drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 43, E'I was a stranger, and ye took me not in: naked, and ye clothed me not: sick, and in prison, and ye visited me not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 44, E'Then shall they also answer him, saying, Lord, when saw we thee an hungred, or athirst, or a stranger, or naked, or sick, or in prison, and did not minister unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 45, E'Then shall he answer them, saying, Verily I say unto you, Inasmuch as ye did it not to one of the least of these, ye did it not to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 25, 46, E'And these shall go away into everlasting punishment: but the righteous into life eternal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 1, E'And it came to pass, when Jesus had finished all these sayings, he said unto his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 2, E'Ye know that after two days is the feast of the passover, and the Son of man is betrayed to be crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 3, E'Then assembled together the chief priests, and the scribes, and the elders of the people, unto the palace of the high priest, who was called Caiaphas,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 4, E'And consulted that they might take Jesus by subtilty, and kill him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 5, E'But they said, Not on the feast day, lest there be an uproar among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 6, E'Now when Jesus was in Bethany, in the house of Simon the leper,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 7, E'There came unto him a woman having an alabaster box of very precious ointment, and poured it on his head, as he sat at meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 8, E'But when his disciples saw it, they had indignation, saying, To what purpose is this waste?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 9, E'For this ointment might have been sold for much, and given to the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 10, E'When Jesus understood it, he said unto them, Why trouble ye the woman? for she hath wrought a good work upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 11, E'For ye have the poor always with you; but me ye have not always.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 12, E'For in that she hath poured this ointment on my body, she did it for my burial.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 13, E'Verily I say unto you, Wheresoever this gospel shall be preached in the whole world, there shall also this, that this woman hath done, be told for a memorial of her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 14, E'Then one of the twelve, called Judas Iscariot, went unto the chief priests,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 15, E'And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 16, E'And from that time he sought opportunity to betray him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 17, E'Now the first day of the feast of unleavened bread the disciples came to Jesus, saying unto him, Where wilt thou that we prepare for thee to eat the passover?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 18, E'And he said, Go into the city to such a man, and say unto him, The Master saith, My time is at hand; I will keep the passover at thy house with my disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 19, E'And the disciples did as Jesus had appointed them; and they made ready the passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 20, E'Now when the even was come, he sat down with the twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 21, E'And as they did eat, he said, Verily I say unto you, that one of you shall betray me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 22, E'And they were exceeding sorrowful, and began every one of them to say unto him, Lord, is it I?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 23, E'And he answered and said, He that dippeth his hand with me in the dish, the same shall betray me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 24, E'The Son of man goeth as it is written of him: but woe unto that man by whom the Son of man is betrayed! it had been good for that man if he had not been born.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 25, E'Then Judas, which betrayed him, answered and said, Master, is it I? He said unto him, Thou hast said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 26, E'And as they were eating, Jesus took bread, and blessed it, and brake it, and gave it to the disciples, and said, Take, eat; this is my body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 27, E'And he took the cup, and gave thanks, and gave it to them, saying, Drink ye all of it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 28, E'For this is my blood of the new testament, which is shed for many for the remission of sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 29, E'But I say unto you, I will not drink henceforth of this fruit of the vine, until that day when I drink it new with you in my Fatherâ€™s kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 30, E'And when they had sung an hymn, they went out into the mount of Olives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 31, E'Then saith Jesus unto them, All ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep of the flock shall be scattered abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 32, E'But after I am risen again, I will go before you into Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 33, E'Peter answered and said unto him, Though all men shall be offended because of thee, yet will I never be offended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 34, E'Jesus said unto him, Verily I say unto thee, That this night, before the cock crow, thou shalt deny me thrice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 35, E'Peter said unto him, Though I should die with thee, yet will I not deny thee. Likewise also said all the disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 36, E'Then cometh Jesus with them unto a place called Gethsemane, and saith unto the disciples, Sit ye here, while I go and pray yonder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 37, E'And he took with him Peter and the two sons of Zebedee, and began to be sorrowful and very heavy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 38, E'Then saith he unto them, My soul is exceeding sorrowful, even unto death: tarry ye here, and watch with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 39, E'And he went a little farther, and fell on his face, and prayed, saying, O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 40, E'And he cometh unto the disciples, and findeth them asleep, and saith unto Peter, What, could ye not watch with me one hour?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 41, E'Watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 42, E'He went away again the second time, and prayed, saying, O my Father, if this cup may not pass away from me, except I drink it, thy will be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 43, E'And he came and found them asleep again: for their eyes were heavy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 44, E'And he left them, and went away again, and prayed the third time, saying the same words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 45, E'Then cometh he to his disciples, and saith unto them, Sleep on now, and take your rest: behold, the hour is at hand, and the Son of man is betrayed into the hands of sinners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 46, E'Rise, let us be going: behold, he is at hand that doth betray me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 47, E'And while he yet spake, lo, Judas, one of the twelve, came, and with him a great multitude with swords and staves, from the chief priests and elders of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 48, E'Now he that betrayed him gave them a sign, saying, Whomsoever I shall kiss, that same is he: hold him fast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 49, E'And forthwith he came to Jesus, and said, Hail, master; and kissed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 50, E'And Jesus said unto him, Friend, wherefore art thou come? Then came they, and laid hands on Jesus, and took him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 51, E'And, behold, one of them which were with Jesus stretched out his hand, and drew his sword, and struck a servant of the high priestâ€™s, and smote off his ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 52, E'Then said Jesus unto him, Put up again thy sword into his place: for all they that take the sword shall perish with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 53, E'Thinkest thou that I cannot now pray to my Father, and he shall presently give me more than twelve legions of angels?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 54, E'But how then shall the scriptures be fulfilled, that thus it must be?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 55, E'In that same hour said Jesus to the multitudes, Are ye come out as against a thief with swords and staves for to take me? I sat daily with you teaching in the temple, and ye laid no hold on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 56, E'But all this was done, that the scriptures of the prophets might be fulfilled. Then all the disciples forsook him, and fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 57, E'And they that had laid hold on Jesus led him away to Caiaphas the high priest, where the scribes and the elders were assembled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 58, E'But Peter followed him afar off unto the high priestâ€™s palace, and went in, and sat with the servants, to see the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 59, E'Now the chief priests, and elders, and all the council, sought false witness against Jesus, to put him to death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 60, E'But found none: yea, though many false witnesses came, yet found they none. At the last came two false witnesses,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 61, E'And said, This fellow said, I am able to destroy the temple of God, and to build it in three days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 62, E'And the high priest arose, and said unto him, Answerest thou nothing? what is it which these witness against thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 63, E'But Jesus held his peace. And the high priest answered and said unto him, I adjure thee by the living God, that thou tell us whether thou be the Christ, the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 64, E'Jesus saith unto him, Thou hast said: nevertheless I say unto you, Hereafter shall ye see the Son of man sitting on the right hand of power, and coming in the clouds of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 65, E'Then the high priest rent his clothes, saying, He hath spoken blasphemy; what further need have we of witnesses? behold, now ye have heard his blasphemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 66, E'What think ye? They answered and said, He is guilty of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 67, E'Then did they spit in his face, and buffeted him; and others smote him with the palms of their hands,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 68, E'Saying, Prophesy unto us, thou Christ, Who is he that smote thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 69, E'Now Peter sat without in the palace: and a damsel came unto him, saying, Thou also wast with Jesus of Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 70, E'But he denied before them all, saying, I know not what thou sayest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 71, E'And when he was gone out into the porch, another maid saw him, and said unto them that were there, This fellow was also with Jesus of Nazareth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 72, E'And again he denied with an oath, I do not know the man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 73, E'And after a while came unto him they that stood by, and said to Peter, Surely thou also art one of them; for thy speech bewrayeth thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 74, E'Then began he to curse and to swear, saying, I know not the man. And immediately the cock crew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 26, 75, E'And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 1, E'When the morning was come, all the chief priests and elders of the people took counsel against Jesus to put him to death:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 2, E'And when they had bound him, they led him away, and delivered him to Pontius Pilate the governor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 3, E'Then Judas, which had betrayed him, when he saw that he was condemned, repented himself, and brought again the thirty pieces of silver to the chief priests and elders,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 4, E'Saying, I have sinned in that I have betrayed the innocent blood. And they said, What is that to us? see thou to that.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 5, E'And he cast down the pieces of silver in the temple, and departed, and went and hanged himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 6, E'And the chief priests took the silver pieces, and said, It is not lawful for to put them into the treasury, because it is the price of blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 7, E'And they took counsel, and bought with them the potterâ€™s field, to bury strangers in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 8, E'Wherefore that field was called, The field of blood, unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 9, E'Then was fulfilled that which was spoken by Jeremy the prophet, saying, And they took the thirty pieces of silver, the price of him that was valued, whom they of the children of Israel did value;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 10, E'And gave them for the potterâ€™s field, as the Lord appointed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 11, E'And Jesus stood before the governor: and the governor asked him, saying, Art thou the King of the Jews? And Jesus said unto him, Thou sayest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 12, E'And when he was accused of the chief priests and elders, he answered nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 13, E'Then said Pilate unto him, Hearest thou not how many things they witness against thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 14, E'And he answered him to never a word; insomuch that the governor marvelled greatly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 15, E'Now at that feast the governor was wont to release unto the people a prisoner, whom they would.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 16, E'And they had then a notable prisoner, called Barabbas.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 17, E'Therefore when they were gathered together, Pilate said unto them, Whom will ye that I release unto you? Barabbas, or Jesus which is called Christ?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 18, E'For he knew that for envy they had delivered him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 19, E'When he was set down on the judgment seat, his wife sent unto him, saying, Have thou nothing to do with that just man: for I have suffered many things this day in a dream because of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 20, E'But the chief priests and elders persuaded the multitude that they should ask Barabbas, and destroy Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 21, E'The governor answered and said unto them, Whether of the twain will ye that I release unto you? They said, Barabbas.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 22, E'Pilate saith unto them, What shall I do then with Jesus which is called Christ? They all say unto him, Let him be crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 23, E'And the governor said, Why, what evil hath he done? But they cried out the more, saying, Let him be crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 24, E'When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 25, E'Then answered all the people, and said, His blood be on us, and on our children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 26, E'Then released he Barabbas unto them: and when he had scourged Jesus, he delivered him to be crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 27, E'Then the soldiers of the governor took Jesus into the common hall, and gathered unto him the whole band of soldiers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 28, E'And they stripped him, and put on him a scarlet robe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 29, E'And when they had platted a crown of thorns, they put it upon his head, and a reed in his right hand: and they bowed the knee before him, and mocked him, saying, Hail, King of the Jews!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 30, E'And they spit upon him, and took the reed, and smote him on the head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 31, E'And after that they had mocked him, they took the robe off from him, and put his own raiment on him, and led him away to crucify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 32, E'And as they came out, they found a man of Cyrene, Simon by name: him they compelled to bear his cross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 33, E'And when they were come unto a place called Golgotha, that is to say, a place of a skull,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 34, E'They gave him vinegar to drink mingled with gall: and when he had tasted thereof, he would not drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 35, E'And they crucified him, and parted his garments, casting lots: that it might be fulfilled which was spoken by the prophet, They parted my garments among them, and upon my vesture did they cast lots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 36, E'And sitting down they watched him there;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 37, E'And set up over his head his accusation written, THIS IS JESUS THE KING OF THE JEWS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 38, E'Then were there two thieves crucified with him, one on the right hand, and another on the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 39, E'And they that passed by reviled him, wagging their heads,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 40, E'And saying, Thou that destroyest the temple, and buildest it in three days, save thyself. If thou be the Son of God, come down from the cross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 41, E'Likewise also the chief priests mocking him, with the scribes and elders, said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 42, E'He saved others; himself he cannot save. If he be the King of Israel, let him now come down from the cross, and we will believe him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 43, E'He trusted in God; let him deliver him now, if he will have him: for he said, I am the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 44, E'The thieves also, which were crucified with him, cast the same in his teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 45, E'Now from the sixth hour there was darkness over all the land unto the ninth hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 46, E'And about the ninth hour Jesus cried with a loud voice, saying, Eli, Eli, lama sabachthani? that is to say, My God, my God, why hast thou forsaken me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 47, E'Some of them that stood there, when they heard that, said, This man calleth for Elias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 48, E'And straightway one of them ran, and took a spunge, and filled it with vinegar, and put it on a reed, and gave him to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 49, E'The rest said, Let be, let us see whether Elias will come to save him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 50, E'Jesus, when he had cried again with a loud voice, yielded up the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 51, E'And, behold, the veil of the temple was rent in twain from the top to the bottom; and the earth did quake, and the rocks rent;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 52, E'And the graves were opened; and many bodies of the saints which slept arose,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 53, E'And came out of the graves after his resurrection, and went into the holy city, and appeared unto many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 54, E'Now when the centurion, and they that were with him, watching Jesus, saw the earthquake, and those things that were done, they feared greatly, saying, Truly this was the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 55, E'And many women were there beholding afar off, which followed Jesus from Galilee, ministering unto him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 56, E'Among which was Mary Magdalene, and Mary the mother of James and Joses, and the mother of Zebedeeâ€™s children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 57, E'When the even was come, there came a rich man of Arimathaea, named Joseph, who also himself was Jesusâ€™ disciple:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 58, E'He went to Pilate, and begged the body of Jesus. Then Pilate commanded the body to be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 59, E'And when Joseph had taken the body, he wrapped it in a clean linen cloth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 60, E'And laid it in his own new tomb, which he had hewn out in the rock: and he rolled a great stone to the door of the sepulchre, and departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 61, E'And there was Mary Magdalene, and the other Mary, sitting over against the sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 62, E'Now the next day, that followed the day of the preparation, the chief priests and Pharisees came together unto Pilate,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 63, E'Saying, Sir, we remember that that deceiver said, while he was yet alive, After three days I will rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 64, E'Command therefore that the sepulchre be made sure until the third day, lest his disciples come by night, and steal him away, and say unto the people, He is risen from the dead: so the last error shall be worse than the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 65, E'Pilate said unto them, Ye have a watch: go your way, make it as sure as ye can.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 27, 66, E'So they went, and made the sepulchre sure, sealing the stone, and setting a watch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 1, E'In the end of the sabbath, as it began to dawn toward the first day of the week, came Mary Magdalene and the other Mary to see the sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 2, E'And, behold, there was a great earthquake: for the angel of the Lord descended from heaven, and came and rolled back the stone from the door, and sat upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 3, E'His countenance was like lightning, and his raiment white as snow:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 4, E'And for fear of him the keepers did shake, and became as dead men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 5, E'And the angel answered and said unto the women, Fear not ye: for I know that ye seek Jesus, which was crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 6, E'He is not here: for he is risen, as he said. Come, see the place where the Lord lay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 7, E'And go quickly, and tell his disciples that he is risen from the dead; and, behold, he goeth before you into Galilee; there shall ye see him: lo, I have told you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 8, E'And they departed quickly from the sepulchre with fear and great joy; and did run to bring his disciples word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 9, E'And as they went to tell his disciples, behold, Jesus met them, saying, All hail. And they came and held him by the feet, and worshipped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 10, E'Then said Jesus unto them, Be not afraid: go tell my brethren that they go into Galilee, and there shall they see me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 11, E'Now when they were going, behold, some of the watch came into the city, and shewed unto the chief priests all the things that were done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 12, E'And when they were assembled with the elders, and had taken counsel, they gave large money unto the soldiers,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 13, E'Saying, Say ye, His disciples came by night, and stole him away while we slept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 14, E'And if this come to the governorâ€™s ears, we will persuade him, and secure you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 15, E'So they took the money, and did as they were taught: and this saying is commonly reported among the Jews until this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 16, E'Then the eleven disciples went away into Galilee, into a mountain where Jesus had appointed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 17, E'And when they saw him, they worshipped him: but some doubted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 18, E'And Jesus came and spake unto them, saying, All power is given unto me in heaven and in earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 19, E'Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ed093818-3334-40d3-b5f0-ff2bbb0f054c', 28, 20, E'Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Matthew') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 1, E'The beginning of the gospel of Jesus Christ, the Son of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 2, E'As it is written in the prophets, Behold, I send my messenger before thy face, which shall prepare thy way before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 3, E'The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 4, E'John did baptize in the wilderness, and preach the baptism of repentance for the remission of sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 5, E'And there went out unto him all the land of Judaea, and they of Jerusalem, and were all baptized of him in the river of Jordan, confessing their sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 6, E'And John was clothed with camelâ€™s hair, and with a girdle of a skin about his loins; and he did eat locusts and wild honey;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 7, E'And preached, saying, There cometh one mightier than I after me, the latchet of whose shoes I am not worthy to stoop down and unloose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 8, E'I indeed have baptized you with water: but he shall baptize you with the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 9, E'And it came to pass in those days, that Jesus came from Nazareth of Galilee, and was baptized of John in Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 10, E'And straightway coming up out of the water, he saw the heavens opened, and the Spirit like a dove descending upon him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 11, E'And there came a voice from heaven, saying, Thou art my beloved Son, in whom I am well pleased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 12, E'And immediately the Spirit driveth him into the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 13, E'And he was there in the wilderness forty days, tempted of Satan; and was with the wild beasts; and the angels ministered unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 14, E'Now after that John was put in prison, Jesus came into Galilee, preaching the gospel of the kingdom of God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 15, E'And saying, The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 16, E'Now as he walked by the sea of Galilee, he saw Simon and Andrew his brother casting a net into the sea: for they were fishers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 17, E'And Jesus said unto them, Come ye after me, and I will make you to become fishers of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 18, E'And straightway they forsook their nets, and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 19, E'And when he had gone a little farther thence, he saw James the son of Zebedee, and John his brother, who also were in the ship mending their nets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 20, E'And straightway he called them: and they left their father Zebedee in the ship with the hired servants, and went after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 21, E'And they went into Capernaum; and straightway on the sabbath day he entered into the synagogue, and taught.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 22, E'And they were astonished at his doctrine: for he taught them as one that had authority, and not as the scribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 23, E'And there was in their synagogue a man with an unclean spirit; and he cried out,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 24, E'Saying, Let us alone; what have we to do with thee, thou Jesus of Nazareth? art thou come to destroy us? I know thee who thou art, the Holy One of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 25, E'And Jesus rebuked him, saying, Hold thy peace, and come out of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 26, E'And when the unclean spirit had torn him, and cried with a loud voice, he came out of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 27, E'And they were all amazed, insomuch that they questioned among themselves, saying, What thing is this? what new doctrine is this? for with authority commandeth he even the unclean spirits, and they do obey him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 28, E'And immediately his fame spread abroad throughout all the region round about Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 29, E'And forthwith, when they were come out of the synagogue, they entered into the house of Simon and Andrew, with James and John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 30, E'But Simonâ€™s wifeâ€™s mother lay sick of a fever, and anon they tell him of her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 31, E'And he came and took her by the hand, and lifted her up; and immediately the fever left her, and she ministered unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 32, E'And at even, when the sun did set, they brought unto him all that were diseased, and them that were possessed with devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 33, E'And all the city was gathered together at the door.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 34, E'And he healed many that were sick of divers diseases, and cast out many devils; and suffered not the devils to speak, because they knew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 35, E'And in the morning, rising up a great while before day, he went out, and departed into a solitary place, and there prayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 36, E'And Simon and they that were with him followed after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 37, E'And when they had found him, they said unto him, All men seek for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 38, E'And he said unto them, Let us go into the next towns, that I may preach there also: for therefore came I forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 39, E'And he preached in their synagogues throughout all Galilee, and cast out devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 40, E'And there came a leper to him, beseeching him, and kneeling down to him, and saying unto him, If thou wilt, thou canst make me clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 41, E'And Jesus, moved with compassion, put forth his hand, and touched him, and saith unto him, I will; be thou clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 42, E'And as soon as he had spoken, immediately the leprosy departed from him, and he was cleansed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 43, E'And he straitly charged him, and forthwith sent him away;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 44, E'And saith unto him, See thou say nothing to any man: but go thy way, shew thyself to the priest, and offer for thy cleansing those things which Moses commanded, for a testimony unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 1, 45, E'But he went out, and began to publish it much, and to blaze abroad the matter, insomuch that Jesus could no more openly enter into the city, but was without in desert places: and they came to him from every quarter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 1, E'And again he entered into Capernaum after some days; and it was noised that he was in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 2, E'And straightway many were gathered together, insomuch that there was no room to receive them, no, not so much as about the door: and he preached the word unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 3, E'And they come unto him, bringing one sick of the palsy, which was borne of four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 4, E'And when they could not come nigh unto him for the press, they uncovered the roof where he was: and when they had broken it up, they let down the bed wherein the sick of the palsy lay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 5, E'When Jesus saw their faith, he said unto the sick of the palsy, Son, thy sins be forgiven thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 6, E'But there were certain of the scribes sitting there, and reasoning in their hearts,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 7, E'Why doth this man thus speak blasphemies? who can forgive sins but God only?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 8, E'And immediately when Jesus perceived in his spirit that they so reasoned within themselves, he said unto them, Why reason ye these things in your hearts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 9, E'Whether is it easier to say to the sick of the palsy, Thy sins be forgiven thee; or to say, Arise, and take up thy bed, and walk?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 10, E'But that ye may know that the Son of man hath power on earth to forgive sins, (he saith to the sick of the palsy,)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 11, E'I say unto thee, Arise, and take up thy bed, and go thy way into thine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 12, E'And immediately he arose, took up the bed, and went forth before them all; insomuch that they were all amazed, and glorified God, saying, We never saw it on this fashion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 13, E'And he went forth again by the sea side; and all the multitude resorted unto him, and he taught them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 14, E'And as he passed by, he saw Levi the son of Alphaeus sitting at the receipt of custom, and said unto him, Follow me. And he arose and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 15, E'And it came to pass, that, as Jesus sat at meat in his house, many publicans and sinners sat also together with Jesus and his disciples: for there were many, and they followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 16, E'And when the scribes and Pharisees saw him eat with publicans and sinners, they said unto his disciples, How is it that he eateth and drinketh with publicans and sinners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 17, E'When Jesus heard it, he saith unto them, They that are whole have no need of the physician, but they that are sick: I came not to call the righteous, but sinners to repentance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 18, E'And the disciples of John and of the Pharisees used to fast: and they come and say unto him, Why do the disciples of John and of the Pharisees fast, but thy disciples fast not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 19, E'And Jesus said unto them, Can the children of the bridechamber fast, while the bridegroom is with them? as long as they have the bridegroom with them, they cannot fast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 20, E'But the days will come, when the bridegroom shall be taken away from them, and then shall they fast in those days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 21, E'No man also seweth a piece of new cloth on an old garment: else the new piece that filled it up taketh away from the old, and the rent is made worse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 22, E'And no man putteth new wine into old bottles: else the new wine doth burst the bottles, and the wine is spilled, and the bottles will be marred: but new wine must be put into new bottles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 23, E'And it came to pass, that he went through the corn fields on the sabbath day; and his disciples began, as they went, to pluck the ears of corn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 24, E'And the Pharisees said unto him, Behold, why do they on the sabbath day that which is not lawful?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 25, E'And he said unto them, Have ye never read what David did, when he had need, and was an hungred, he, and they that were with him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 26, E'How he went into the house of God in the days of Abiathar the high priest, and did eat the shewbread, which is not lawful to eat but for the priests, and gave also to them which were with him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 27, E'And he said unto them, The sabbath was made for man, and not man for the sabbath:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 2, 28, E'Therefore the Son of man is Lord also of the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 1, E'And he entered again into the synagogue; and there was a man there which had a withered hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 2, E'And they watched him, whether he would heal him on the sabbath day; that they might accuse him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 3, E'And he saith unto the man which had the withered hand, Stand forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 4, E'And he saith unto them, Is it lawful to do good on the sabbath days, or to do evil? to save life, or to kill? But they held their peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 5, E'And when he had looked round about on them with anger, being grieved for the hardness of their hearts, he saith unto the man, Stretch forth thine hand. And he stretched it out: and his hand was restored whole as the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 6, E'And the Pharisees went forth, and straightway took counsel with the Herodians against him, how they might destroy him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 7, E'But Jesus withdrew himself with his disciples to the sea: and a great multitude from Galilee followed him, and from Judaea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 8, E'And from Jerusalem, and from Idumaea, and from beyond Jordan; and they about Tyre and Sidon, a great multitude, when they had heard what great things he did, came unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 9, E'And he spake to his disciples, that a small ship should wait on him because of the multitude, lest they should throng him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 10, E'For he had healed many; insomuch that they pressed upon him for to touch him, as many as had plagues.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 11, E'And unclean spirits, when they saw him, fell down before him, and cried, saying, Thou art the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 12, E'And he straitly charged them that they should not make him known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 13, E'And he goeth up into a mountain, and calleth unto him whom he would: and they came unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 14, E'And he ordained twelve, that they should be with him, and that he might send them forth to preach,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 15, E'And to have power to heal sicknesses, and to cast out devils:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 16, E'And Simon he surnamed Peter;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 17, E'And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 18, E'And Andrew, and Philip, and Bartholomew, and Matthew, and Thomas, and James the son of Alphaeus, and Thaddaeus, and Simon the Canaanite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 19, E'And Judas Iscariot, which also betrayed him: and they went into an house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 20, E'And the multitude cometh together again, so that they could not so much as eat bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 21, E'And when his friends heard of it, they went out to lay hold on him: for they said, He is beside himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 22, E'And the scribes which came down from Jerusalem said, He hath Beelzebub, and by the prince of the devils casteth he out devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 23, E'And he called them unto him, and said unto them in parables, How can Satan cast out Satan?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 24, E'And if a kingdom be divided against itself, that kingdom cannot stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 25, E'And if a house be divided against itself, that house cannot stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 26, E'And if Satan rise up against himself, and be divided, he cannot stand, but hath an end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 27, E'No man can enter into a strong manâ€™s house, and spoil his goods, except he will first bind the strong man; and then he will spoil his house.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 28, E'Verily I say unto you, All sins shall be forgiven unto the sons of men, and blasphemies wherewith soever they shall blaspheme:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 29, E'But he that shall blaspheme against the Holy Ghost hath never forgiveness, but is in danger of eternal damnation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 30, E'Because they said, He hath an unclean spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 31, E'There came then his brethren and his mother, and, standing without, sent unto him, calling him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 32, E'And the multitude sat about him, and they said unto him, Behold, thy mother and thy brethren without seek for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 33, E'And he answered them, saying, Who is my mother, or my brethren?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 34, E'And he looked round about on them which sat about him, and said, Behold my mother and my brethren!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 3, 35, E'For whosoever shall do the will of God, the same is my brother, and my sister, and mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 1, E'And he began again to teach by the sea side: and there was gathered unto him a great multitude, so that he entered into a ship, and sat in the sea; and the whole multitude was by the sea on the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 2, E'And he taught them many things by parables, and said unto them in his doctrine,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 3, E'Hearken; Behold, there went out a sower to sow:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 4, E'And it came to pass, as he sowed, some fell by the way side, and the fowls of the air came and devoured it up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 5, E'And some fell on stony ground, where it had not much earth; and immediately it sprang up, because it had no depth of earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 6, E'But when the sun was up, it was scorched; and because it had no root, it withered away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 7, E'And some fell among thorns, and the thorns grew up, and choked it, and it yielded no fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 8, E'And other fell on good ground, and did yield fruit that sprang up and increased; and brought forth, some thirty, and some sixty, and some an hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 9, E'And he said unto them, He that hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 10, E'And when he was alone, they that were about him with the twelve asked of him the parable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 11, E'And he said unto them, Unto you it is given to know the mystery of the kingdom of God: but unto them that are without, all these things are done in parables:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 12, E'That seeing they may see, and not perceive; and hearing they may hear, and not understand; lest at any time they should be converted, and their sins should be forgiven them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 13, E'And he said unto them, Know ye not this parable? and how then will ye know all parables?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 14, E'The sower soweth the word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 15, E'And these are they by the way side, where the word is sown; but when they have heard, Satan cometh immediately, and taketh away the word that was sown in their hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 16, E'And these are they likewise which are sown on stony ground; who, when they have heard the word, immediately receive it with gladness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 17, E'And have no root in themselves, and so endure but for a time: afterward, when affliction or persecution ariseth for the wordâ€™s sake, immediately they are offended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 18, E'And these are they which are sown among thorns; such as hear the word,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 19, E'And the cares of this world, and the deceitfulness of riches, and the lusts of other things entering in, choke the word, and it becometh unfruitful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 20, E'And these are they which are sown on good ground; such as hear the word, and receive it, and bring forth fruit, some thirtyfold, some sixty, and some an hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 21, E'And he said unto them, Is a candle brought to be put under a bushel, or under a bed? and not to be set on a candlestick?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 22, E'For there is nothing hid, which shall not be manifested; neither was any thing kept secret, but that it should come abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 23, E'If any man have ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 24, E'And he said unto them, Take heed what ye hear: with what measure ye mete, it shall be measured to you: and unto you that hear shall more be given.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 25, E'For he that hath, to him shall be given: and he that hath not, from him shall be taken even that which he hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 26, E'And he said, So is the kingdom of God, as if a man should cast seed into the ground;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 27, E'And should sleep, and rise night and day, and the seed should spring and grow up, he knoweth not how.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 28, E'For the earth bringeth forth fruit of herself; first the blade, then the ear, after that the full corn in the ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 29, E'But when the fruit is brought forth, immediately he putteth in the sickle, because the harvest is come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 30, E'And he said, Whereunto shall we liken the kingdom of God? or with what comparison shall we compare it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 31, E'It is like a grain of mustard seed, which, when it is sown in the earth, is less than all the seeds that be in the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 32, E'But when it is sown, it groweth up, and becometh greater than all herbs, and shooteth out great branches; so that the fowls of the air may lodge under the shadow of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 33, E'And with many such parables spake he the word unto them, as they were able to hear it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 34, E'But without a parable spake he not unto them: and when they were alone, he expounded all things to his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 35, E'And the same day, when the even was come, he saith unto them, Let us pass over unto the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 36, E'And when they had sent away the multitude, they took him even as he was in the ship. And there were also with him other little ships.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 37, E'And there arose a great storm of wind, and the waves beat into the ship, so that it was now full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 38, E'And he was in the hinder part of the ship, asleep on a pillow: and they awake him, and say unto him, Master, carest thou not that we perish?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 39, E'And he arose, and rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 40, E'And he said unto them, Why are ye so fearful? how is it that ye have no faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 4, 41, E'And they feared exceedingly, and said one to another, What manner of man is this, that even the wind and the sea obey him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 1, E'And they came over unto the other side of the sea, into the country of the Gadarenes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 2, E'And when he was come out of the ship, immediately there met him out of the tombs a man with an unclean spirit,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 3, E'Who had his dwelling among the tombs; and no man could bind him, no, not with chains:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 4, E'Because that he had been often bound with fetters and chains, and the chains had been plucked asunder by him, and the fetters broken in pieces: neither could any man tame him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 5, E'And always, night and day, he was in the mountains, and in the tombs, crying, and cutting himself with stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 6, E'But when he saw Jesus afar off, he ran and worshipped him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 7, E'And cried with a loud voice, and said, What have I to do with thee, Jesus, thou Son of the most high God? I adjure thee by God, that thou torment me not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 8, E'For he said unto him, Come out of the man, thou unclean spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 9, E'And he asked him, What is thy name? And he answered, saying, My name is Legion: for we are many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 10, E'And he besought him much that he would not send them away out of the country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 11, E'Now there was there nigh unto the mountains a great herd of swine feeding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 12, E'And all the devils besought him, saying, Send us into the swine, that we may enter into them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 13, E'And forthwith Jesus gave them leave. And the unclean spirits went out, and entered into the swine: and the herd ran violently down a steep place into the sea, (they were about two thousand;) and were choked in the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 14, E'And they that fed the swine fled, and told it in the city, and in the country. And they went out to see what it was that was done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 15, E'And they come to Jesus, and see him that was possessed with the devil, and had the legion, sitting, and clothed, and in his right mind: and they were afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 16, E'And they that saw it told them how it befell to him that was possessed with the devil, and also concerning the swine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 17, E'And they began to pray him to depart out of their coasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 18, E'And when he was come into the ship, he that had been possessed with the devil prayed him that he might be with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 19, E'Howbeit Jesus suffered him not, but saith unto him, Go home to thy friends, and tell them how great things the Lord hath done for thee, and hath had compassion on thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 20, E'And he departed, and began to publish in Decapolis how great things Jesus had done for him: and all men did marvel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 21, E'And when Jesus was passed over again by ship unto the other side, much people gathered unto him: and he was nigh unto the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 22, E'And, behold, there cometh one of the rulers of the synagogue, Jairus by name; and when he saw him, he fell at his feet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 23, E'And besought him greatly, saying, My little daughter lieth at the point of death: I pray thee, come and lay thy hands on her, that she may be healed; and she shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 24, E'And Jesus went with him; and much people followed him, and thronged him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 25, E'And a certain woman, which had an issue of blood twelve years,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 26, E'And had suffered many things of many physicians, and had spent all that she had, and was nothing bettered, but rather grew worse,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 27, E'When she had heard of Jesus, came in the press behind, and touched his garment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 28, E'For she said, If I may touch but his clothes, I shall be whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 29, E'And straightway the fountain of her blood was dried up; and she felt in her body that she was healed of that plague.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 30, E'And Jesus, immediately knowing in himself that virtue had gone out of him, turned him about in the press, and said, Who touched my clothes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 31, E'And his disciples said unto him, Thou seest the multitude thronging thee, and sayest thou, Who touched me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 32, E'And he looked round about to see her that had done this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 33, E'But the woman fearing and trembling, knowing what was done in her, came and fell down before him, and told him all the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 34, E'And he said unto her, Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 35, E'While he yet spake, there came from the ruler of the synagogueâ€™s house certain which said, Thy daughter is dead: why troublest thou the Master any further?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 36, E'As soon as Jesus heard the word that was spoken, he saith unto the ruler of the synagogue, Be not afraid, only believe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 37, E'And he suffered no man to follow him, save Peter, and James, and John the brother of James.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 38, E'And he cometh to the house of the ruler of the synagogue, and seeth the tumult, and them that wept and wailed greatly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 39, E'And when he was come in, he saith unto them, Why make ye this ado, and weep? the damsel is not dead, but sleepeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 40, E'And they laughed him to scorn. But when he had put them all out, he taketh the father and the mother of the damsel, and them that were with him, and entereth in where the damsel was lying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 41, E'And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 42, E'And straightway the damsel arose, and walked; for she was of the age of twelve years. And they were astonished with a great astonishment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 5, 43, E'And he charged them straitly that no man should know it; and commanded that something should be given her to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 1, E'And he went out from thence, and came into his own country; and his disciples follow him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 2, E'And when the sabbath day was come, he began to teach in the synagogue: and many hearing him were astonished, saying, From whence hath this man these things? and what wisdom is this which is given unto him, that even such mighty works are wrought by his hands?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 3, E'Is not this the carpenter, the son of Mary, the brother of James, and Joses, and of Juda, and Simon? and are not his sisters here with us? And they were offended at him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 4, E'But Jesus said unto them, A prophet is not without honour, but in his own country, and among his own kin, and in his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 5, E'And he could there do no mighty work, save that he laid his hands upon a few sick folk, and healed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 6, E'And he marvelled because of their unbelief. And he went round about the villages, teaching.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 7, E'And he called unto him the twelve, and began to send them forth by two and two; and gave them power over unclean spirits;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 8, E'And commanded them that they should take nothing for their journey, save a staff only; no scrip, no bread, no money in their purse:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 9, E'But be shod with sandals; and not put on two coats.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 10, E'And he said unto them, In what place soever ye enter into an house, there abide till ye depart from that place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 11, E'And whosoever shall not receive you, nor hear you, when ye depart thence, shake off the dust under your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for Sodom and Gomorrha in the day of judgment, than for that city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 12, E'And they went out, and preached that men should repent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 13, E'And they cast out many devils, and anointed with oil many that were sick, and healed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 14, E'And king Herod heard of him; (for his name was spread abroad:) and he said, That John the Baptist was risen from the dead, and therefore mighty works do shew forth themselves in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 15, E'Others said, That it is Elias. And others said, That it is a prophet, or as one of the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 16, E'But when Herod heard thereof, he said, It is John, whom I beheaded: he is risen from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 17, E'For Herod himself had sent forth and laid hold upon John, and bound him in prison for Herodiasâ€™ sake, his brother Philipâ€™s wife: for he had married her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 18, E'For John had said unto Herod, It is not lawful for thee to have thy brotherâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 19, E'Therefore Herodias had a quarrel against him, and would have killed him; but she could not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 20, E'For Herod feared John, knowing that he was a just man and an holy, and observed him; and when he heard him, he did many things, and heard him gladly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 21, E'And when a convenient day was come, that Herod on his birthday made a supper to his lords, high captains, and chief estates of Galilee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 22, E'And when the daughter of the said Herodias came in, and danced, and pleased Herod and them that sat with him, the king said unto the damsel, Ask of me whatsoever thou wilt, and I will give it thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 23, E'And he sware unto her, Whatsoever thou shalt ask of me, I will give it thee, unto the half of my kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 24, E'And she went forth, and said unto her mother, What shall I ask? And she said, The head of John the Baptist.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 25, E'And she came in straightway with haste unto the king, and asked, saying, I will that thou give me by and by in a charger the head of John the Baptist.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 26, E'And the king was exceeding sorry; yet for his oathâ€™s sake, and for their sakes which sat with him, he would not reject her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 27, E'And immediately the king sent an executioner, and commanded his head to be brought: and he went and beheaded him in the prison,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 28, E'And brought his head in a charger, and gave it to the damsel: and the damsel gave it to her mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 29, E'And when his disciples heard of it, they came and took up his corpse, and laid it in a tomb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 30, E'And the apostles gathered themselves together unto Jesus, and told him all things, both what they had done, and what they had taught.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 31, E'And he said unto them, Come ye yourselves apart into a desert place, and rest a while: for there were many coming and going, and they had no leisure so much as to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 32, E'And they departed into a desert place by ship privately.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 33, E'And the people saw them departing, and many knew him, and ran afoot thither out of all cities, and outwent them, and came together unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 34, E'And Jesus, when he came out, saw much people, and was moved with compassion toward them, because they were as sheep not having a shepherd: and he began to teach them many things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 35, E'And when the day was now far spent, his disciples came unto him, and said, This is a desert place, and now the time is far passed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 36, E'Send them away, that they may go into the country round about, and into the villages, and buy themselves bread: for they have nothing to eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 37, E'He answered and said unto them, Give ye them to eat. And they say unto him, Shall we go and buy two hundred pennyworth of bread, and give them to eat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 38, E'He saith unto them, How many loaves have ye? go and see. And when they knew, they say, Five, and two fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 39, E'And he commanded them to make all sit down by companies upon the green grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 40, E'And they sat down in ranks, by hundreds, and by fifties.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 41, E'And when he had taken the five loaves and the two fishes, he looked up to heaven, and blessed, and brake the loaves, and gave them to his disciples to set before them; and the two fishes divided he among them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 42, E'And they did all eat, and were filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 43, E'And they took up twelve baskets full of the fragments, and of the fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 44, E'And they that did eat of the loaves were about five thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 45, E'And straightway he constrained his disciples to get into the ship, and to go to the other side before unto Bethsaida, while he sent away the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 46, E'And when he had sent them away, he departed into a mountain to pray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 47, E'And when even was come, the ship was in the midst of the sea, and he alone on the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 48, E'And he saw them toiling in rowing; for the wind was contrary unto them: and about the fourth watch of the night he cometh unto them, walking upon the sea, and would have passed by them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 49, E'But when they saw him walking upon the sea, they supposed it had been a spirit, and cried out:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 50, E'For they all saw him, and were troubled. And immediately he talked with them, and saith unto them, Be of good cheer: it is I; be not afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 51, E'And he went up unto them into the ship; and the wind ceased: and they were sore amazed in themselves beyond measure, and wondered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 52, E'For they considered not the miracle of the loaves: for their heart was hardened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 53, E'And when they had passed over, they came into the land of Gennesaret, and drew to the shore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 54, E'And when they were come out of the ship, straightway they knew him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 55, E'And ran through that whole region round about, and began to carry about in beds those that were sick, where they heard he was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 6, 56, E'And whithersoever he entered, into villages, or cities, or country, they laid the sick in the streets, and besought him that they might touch if it were but the border of his garment: and as many as touched him were made whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 1, E'Then came together unto him the Pharisees, and certain of the scribes, which came from Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 2, E'And when they saw some of his disciples eat bread with defiled, that is to say, with unwashen, hands, they found fault.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 3, E'For the Pharisees, and all the Jews, except they wash their hands oft, eat not, holding the tradition of the elders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 4, E'And when they come from the market, except they wash, they eat not. And many other things there be, which they have received to hold, as the washing of cups, and pots, brasen vessels, and of tables.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 5, E'Then the Pharisees and scribes asked him, Why walk not thy disciples according to the tradition of the elders, but eat bread with unwashen hands?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 6, E'He answered and said unto them, Well hath Esaias prophesied of you hypocrites, as it is written, This people honoureth me with their lips, but their heart is far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 7, E'Howbeit in vain do they worship me, teaching for doctrines the commandments of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 8, E'For laying aside the commandment of God, ye hold the tradition of men, as the washing of pots and cups: and many other such like things ye do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 9, E'And he said unto them, Full well ye reject the commandment of God, that ye may keep your own tradition.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 10, E'For Moses said, Honour thy father and thy mother; and, Whoso curseth father or mother, let him die the death:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 11, E'But ye say, If a man shall say to his father or mother, It is Corban, that is to say, a gift, by whatsoever thou mightest be profited by me; he shall be free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 12, E'And ye suffer him no more to do ought for his father or his mother;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 13, E'Making the word of God of none effect through your tradition, which ye have delivered: and many such like things do ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 14, E'And when he had called all the people unto him, he said unto them, Hearken unto me every one of you, and understand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 15, E'There is nothing from without a man, that entering into him can defile him: but the things which come out of him, those are they that defile the man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 16, E'If any man have ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 17, E'And when he was entered into the house from the people, his disciples asked him concerning the parable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 18, E'And he saith unto them, Are ye so without understanding also? Do ye not perceive, that whatsoever thing from without entereth into the man, it cannot defile him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 19, E'Because it entereth not into his heart, but into the belly, and goeth out into the draught, purging all meats?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 20, E'And he said, That which cometh out of the man, that defileth the man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 21, E'For from within, out of the heart of men, proceed evil thoughts, adulteries, fornications, murders,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 22, E'Thefts, covetousness, wickedness, deceit, lasciviousness, an evil eye, blasphemy, pride, foolishness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 23, E'All these evil things come from within, and defile the man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 24, E'And from thence he arose, and went into the borders of Tyre and Sidon, and entered into an house, and would have no man know it: but he could not be hid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 25, E'For a certain woman, whose young daughter had an unclean spirit, heard of him, and came and fell at his feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 26, E'The woman was a Greek, a Syrophenician by nation; and she besought him that he would cast forth the devil out of her daughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 27, E'But Jesus said unto her, Let the children first be filled: for it is not meet to take the childrenâ€™s bread, and to cast it unto the dogs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 28, E'And she answered and said unto him, Yes, Lord: yet the dogs under the table eat of the childrenâ€™s crumbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 29, E'And he said unto her, For this saying go thy way; the devil is gone out of thy daughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 30, E'And when she was come to her house, she found the devil gone out, and her daughter laid upon the bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 31, E'And again, departing from the coasts of Tyre and Sidon, he came unto the sea of Galilee, through the midst of the coasts of Decapolis.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 32, E'And they bring unto him one that was deaf, and had an impediment in his speech; and they beseech him to put his hand upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 33, E'And he took him aside from the multitude, and put his fingers into his ears, and he spit, and touched his tongue;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 34, E'And looking up to heaven, he sighed, and saith unto him, Ephphatha, that is, Be opened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 35, E'And straightway his ears were opened, and the string of his tongue was loosed, and he spake plain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 36, E'And he charged them that they should tell no man: but the more he charged them, so much the more a great deal they published it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 7, 37, E'And were beyond measure astonished, saying, He hath done all things well: he maketh both the deaf to hear, and the dumb to speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 1, E'In those days the multitude being very great, and having nothing to eat, Jesus called his disciples unto him, and saith unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 2, E'I have compassion on the multitude, because they have now been with me three days, and have nothing to eat:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 3, E'And if I send them away fasting to their own houses, they will faint by the way: for divers of them came from far.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 4, E'And his disciples answered him, From whence can a man satisfy these men with bread here in the wilderness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 5, E'And he asked them, How many loaves have ye? And they said, Seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 6, E'And he commanded the people to sit down on the ground: and he took the seven loaves, and gave thanks, and brake, and gave to his disciples to set before them; and they did set them before the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 7, E'And they had a few small fishes: and he blessed, and commanded to set them also before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 8, E'So they did eat, and were filled: and they took up of the broken meat that was left seven baskets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 9, E'And they that had eaten were about four thousand: and he sent them away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 10, E'And straightway he entered into a ship with his disciples, and came into the parts of Dalmanutha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 11, E'And the Pharisees came forth, and began to question with him, seeking of him a sign from heaven, tempting him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 12, E'And he sighed deeply in his spirit, and saith, Why doth this generation seek after a sign? verily I say unto you, There shall no sign be given unto this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 13, E'And he left them, and entering into the ship again departed to the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 14, E'Now the disciples had forgotten to take bread, neither had they in the ship with them more than one loaf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 15, E'And he charged them, saying, Take heed, beware of the leaven of the Pharisees, and of the leaven of Herod.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 16, E'And they reasoned among themselves, saying, It is because we have no bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 17, E'And when Jesus knew it, he saith unto them, Why reason ye, because ye have no bread? perceive ye not yet, neither understand? have ye your heart yet hardened?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 18, E'Having eyes, see ye not? and having ears, hear ye not? and do ye not remember?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 19, E'When I brake the five loaves among five thousand, how many baskets full of fragments took ye up? They say unto him, Twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 20, E'And when the seven among four thousand, how many baskets full of fragments took ye up? And they said, Seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 21, E'And he said unto them, How is it that ye do not understand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 22, E'And he cometh to Bethsaida; and they bring a blind man unto him, and besought him to touch him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 23, E'And he took the blind man by the hand, and led him out of the town; and when he had spit on his eyes, and put his hands upon him, he asked him if he saw ought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 24, E'And he looked up, and said, I see men as trees, walking.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 25, E'After that he put his hands again upon his eyes, and made him look up: and he was restored, and saw every man clearly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 26, E'And he sent him away to his house, saying, Neither go into the town, nor tell it to any in the town.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 27, E'And Jesus went out, and his disciples, into the towns of Caesarea Philippi: and by the way he asked his disciples, saying unto them, Whom do men say that I am?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 28, E'And they answered, John the Baptist: but some say, Elias; and others, One of the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 29, E'And he saith unto them, But whom say ye that I am? And Peter answereth and saith unto him, Thou art the Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 30, E'And he charged them that they should tell no man of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 31, E'And he began to teach them, that the Son of man must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 32, E'And he spake that saying openly. And Peter took him, and began to rebuke him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 33, E'But when he had turned about and looked on his disciples, he rebuked Peter, saying, Get thee behind me, Satan: for thou savourest not the things that be of God, but the things that be of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 34, E'And when he had called the people unto him with his disciples also, he said unto them, Whosoever will come after me, let him deny himself, and take up his cross, and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 35, E'For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospelâ€™s, the same shall save it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 36, E'For what shall it profit a man, if he shall gain the whole world, and lose his own soul?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 37, E'Or what shall a man give in exchange for his soul?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 8, 38, E'Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of man be ashamed, when he cometh in the glory of his Father with the holy angels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 1, E'And he said unto them, Verily I say unto you, That there be some of them that stand here, which shall not taste of death, till they have seen the kingdom of God come with power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 2, E'And after six days Jesus taketh with him Peter, and James, and John, and leadeth them up into an high mountain apart by themselves: and he was transfigured before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 3, E'And his raiment became shining, exceeding white as snow; so as no fuller on earth can white them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 4, E'And there appeared unto them Elias with Moses: and they were talking with Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 5, E'And Peter answered and said to Jesus, Master, it is good for us to be here: and let us make three tabernacles; one for thee, and one for Moses, and one for Elias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 6, E'For he wist not what to say; for they were sore afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 7, E'And there was a cloud that overshadowed them: and a voice came out of the cloud, saying, This is my beloved Son: hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 8, E'And suddenly, when they had looked round about, they saw no man any more, save Jesus only with themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 9, E'And as they came down from the mountain, he charged them that they should tell no man what things they had seen, till the Son of man were risen from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 10, E'And they kept that saying with themselves, questioning one with another what the rising from the dead should mean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 11, E'And they asked him, saying, Why say the scribes that Elias must first come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 12, E'And he answered and told them, Elias verily cometh first, and restoreth all things; and how it is written of the Son of man, that he must suffer many things, and be set at nought.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 13, E'But I say unto you, That Elias is indeed come, and they have done unto him whatsoever they listed, as it is written of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 14, E'And when he came to his disciples, he saw a great multitude about them, and the scribes questioning with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 15, E'And straightway all the people, when they beheld him, were greatly amazed, and running to him saluted him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 16, E'And he asked the scribes, What question ye with them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 17, E'And one of the multitude answered and said, Master, I have brought unto thee my son, which hath a dumb spirit;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 18, E'And wheresoever he taketh him, he teareth him: and he foameth, and gnasheth with his teeth, and pineth away: and I spake to thy disciples that they should cast him out; and they could not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 19, E'He answereth him, and saith, O faithless generation, how long shall I be with you? how long shall I suffer you? bring him unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 20, E'And they brought him unto him: and when he saw him, straightway the spirit tare him; and he fell on the ground, and wallowed foaming.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 21, E'And he asked his father, How long is it ago since this came unto him? And he said, Of a child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 22, E'And ofttimes it hath cast him into the fire, and into the waters, to destroy him: but if thou canst do any thing, have compassion on us, and help us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 23, E'Jesus said unto him, If thou canst believe, all things are possible to him that believeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 24, E'And straightway the father of the child cried out, and said with tears, Lord, I believe; help thou mine unbelief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 25, E'When Jesus saw that the people came running together, he rebuked the foul spirit, saying unto him, Thou dumb and deaf spirit, I charge thee, come out of him, and enter no more into him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 26, E'And the spirit cried, and rent him sore, and came out of him: and he was as one dead; insomuch that many said, He is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 27, E'But Jesus took him by the hand, and lifted him up; and he arose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 28, E'And when he was come into the house, his disciples asked him privately, Why could not we cast him out?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 29, E'And he said unto them, This kind can come forth by nothing, but by prayer and fasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 30, E'And they departed thence, and passed through Galilee; and he would not that any man should know it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 31, E'For he taught his disciples, and said unto them, The Son of man is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 32, E'But they understood not that saying, and were afraid to ask him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 33, E'And he came to Capernaum: and being in the house he asked them, What was it that ye disputed among yourselves by the way?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 34, E'But they held their peace: for by the way they had disputed among themselves, who should be the greatest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 35, E'And he sat down, and called the twelve, and saith unto them, If any man desire to be first, the same shall be last of all, and servant of all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 36, E'And he took a child, and set him in the midst of them: and when he had taken him in his arms, he said unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 37, E'Whosoever shall receive one of such children in my name, receiveth me: and whosoever shall receive me, receiveth not me, but him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 38, E'And John answered him, saying, Master, we saw one casting out devils in thy name, and he followeth not us: and we forbad him, because he followeth not us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 39, E'But Jesus said, Forbid him not: for there is no man which shall do a miracle in my name, that can lightly speak evil of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 40, E'For he that is not against us is on our part.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 41, E'For whosoever shall give you a cup of water to drink in my name, because ye belong to Christ, verily I say unto you, he shall not lose his reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 42, E'And whosoever shall offend one of these little ones that believe in me, it is better for him that a millstone were hanged about his neck, and he were cast into the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 43, E'And if thy hand offend thee, cut it off: it is better for thee to enter into life maimed, than having two hands to go into hell, into the fire that never shall be quenched:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 44, E'Where their worm dieth not, and the fire is not quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 45, E'And if thy foot offend thee, cut it off: it is better for thee to enter halt into life, than having two feet to be cast into hell, into the fire that never shall be quenched:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 46, E'Where their worm dieth not, and the fire is not quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 47, E'And if thine eye offend thee, pluck it out: it is better for thee to enter into the kingdom of God with one eye, than having two eyes to be cast into hell fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 48, E'Where their worm dieth not, and the fire is not quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 49, E'For every one shall be salted with fire, and every sacrifice shall be salted with salt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 9, 50, E'Salt is good: but if the salt have lost his saltness, wherewith will ye season it? Have salt in yourselves, and have peace one with another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 1, E'And he arose from thence, and cometh into the coasts of Judaea by the farther side of Jordan: and the people resort unto him again; and, as he was wont, he taught them again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 2, E'And the Pharisees came to him, and asked him, Is it lawful for a man to put away his wife? tempting him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 3, E'And he answered and said unto them, What did Moses command you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 4, E'And they said, Moses suffered to write a bill of divorcement, and to put her away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 5, E'And Jesus answered and said unto them, For the hardness of your heart he wrote you this precept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 6, E'But from the beginning of the creation God made them male and female.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 7, E'For this cause shall a man leave his father and mother, and cleave to his wife;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 8, E'And they twain shall be one flesh: so then they are no more twain, but one flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 9, E'What therefore God hath joined together, let not man put asunder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 10, E'And in the house his disciples asked him again of the same matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 11, E'And he saith unto them, Whosoever shall put away his wife, and marry another, committeth adultery against her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 12, E'And if a woman shall put away her husband, and be married to another, she committeth adultery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 13, E'And they brought young children to him, that he should touch them: and his disciples rebuked those that brought them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 14, E'But when Jesus saw it, he was much displeased, and said unto them, Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 15, E'Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child, he shall not enter therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 16, E'And he took them up in his arms, put his hands upon them, and blessed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 17, E'And when he was gone forth into the way, there came one running, and kneeled to him, and asked him, Good Master, what shall I do that I may inherit eternal life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 18, E'And Jesus said unto him, Why callest thou me good? there is none good but one, that is, God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 19, E'Thou knowest the commandments, Do not commit adultery, Do not kill, Do not steal, Do not bear false witness, Defraud not, Honour thy father and mother. '),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 20, E'And he answered and said unto him, Master, all these have I observed from my youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 21, E'Then Jesus beholding him loved him, and said unto him, One thing thou lackest: go thy way, sell whatsoever thou hast, and give to the poor, and thou shalt have treasure in heaven: and come, take up the cross, and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 22, E'And he was sad at that saying, and went away grieved: for he had great possessions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 23, E'And Jesus looked round about, and saith unto his disciples, How hardly shall they that have riches enter into the kingdom of God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 24, E'And the disciples were astonished at his words. But Jesus answereth again, and saith unto them, Children, how hard is it for them that trust in riches to enter into the kingdom of God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 25, E'It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 26, E'And they were astonished out of measure, saying among themselves, Who then can be saved?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 27, E'And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 28, E'Then Peter began to say unto him, Lo, we have left all, and have followed thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 29, E'And Jesus answered and said, Verily I say unto you, There is no man that hath left house, or brethren, or sisters, or father, or mother, or wife, or children, or lands, for my sake, and the gospelâ€™s,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 30, E'But he shall receive an hundredfold now in this time, houses, and brethren, and sisters, and mothers, and children, and lands, with persecutions; and in the world to come eternal life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 31, E'But many that are first shall be last; and the last first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 32, E'And they were in the way going up to Jerusalem; and Jesus went before them: and they were amazed; and as they followed, they were afraid. And he took again the twelve, and began to tell them what things should happen unto him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 33, E'Saying, Behold, we go up to Jerusalem; and the Son of man shall be delivered unto the chief priests, and unto the scribes; and they shall condemn him to death, and shall deliver him to the Gentiles:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 34, E'And they shall mock him, and shall scourge him, and shall spit upon him, and shall kill him: and the third day he shall rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 35, E'And James and John, the sons of Zebedee, come unto him, saying, Master, we would that thou shouldest do for us whatsoever we shall desire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 36, E'And he said unto them, What would ye that I should do for you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 37, E'They said unto him, Grant unto us that we may sit, one on thy right hand, and the other on thy left hand, in thy glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 38, E'But Jesus said unto them, Ye know not what ye ask: can ye drink of the cup that I drink of? and be baptized with the baptism that I am baptized with?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 39, E'And they said unto him, We can. And Jesus said unto them, Ye shall indeed drink of the cup that I drink of; and with the baptism that I am baptized withal shall ye be baptized:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 40, E'But to sit on my right hand and on my left hand is not mine to give; but it shall be given to them for whom it is prepared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 41, E'And when the ten heard it, they began to be much displeased with James and John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 42, E'But Jesus called them to him, and saith unto them, Ye know that they which are accounted to rule over the Gentiles exercise lordship over them; and their great ones exercise authority upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 43, E'But so shall it not be among you: but whosoever will be great among you, shall be your minister:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 44, E'And whosoever of you will be the chiefest, shall be servant of all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 45, E'For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 46, E'And they came to Jericho: and as he went out of Jericho with his disciples and a great number of people, blind Bartimaeus, the son of Timaeus, sat by the highway side begging.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 47, E'And when he heard that it was Jesus of Nazareth, he began to cry out, and say, Jesus, thou son of David, have mercy on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 48, E'And many charged him that he should hold his peace: but he cried the more a great deal, Thou son of David, have mercy on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 49, E'And Jesus stood still, and commanded him to be called. And they call the blind man, saying unto him, Be of good comfort, rise; he calleth thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 50, E'And he, casting away his garment, rose, and came to Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 51, E'And Jesus answered and said unto him, What wilt thou that I should do unto thee? The blind man said unto him, Lord, that I might receive my sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 10, 52, E'And Jesus said unto him, Go thy way; thy faith hath made thee whole. And immediately he received his sight, and followed Jesus in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 1, E'And when they came nigh to Jerusalem, unto Bethphage and Bethany, at the mount of Olives, he sendeth forth two of his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 2, E'And saith unto them, Go your way into the village over against you: and as soon as ye be entered into it, ye shall find a colt tied, whereon never man sat; loose him, and bring him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 3, E'And if any man say unto you, Why do ye this? say ye that the Lord hath need of him; and straightway he will send him hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 4, E'And they went their way, and found the colt tied by the door without in a place where two ways met; and they loose him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 5, E'And certain of them that stood there said unto them, What do ye, loosing the colt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 6, E'And they said unto them even as Jesus had commanded: and they let them go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 7, E'And they brought the colt to Jesus, and cast their garments on him; and he sat upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 8, E'And many spread their garments in the way: and others cut down branches off the trees, and strawed them in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 9, E'And they that went before, and they that followed, cried, saying, Hosanna; Blessed is he that cometh in the name of the Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 10, E'Blessed be the kingdom of our father David, that cometh in the name of the Lord: Hosanna in the highest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 11, E'And Jesus entered into Jerusalem, and into the temple: and when he had looked round about upon all things, and now the eventide was come, he went out unto Bethany with the twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 12, E'And on the morrow, when they were come from Bethany, he was hungry:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 13, E'And seeing a fig tree afar off having leaves, he came, if haply he might find any thing thereon: and when he came to it, he found nothing but leaves; for the time of figs was not yet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 14, E'And Jesus answered and said unto it, No man eat fruit of thee hereafter for ever. And his disciples heard it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 15, E'And they come to Jerusalem: and Jesus went into the temple, and began to cast out them that sold and bought in the temple, and overthrew the tables of the moneychangers, and the seats of them that sold doves;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 16, E'And would not suffer that any man should carry any vessel through the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 17, E'And he taught, saying unto them, Is it not written, My house shall be called of all nations the house of prayer? but ye have made it a den of thieves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 18, E'And the scribes and chief priests heard it, and sought how they might destroy him: for they feared him, because all the people was astonished at his doctrine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 19, E'And when even was come, he went out of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 20, E'And in the morning, as they passed by, they saw the fig tree dried up from the roots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 21, E'And Peter calling to remembrance saith unto him, Master, behold, the fig tree which thou cursedst is withered away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 22, E'And Jesus answering saith unto them, Have faith in God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 23, E'For verily I say unto you, That whosoever shall say unto this mountain, Be thou removed, and be thou cast into the sea; and shall not doubt in his heart, but shall believe that those things which he saith shall come to pass; he shall have whatsoever he saith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 24, E'Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 25, E'And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 26, E'But if ye do not forgive, neither will your Father which is in heaven forgive your trespasses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 27, E'And they come again to Jerusalem: and as he was walking in the temple, there come to him the chief priests, and the scribes, and the elders,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 28, E'And say unto him, By what authority doest thou these things? and who gave thee this authority to do these things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 29, E'And Jesus answered and said unto them, I will also ask of you one question, and answer me, and I will tell you by what authority I do these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 30, E'The baptism of John, was it from heaven, or of men? answer me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 31, E'And they reasoned with themselves, saying, If we shall say, From heaven; he will say, Why then did ye not believe him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 32, E'But if we shall say, Of men; they feared the people: for all men counted John, that he was a prophet indeed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 11, 33, E'And they answered and said unto Jesus, We cannot tell. And Jesus answering saith unto them, Neither do I tell you by what authority I do these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 1, E'And he began to speak unto them by parables. A certain man planted a vineyard, and set an hedge about it, and digged a place for the winefat, and built a tower, and let it out to husbandmen, and went into a far country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 2, E'And at the season he sent to the husbandmen a servant, that he might receive from the husbandmen of the fruit of the vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 3, E'And they caught him, and beat him, and sent him away empty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 4, E'And again he sent unto them another servant; and at him they cast stones, and wounded him in the head, and sent him away shamefully handled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 5, E'And again he sent another; and him they killed, and many others; beating some, and killing some.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 6, E'Having yet therefore one son, his wellbeloved, he sent him also last unto them, saying, They will reverence my son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 7, E'But those husbandmen said among themselves, This is the heir; come, let us kill him, and the inheritance shall be ourâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 8, E'And they took him, and killed him, and cast him out of the vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 9, E'What shall therefore the lord of the vineyard do? he will come and destroy the husbandmen, and will give the vineyard unto others.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 10, E'And have ye not read this scripture; The stone which the builders rejected is become the head of the corner:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 11, E'This was the Lordâ€™s doing, and it is marvellous in our eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 12, E'And they sought to lay hold on him, but feared the people: for they knew that he had spoken the parable against them: and they left him, and went their way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 13, E'And they send unto him certain of the Pharisees and of the Herodians, to catch him in his words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 14, E'And when they were come, they say unto him, Master, we know that thou art true, and carest for no man: for thou regardest not the person of men, but teachest the way of God in truth: Is it lawful to give tribute to Caesar, or not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 15, E'Shall we give, or shall we not give? But he, knowing their hypocrisy, said unto them, Why tempt ye me? bring me a penny, that I may see it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 16, E'And they brought it. And he saith unto them, Whose is this image and superscription? And they said unto him, Caesarâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 17, E'And Jesus answering said unto them, Render to Caesar the things that are Caesarâ€™s, and to God the things that are Godâ€™s. And they marvelled at him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 18, E'Then come unto him the Sadducees, which say there is no resurrection; and they asked him, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 19, E'Master, Moses wrote unto us, If a manâ€™s brother die, and leave his wife behind him, and leave no children, that his brother should take his wife, and raise up seed unto his brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 20, E'Now there were seven brethren: and the first took a wife, and dying left no seed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 21, E'And the second took her, and died, neither left he any seed: and the third likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 22, E'And the seven had her, and left no seed: last of all the woman died also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 23, E'In the resurrection therefore, when they shall rise, whose wife shall she be of them? for the seven had her to wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 24, E'And Jesus answering said unto them, Do ye not therefore err, because ye know not the scriptures, neither the power of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 25, E'For when they shall rise from the dead, they neither marry, nor are given in marriage; but are as the angels which are in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 26, E'And as touching the dead, that they rise: have ye not read in the book of Moses, how in the bush God spake unto him, saying, I am the God of Abraham, and the God of Isaac, and the God of Jacob?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 27, E'He is not the God of the dead, but the God of the living: ye therefore do greatly err.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 28, E'And one of the scribes came, and having heard them reasoning together, and perceiving that he had answered them well, asked him, Which is the first commandment of all?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 29, E'And Jesus answered him, The first of all the commandments is, Hear, O Israel; The Lord our God is one Lord:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 30, E'And thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength: this is the first commandment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 31, E'And the second is like, namely this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 32, E'And the scribe said unto him, Well, Master, thou hast said the truth: for there is one God; and there is none other but he:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 33, E'And to love him with all the heart, and with all the understanding, and with all the soul, and with all the strength, and to love his neighbour as himself, is more than all whole burnt offerings and sacrifices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 34, E'And when Jesus saw that he answered discreetly, he said unto him, Thou art not far from the kingdom of God. And no man after that durst ask him any question.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 35, E'And Jesus answered and said, while he taught in the temple, How say the scribes that Christ is the son of David?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 36, E'For David himself said by the Holy Ghost, The LORD said to my Lord, Sit thou on my right hand, till I make thine enemies thy footstool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 37, E'David therefore himself calleth him Lord; and whence is he then his son? And the common people heard him gladly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 38, E'And he said unto them in his doctrine, Beware of the scribes, which love to go in long clothing, and love salutations in the marketplaces,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 39, E'And the chief seats in the synagogues, and the uppermost rooms at feasts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 40, E'Which devour widowsâ€™ houses, and for a pretence make long prayers: these shall receive greater damnation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 41, E'And Jesus sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 42, E'And there came a certain poor widow, and she threw in two mites, which make a farthing.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 43, E'And he called unto him his disciples, and saith unto them, Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 12, 44, E'For all they did cast in of their abundance; but she of her want did cast in all that she had, even all her living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 1, E'And as he went out of the temple, one of his disciples saith unto him, Master, see what manner of stones and what buildings are here!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 2, E'And Jesus answering said unto him, Seest thou these great buildings? there shall not be left one stone upon another, that shall not be thrown down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 3, E'And as he sat upon the mount of Olives over against the temple, Peter and James and John and Andrew asked him privately,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 4, E'Tell us, when shall these things be? and what shall be the sign when all these things shall be fulfilled?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 5, E'And Jesus answering them began to say, Take heed lest any man deceive you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 6, E'For many shall come in my name, saying, I am Christ; and shall deceive many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 7, E'And when ye shall hear of wars and rumours of wars, be ye not troubled: for such things must needs be; but the end shall not be yet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 8, E'For nation shall rise against nation, and kingdom against kingdom: and there shall be earthquakes in divers places, and there shall be famines and troubles: these are the beginnings of sorrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 9, E'But take heed to yourselves: for they shall deliver you up to councils; and in the synagogues ye shall be beaten: and ye shall be brought before rulers and kings for my sake, for a testimony against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 10, E'And the gospel must first be published among all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 11, E'But when they shall lead you, and deliver you up, take no thought beforehand what ye shall speak, neither do ye premeditate: but whatsoever shall be given you in that hour, that speak ye: for it is not ye that speak, but the Holy Ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 12, E'Now the brother shall betray the brother to death, and the father the son; and children shall rise up against their parents, and shall cause them to be put to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 13, E'And ye shall be hated of all men for my nameâ€™s sake: but he that shall endure unto the end, the same shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 14, E'But when ye shall see the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not, (let him that readeth understand,) then let them that be in Judaea flee to the mountains:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 15, E'And let him that is on the housetop not go down into the house, neither enter therein, to take any thing out of his house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 16, E'And let him that is in the field not turn back again for to take up his garment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 17, E'But woe to them that are with child, and to them that give suck in those days!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 18, E'And pray ye that your flight be not in the winter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 19, E'For in those days shall be affliction, such as was not from the beginning of the creation which God created unto this time, neither shall be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 20, E'And except that the Lord had shortened those days, no flesh should be saved: but for the electâ€™s sake, whom he hath chosen, he hath shortened the days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 21, E'And then if any man shall say to you, Lo, here is Christ; or, lo, he is there; believe him not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 22, E'For false Christs and false prophets shall rise, and shall shew signs and wonders, to seduce, if it were possible, even the elect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 23, E'But take ye heed: behold, I have foretold you all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 24, E'But in those days, after that tribulation, the sun shall be darkened, and the moon shall not give her light,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 25, E'And the stars of heaven shall fall, and the powers that are in heaven shall be shaken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 26, E'And then shall they see the Son of man coming in the clouds with great power and glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 27, E'And then shall he send his angels, and shall gather together his elect from the four winds, from the uttermost part of the earth to the uttermost part of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 28, E'Now learn a parable of the fig tree; When her branch is yet tender, and putteth forth leaves, ye know that summer is near:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 29, E'So ye in like manner, when ye shall see these things come to pass, know that it is nigh, even at the doors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 30, E'Verily I say unto you, that this generation shall not pass, till all these things be done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 31, E'Heaven and earth shall pass away: but my words shall not pass away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 32, E'But of that day and that hour knoweth no man, no, not the angels which are in heaven, neither the Son, but the Father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 33, E'Take ye heed, watch and pray: for ye know not when the time is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 34, E'For the Son of man is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 35, E'Watch ye therefore: for ye know not when the master of the house cometh, at even, or at midnight, or at the cockcrowing, or in the morning:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 36, E'Lest coming suddenly he find you sleeping.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 13, 37, E'And what I say unto you I say unto all, Watch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 1, E'After two days was the feast of the passover, and of unleavened bread: and the chief priests and the scribes sought how they might take him by craft, and put him to death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 2, E'But they said, Not on the feast day, lest there be an uproar of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 3, E'And being in Bethany in the house of Simon the leper, as he sat at meat, there came a woman having an alabaster box of ointment of spikenard very precious; and she brake the box, and poured it on his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 4, E'And there were some that had indignation within themselves, and said, Why was this waste of the ointment made?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 5, E'For it might have been sold for more than three hundred pence, and have been given to the poor. And they murmured against her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 6, E'And Jesus said, Let her alone; why trouble ye her? she hath wrought a good work on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 7, E'For ye have the poor with you always, and whensoever ye will ye may do them good: but me ye have not always.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 8, E'She hath done what she could: she is come aforehand to anoint my body to the burying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 9, E'Verily I say unto you, Wheresoever this gospel shall be preached throughout the whole world, this also that she hath done shall be spoken of for a memorial of her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 10, E'And Judas Iscariot, one of the twelve, went unto the chief priests, to betray him unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 11, E'And when they heard it, they were glad, and promised to give him money. And he sought how he might conveniently betray him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 12, E'And the first day of unleavened bread, when they killed the passover, his disciples said unto him, Where wilt thou that we go and prepare that thou mayest eat the passover?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 13, E'And he sendeth forth two of his disciples, and saith unto them, Go ye into the city, and there shall meet you a man bearing a pitcher of water: follow him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 14, E'And wheresoever he shall go in, say ye to the goodman of the house, The Master saith, Where is the guestchamber, where I shall eat the passover with my disciples?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 15, E'And he will shew you a large upper room furnished and prepared: there make ready for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 16, E'And his disciples went forth, and came into the city, and found as he had said unto them: and they made ready the passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 17, E'And in the evening he cometh with the twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 18, E'And as they sat and did eat, Jesus said, Verily I say unto you, One of you which eateth with me shall betray me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 19, E'And they began to be sorrowful, and to say unto him one by one, Is it I? and another said, Is it I?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 20, E'And he answered and said unto them, It is one of the twelve, that dippeth with me in the dish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 21, E'The Son of man indeed goeth, as it is written of him: but woe to that man by whom the Son of man is betrayed! good were it for that man if he had never been born.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 22, E'And as they did eat, Jesus took bread, and blessed, and brake it, and gave to them, and said, Take, eat: this is my body.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 23, E'And he took the cup, and when he had given thanks, he gave it to them: and they all drank of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 24, E'And he said unto them, This is my blood of the new testament, which is shed for many.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 25, E'Verily I say unto you, I will drink no more of the fruit of the vine, until that day that I drink it new in the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 26, E'And when they had sung an hymn, they went out into the mount of Olives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 27, E'And Jesus saith unto them, All ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep shall be scattered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 28, E'But after that I am risen, I will go before you into Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 29, E'But Peter said unto him, Although all shall be offended, yet will not I.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 30, E'And Jesus saith unto him, Verily I say unto thee, That this day, even in this night, before the cock crow twice, thou shalt deny me thrice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 31, E'But he spake the more vehemently, If I should die with thee, I will not deny thee in any wise. Likewise also said they all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 32, E'And they came to a place which was named Gethsemane: and he saith to his disciples, Sit ye here, while I shall pray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 33, E'And he taketh with him Peter and James and John, and began to be sore amazed, and to be very heavy;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 34, E'And saith unto them, My soul is exceeding sorrowful unto death: tarry ye here, and watch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 35, E'And he went forward a little, and fell on the ground, and prayed that, if it were possible, the hour might pass from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 36, E'And he said, Abba, Father, all things are possible unto thee; take away this cup from me: nevertheless not what I will, but what thou wilt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 37, E'And he cometh, and findeth them sleeping, and saith unto Peter, Simon, sleepest thou? couldest not thou watch one hour?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 38, E'Watch ye and pray, lest ye enter into temptation. The spirit truly is ready, but the flesh is weak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 39, E'And again he went away, and prayed, and spake the same words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 40, E'And when he returned, he found them asleep again, (for their eyes were heavy,) neither wist they what to answer him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 41, E'And he cometh the third time, and saith unto them, Sleep on now, and take your rest: it is enough, the hour is come; behold, the Son of man is betrayed into the hands of sinners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 42, E'Rise up, let us go; lo, he that betrayeth me is at hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 43, E'And immediately, while he yet spake, cometh Judas, one of the twelve, and with him a great multitude with swords and staves, from the chief priests and the scribes and the elders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 44, E'And he that betrayed him had given them a token, saying, Whomsoever I shall kiss, that same is he; take him, and lead him away safely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 45, E'And as soon as he was come, he goeth straightway to him, and saith, Master, master; and kissed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 46, E'And they laid their hands on him, and took him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 47, E'And one of them that stood by drew a sword, and smote a servant of the high priest, and cut off his ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 48, E'And Jesus answered and said unto them, Are ye come out, as against a thief, with swords and with staves to take me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 49, E'I was daily with you in the temple teaching, and ye took me not: but the scriptures must be fulfilled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 50, E'And they all forsook him, and fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 51, E'And there followed him a certain young man, having a linen cloth cast about his naked body; and the young men laid hold on him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 52, E'And he left the linen cloth, and fled from them naked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 53, E'And they led Jesus away to the high priest: and with him were assembled all the chief priests and the elders and the scribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 54, E'And Peter followed him afar off, even into the palace of the high priest: and he sat with the servants, and warmed himself at the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 55, E'And the chief priests and all the council sought for witness against Jesus to put him to death; and found none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 56, E'For many bare false witness against him, but their witness agreed not together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 57, E'And there arose certain, and bare false witness against him, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 58, E'We heard him say, I will destroy this temple that is made with hands, and within three days I will build another made without hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 59, E'But neither so did their witness agree together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 60, E'And the high priest stood up in the midst, and asked Jesus, saying, Answerest thou nothing? what is it which these witness against thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 61, E'But he held his peace, and answered nothing. Again the high priest asked him, and said unto him, Art thou the Christ, the Son of the Blessed?')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 62, E'And Jesus said, I am: and ye shall see the Son of man sitting on the right hand of power, and coming in the clouds of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 63, E'Then the high priest rent his clothes, and saith, What need we any further witnesses?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 64, E'Ye have heard the blasphemy: what think ye? And they all condemned him to be guilty of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 65, E'And some began to spit on him, and to cover his face, and to buffet him, and to say unto him, Prophesy: and the servants did strike him with the palms of their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 66, E'And as Peter was beneath in the palace, there cometh one of the maids of the high priest:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 67, E'And when she saw Peter warming himself, she looked upon him, and said, And thou also wast with Jesus of Nazareth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 68, E'But he denied, saying, I know not, neither understand I what thou sayest. And he went out into the porch; and the cock crew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 69, E'And a maid saw him again, and began to say to them that stood by, This is one of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 70, E'And he denied it again. And a little after, they that stood by said again to Peter, Surely thou art one of them: for thou art a Galilaean, and thy speech agreeth thereto.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 71, E'But he began to curse and to swear, saying, I know not this man of whom ye speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 14, 72, E'And the second time the cock crew. And Peter called to mind the word that Jesus said unto him, Before the cock crow twice, thou shalt deny me thrice. And when he thought thereon, he wept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 1, E'And straightway in the morning the chief priests held a consultation with the elders and scribes and the whole council, and bound Jesus, and carried him away, and delivered him to Pilate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 2, E'And Pilate asked him, Art thou the King of the Jews? And he answering said unto him, Thou sayest it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 3, E'And the chief priests accused him of many things: but he answered nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 4, E'And Pilate asked him again, saying, Answerest thou nothing? behold how many things they witness against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 5, E'But Jesus yet answered nothing; so that Pilate marvelled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 6, E'Now at that feast he released unto them one prisoner, whomsoever they desired.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 7, E'And there was one named Barabbas, which lay bound with them that had made insurrection with him, who had committed murder in the insurrection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 8, E'And the multitude crying aloud began to desire him to do as he had ever done unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 9, E'But Pilate answered them, saying, Will ye that I release unto you the King of the Jews?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 10, E'For he knew that the chief priests had delivered him for envy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 11, E'But the chief priests moved the people, that he should rather release Barabbas unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 12, E'And Pilate answered and said again unto them, What will ye then that I shall do unto him whom ye call the King of the Jews?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 13, E'And they cried out again, Crucify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 14, E'Then Pilate said unto them, Why, what evil hath he done? And they cried out the more exceedingly, Crucify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 15, E'And so Pilate, willing to content the people, released Barabbas unto them, and delivered Jesus, when he had scourged him, to be crucified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 16, E'And the soldiers led him away into the hall, called Praetorium; and they call together the whole band.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 17, E'And they clothed him with purple, and platted a crown of thorns, and put it about his head,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 18, E'And began to salute him, Hail, King of the Jews!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 19, E'And they smote him on the head with a reed, and did spit upon him, and bowing their knees worshipped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 20, E'And when they had mocked him, they took off the purple from him, and put his own clothes on him, and led him out to crucify him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 21, E'And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 22, E'And they bring him unto the place Golgotha, which is, being interpreted, The place of a skull.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 23, E'And they gave him to drink wine mingled with myrrh: but he received it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 24, E'And when they had crucified him, they parted his garments, casting lots upon them, what every man should take.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 25, E'And it was the third hour, and they crucified him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 26, E'And the superscription of his accusation was written over, THE KING OF THE JEWS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 27, E'And with him they crucify two thieves; the one on his right hand, and the other on his left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 28, E'And the scripture was fulfilled, which saith, And he was numbered with the transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 29, E'And they that passed by railed on him, wagging their heads, and saying, Ah, thou that destroyest the temple, and buildest it in three days,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 30, E'Save thyself, and come down from the cross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 31, E'Likewise also the chief priests mocking said among themselves with the scribes, He saved others; himself he cannot save.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 32, E'Let Christ the King of Israel descend now from the cross, that we may see and believe. And they that were crucified with him reviled him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 33, E'And when the sixth hour was come, there was darkness over the whole land until the ninth hour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 34, E'And at the ninth hour Jesus cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My God, my God, why hast thou forsaken me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 35, E'And some of them that stood by, when they heard it, said, Behold, he calleth Elias.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 36, E'And one ran and filled a spunge full of vinegar, and put it on a reed, and gave him to drink, saying, Let alone; let us see whether Elias will come to take him down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 37, E'And Jesus cried with a loud voice, and gave up the ghost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 38, E'And the veil of the temple was rent in twain from the top to the bottom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 39, E'And when the centurion, which stood over against him, saw that he so cried out, and gave up the ghost, he said, Truly this man was the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 40, E'There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 41, E'(Who also, when he was in Galilee, followed him, and ministered unto him;) and many other women which came up with him unto Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 42, E'And now when the even was come, because it was the preparation, that is, the day before the sabbath,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 43, E'Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 44, E'And Pilate marvelled if he were already dead: and calling unto him the centurion, he asked him whether he had been any while dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 45, E'And when he knew it of the centurion, he gave the body to Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 46, E'And he bought fine linen, and took him down, and wrapped him in the linen, and laid him in a sepulchre which was hewn out of a rock, and rolled a stone unto the door of the sepulchre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 15, 47, E'And Mary Magdalene and Mary the mother of Joses beheld where he was laid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 1, E'And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 2, E'And very early in the morning the first day of the week, they came unto the sepulchre at the rising of the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 3, E'And they said among themselves, Who shall roll us away the stone from the door of the sepulchre?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 4, E'And when they looked, they saw that the stone was rolled away: for it was very great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 5, E'And entering into the sepulchre, they saw a young man sitting on the right side, clothed in a long white garment; and they were affrighted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 6, E'And he saith unto them, Be not affrighted: Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here: behold the place where they laid him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 7, E'But go your way, tell his disciples and Peter that he goeth before you into Galilee: there shall ye see him, as he said unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 8, E'And they went out quickly, and fled from the sepulchre; for they trembled and were amazed: neither said they any thing to any man; for they were afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 9, E'Now when Jesus was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 10, E'And she went and told them that had been with him, as they mourned and wept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 11, E'And they, when they had heard that he was alive, and had been seen of her, believed not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 12, E'After that he appeared in another form unto two of them, as they walked, and went into the country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 13, E'And they went and told it unto the residue: neither believed they them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 14, E'Afterward he appeared unto the eleven as they sat at meat, and upbraided them with their unbelief and hardness of heart, because they believed not them which had seen him after he was risen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 15, E'And he said unto them, Go ye into all the world, and preach the gospel to every creature.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 16, E'He that believeth and is baptized shall be saved; but he that believeth not shall be damned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 17, E'And these signs shall follow them that believe; In my name shall they cast out devils; they shall speak with new tongues;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 18, E'They shall take up serpents; and if they drink any deadly thing, it shall not hurt them; they shall lay hands on the sick, and they shall recover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 19, E'So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '7d9d1a60-fd3b-4d0e-8ef1-9a6282d8f149', 16, 20, E'And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Mark') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 1, E'Forasmuch as many have taken in hand to set forth in order a declaration of those things which are most surely believed among us,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 2, E'Even as they delivered them unto us, which from the beginning were eyewitnesses, and ministers of the word;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 3, E'It seemed good to me also, having had perfect understanding of all things from the very first, to write unto thee in order, most excellent Theophilus,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 4, E'That thou mightest know the certainty of those things, wherein thou hast been instructed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 5, E'There was in the days of Herod, the king of Judaea, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 6, E'And they were both righteous before God, walking in all the commandments and ordinances of the Lord blameless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 7, E'And they had no child, because that Elisabeth was barren, and they both were now well stricken in years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 8, E'And it came to pass, that while he executed the priestâ€™s office before God in the order of his course,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 9, E'According to the custom of the priestâ€™s office, his lot was to burn incense when he went into the temple of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 10, E'And the whole multitude of the people were praying without at the time of incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 11, E'And there appeared unto him an angel of the Lord standing on the right side of the altar of incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 12, E'And when Zacharias saw him, he was troubled, and fear fell upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 13, E'But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 14, E'And thou shalt have joy and gladness; and many shall rejoice at his birth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 15, E'For he shall be great in the sight of the Lord, and shall drink neither wine nor strong drink; and he shall be filled with the Holy Ghost, even from his motherâ€™s womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 16, E'And many of the children of Israel shall he turn to the Lord their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 17, E'And he shall go before him in the spirit and power of Elias, to turn the hearts of the fathers to the children, and the disobedient to the wisdom of the just; to make ready a people prepared for the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 18, E'And Zacharias said unto the angel, Whereby shall I know this? for I am an old man, and my wife well stricken in years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 19, E'And the angel answering said unto him, I am Gabriel, that stand in the presence of God; and am sent to speak unto thee, and to shew thee these glad tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 20, E'And, behold, thou shalt be dumb, and not able to speak, until the day that these things shall be performed, because thou believest not my words, which shall be fulfilled in their season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 21, E'And the people waited for Zacharias, and marvelled that he tarried so long in the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 22, E'And when he came out, he could not speak unto them: and they perceived that he had seen a vision in the temple: for he beckoned unto them, and remained speechless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 23, E'And it came to pass, that, as soon as the days of his ministration were accomplished, he departed to his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 24, E'And after those days his wife Elisabeth conceived, and hid herself five months, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 25, E'Thus hath the Lord dealt with me in the days wherein he looked on me, to take away my reproach among men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 26, E'And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 27, E'To a virgin espoused to a man whose name was Joseph, of the house of David; and the virginâ€™s name was Mary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 28, E'And the angel came in unto her, and said, Hail, thou that art highly favoured, the Lord is with thee: blessed art thou among women.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 29, E'And when she saw him, she was troubled at his saying, and cast in her mind what manner of salutation this should be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 30, E'And the angel said unto her, Fear not, Mary: for thou hast found favour with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 31, E'And, behold, thou shalt conceive in thy womb, and bring forth a son, and shalt call his name JESUS.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 32, E'He shall be great, and shall be called the Son of the Highest: and the Lord God shall give unto him the throne of his father David:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 33, E'And he shall reign over the house of Jacob for ever; and of his kingdom there shall be no end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 34, E'Then said Mary unto the angel, How shall this be, seeing I know not a man?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 35, E'And the angel answered and said unto her, The Holy Ghost shall come upon thee, and the power of the Highest shall overshadow thee: therefore also that holy thing which shall be born of thee shall be called the Son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 36, E'And, behold, thy cousin Elisabeth, she hath also conceived a son in her old age: and this is the sixth month with her, who was called barren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 37, E'For with God nothing shall be impossible.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 38, E'And Mary said, Behold the handmaid of the Lord; be it unto me according to thy word. And the angel departed from her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 39, E'And Mary arose in those days, and went into the hill country with haste, into a city of Juda;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 40, E'And entered into the house of Zacharias, and saluted Elisabeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 41, E'And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 42, E'And she spake out with a loud voice, and said, Blessed art thou among women, and blessed is the fruit of thy womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 43, E'And whence is this to me, that the mother of my Lord should come to me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 44, E'For, lo, as soon as the voice of thy salutation sounded in mine ears, the babe leaped in my womb for joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 45, E'And blessed is she that believed: for there shall be a performance of those things which were told her from the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 46, E'And Mary said, My soul doth magnify the Lord,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 47, E'And my spirit hath rejoiced in God my Saviour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 48, E'For he hath regarded the low estate of his handmaiden: for, behold, from henceforth all generations shall call me blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 49, E'For he that is mighty hath done to me great things; and holy is his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 50, E'And his mercy is on them that fear him from generation to generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 51, E'He hath shewed strength with his arm; he hath scattered the proud in the imagination of their hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 52, E'He hath put down the mighty from their seats, and exalted them of low degree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 53, E'He hath filled the hungry with good things; and the rich he hath sent empty away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 54, E'He hath holpen his servant Israel, in remembrance of his mercy;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 55, E'As he spake to our fathers, to Abraham, and to his seed for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 56, E'And Mary abode with her about three months, and returned to her own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 57, E'Now Elisabethâ€™s full time came that she should be delivered; and she brought forth a son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 58, E'And her neighbours and her cousins heard how the Lord had shewed great mercy upon her; and they rejoiced with her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 59, E'And it came to pass, that on the eighth day they came to circumcise the child; and they called him Zacharias, after the name of his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 60, E'And his mother answered and said, Not so; but he shall be called John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 61, E'And they said unto her, There is none of thy kindred that is called by this name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 62, E'And they made signs to his father, how he would have him called.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 63, E'And he asked for a writing table, and wrote, saying, His name is John. And they marvelled all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 64, E'And his mouth was opened immediately, and his tongue loosed, and he spake, and praised God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 65, E'And fear came on all that dwelt round about them: and all these sayings were noised abroad throughout all the hill country of Judaea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 66, E'And all they that heard them laid them up in their hearts, saying, What manner of child shall this be! And the hand of the Lord was with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 67, E'And his father Zacharias was filled with the Holy Ghost, and prophesied, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 68, E'Blessed be the Lord God of Israel; for he hath visited and redeemed his people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 69, E'And hath raised up an horn of salvation for us in the house of his servant David;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 70, E'As he spake by the mouth of his holy prophets, which have been since the world began:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 71, E'That we should be saved from our enemies, and from the hand of all that hate us;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 72, E'To perform the mercy promised to our fathers, and to remember his holy covenant;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 73, E'The oath which he sware to our father Abraham,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 74, E'That he would grant unto us, that we being delivered out of the hand of our enemies might serve him without fear,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 75, E'In holiness and righteousness before him, all the days of our life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 76, E'And thou, child, shalt be called the prophet of the Highest: for thou shalt go before the face of the Lord to prepare his ways;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 77, E'To give knowledge of salvation unto his people by the remission of their sins,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 78, E'Through the tender mercy of our God; whereby the dayspring from on high hath visited us,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 79, E'To give light to them that sit in darkness and in the shadow of death, to guide our feet into the way of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 1, 80, E'And the child grew, and waxed strong in spirit, and was in the deserts till the day of his shewing unto Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 1, E'And it came to pass in those days, that there went out a decree from Caesar Augustus, that all the world should be taxed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 2, E'(And this taxing was first made when Cyrenius was governor of Syria.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 3, E'And all went to be taxed, every one into his own city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 4, E'And Joseph also went up from Galilee, out of the city of Nazareth, into Judaea, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 5, E'To be taxed with Mary his espoused wife, being great with child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 6, E'And so it was, that, while they were there, the days were accomplished that she should be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 7, E'And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 8, E'And there were in the same country shepherds abiding in the field, keeping watch over their flock by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 9, E'And, lo, the angel of the Lord came upon them, and the glory of the Lord shone round about them: and they were sore afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 10, E'And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 11, E'For unto you is born this day in the city of David a Saviour, which is Christ the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 12, E'And this shall be a sign unto you; Ye shall find the babe wrapped in swaddling clothes, lying in a manger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 13, E'And suddenly there was with the angel a multitude of the heavenly host praising God, and saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 14, E'Glory to God in the highest, and on earth peace, good will toward men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 15, E'And it came to pass, as the angels were gone away from them into heaven, the shepherds said one to another, Let us now go even unto Bethlehem, and see this thing which is come to pass, which the Lord hath made known unto us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 16, E'And they came with haste, and found Mary, and Joseph, and the babe lying in a manger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 17, E'And when they had seen it, they made known abroad the saying which was told them concerning this child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 18, E'And all they that heard it wondered at those things which were told them by the shepherds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 19, E'But Mary kept all these things, and pondered them in her heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 20, E'And the shepherds returned, glorifying and praising God for all the things that they had heard and seen, as it was told unto them.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 21, E'And when eight days were accomplished for the circumcising of the child, his name was called JESUS, which was so named of the angel before he was conceived in the womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 22, E'And when the days of her purification according to the law of Moses were accomplished, they brought him to Jerusalem, to present him to the Lord;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 23, E'(As it is written in the law of the LORD, Every male that openeth the womb shall be called holy to the Lord;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 24, E'And to offer a sacrifice according to that which is said in the law of the Lord, A pair of turtledoves, or two young pigeons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 25, E'And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 26, E'And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lordâ€™s Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 27, E'And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 28, E'Then took he him up in his arms, and blessed God, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 29, E'Lord, now lettest thou thy servant depart in peace, according to thy word:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 30, E'For mine eyes have seen thy salvation,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 31, E'Which thou hast prepared before the face of all people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 32, E'A light to lighten the Gentiles, and the glory of thy people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 33, E'And Joseph and his mother marvelled at those things which were spoken of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 34, E'And Simeon blessed them, and said unto Mary his mother, Behold, this child is set for the fall and rising again of many in Israel; and for a sign which shall be spoken against;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 35, E'(Yea, a sword shall pierce through thy own soul also,) that the thoughts of many hearts may be revealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 36, E'And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 37, E'And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 38, E'And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 39, E'And when they had performed all things according to the law of the Lord, they returned into Galilee, to their own city Nazareth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 40, E'And the child grew, and waxed strong in spirit, filled with wisdom: and the grace of God was upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 41, E'Now his parents went to Jerusalem every year at the feast of the passover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 42, E'And when he was twelve years old, they went up to Jerusalem after the custom of the feast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 43, E'And when they had fulfilled the days, as they returned, the child Jesus tarried behind in Jerusalem; and Joseph and his mother knew not of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 44, E'But they, supposing him to have been in the company, went a dayâ€™s journey; and they sought him among their kinsfolk and acquaintance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 45, E'And when they found him not, they turned back again to Jerusalem, seeking him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 46, E'And it came to pass, that after three days they found him in the temple, sitting in the midst of the doctors, both hearing them, and asking them questions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 47, E'And all that heard him were astonished at his understanding and answers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 48, E'And when they saw him, they were amazed: and his mother said unto him, Son, why hast thou thus dealt with us? behold, thy father and I have sought thee sorrowing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 49, E'And he said unto them, How is it that ye sought me? wist ye not that I must be about my Fatherâ€™s business?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 50, E'And they understood not the saying which he spake unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 51, E'And he went down with them, and came to Nazareth, and was subject unto them: but his mother kept all these sayings in her heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 2, 52, E'And Jesus increased in wisdom and stature, and in favour with God and man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 1, E'Now in the fifteenth year of the reign of Tiberius Caesar, Pontius Pilate being governor of Judaea, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Ituraea and of the region of Trachonitis, and Lysanias the tetrarch of Abilene,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 2, E'Annas and Caiaphas being the high priests, the word of God came unto John the son of Zacharias in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 3, E'And he came into all the country about Jordan, preaching the baptism of repentance for the remission of sins;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 4, E'As it is written in the book of the words of Esaias the prophet, saying, The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 5, E'Every valley shall be filled, and every mountain and hill shall be brought low; and the crooked shall be made straight, and the rough ways shall be made smooth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 6, E'And all flesh shall see the salvation of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 7, E'Then said he to the multitude that came forth to be baptized of him, O generation of vipers, who hath warned you to flee from the wrath to come?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 8, E'Bring forth therefore fruits worthy of repentance, and begin not to say within yourselves, We have Abraham to our father: for I say unto you, That God is able of these stones to raise up children unto Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 9, E'And now also the axe is laid unto the root of the trees: every tree therefore which bringeth not forth good fruit is hewn down, and cast into the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 10, E'And the people asked him, saying, What shall we do then?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 11, E'He answereth and saith unto them, He that hath two coats, let him impart to him that hath none; and he that hath meat, let him do likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 12, E'Then came also publicans to be baptized, and said unto him, Master, what shall we do?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 13, E'And he said unto them, Exact no more than that which is appointed you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 14, E'And the soldiers likewise demanded of him, saying, And what shall we do? And he said unto them, Do violence to no man, neither accuse any falsely; and be content with your wages.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 15, E'And as the people were in expectation, and all men mused in their hearts of John, whether he were the Christ, or not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 16, E'John answered, saying unto them all, I indeed baptize you with water; but one mightier than I cometh, the latchet of whose shoes I am not worthy to unloose: he shall baptize you with the Holy Ghost and with fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 17, E'Whose fan is in his hand, and he will throughly purge his floor, and will gather the wheat into his garner; but the chaff he will burn with fire unquenchable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 18, E'And many other things in his exhortation preached he unto the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 19, E'But Herod the tetrarch, being reproved by him for Herodias his brother Philipâ€™s wife, and for all the evils which Herod had done,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 20, E'Added yet this above all, that he shut up John in prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 21, E'Now when all the people were baptized, it came to pass, that Jesus also being baptized, and praying, the heaven was opened,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 22, E'And the Holy Ghost descended in a bodily shape like a dove upon him, and a voice came from heaven, which said, Thou art my beloved Son; in thee I am well pleased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 23, E'And Jesus himself began to be about thirty years of age, being (as was supposed) the son of Joseph, which was the son of Heli,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 24, E'Which was the son of Matthat, which was the son of Levi, which was the son of Melchi, which was the son of Janna, which was the son of Joseph,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 25, E'Which was the son of Mattathias, which was the son of Amos, which was the son of Naum, which was the son of Esli, which was the son of Nagge,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 26, E'Which was the son of Maath, which was the son of Mattathias, which was the son of Semei, which was the son of Joseph, which was the son of Juda,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 27, E'Which was the son of Joanna, which was the son of Rhesa, which was the son of Zorobabel, which was the son of Salathiel, which was the son of Neri,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 28, E'Which was the son of Melchi, which was the son of Addi, which was the son of Cosam, which was the son of Elmodam, which was the son of Er,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 29, E'Which was the son of Jose, which was the son of Eliezer, which was the son of Jorim, which was the son of Matthat, which was the son of Levi,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 30, E'Which was the son of Simeon, which was the son of Juda, which was the son of Joseph, which was the son of Jonan, which was the son of Eliakim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 31, E'Which was the son of Melea, which was the son of Menan, which was the son of Mattatha, which was the son of Nathan, which was the son of David,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 32, E'Which was the son of Jesse, which was the son of Obed, which was the son of Booz, which was the son of Salmon, which was the son of Naasson,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 33, E'Which was the son of Aminadab, which was the son of Aram, which was the son of Esrom, which was the son of Phares, which was the son of Juda,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 34, E'Which was the son of Jacob, which was the son of Isaac, which was the son of Abraham, which was the son of Thara, which was the son of Nachor,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 35, E'Which was the son of Saruch, which was the son of Ragau, which was the son of Phalec, which was the son of Heber, which was the son of Sala,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 36, E'Which was the son of Cainan, which was the son of Arphaxad, which was the son of Sem, which was the son of Noe, which was the son of Lamech,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 37, E'Which was the son of Mathusala, which was the son of Enoch, which was the son of Jared, which was the son of Maleleel, which was the son of Cainan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 3, 38, E'Which was the son of Enos, which was the son of Seth, which was the son of Adam, which was the son of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 1, E'And Jesus being full of the Holy Ghost returned from Jordan, and was led by the Spirit into the wilderness,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 2, E'Being forty days tempted of the devil. And in those days he did eat nothing: and when they were ended, he afterward hungered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 3, E'And the devil said unto him, If thou be the Son of God, command this stone that it be made bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 4, E'And Jesus answered him, saying, It is written, That man shall not live by bread alone, but by every word of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 5, E'And the devil, taking him up into an high mountain, shewed unto him all the kingdoms of the world in a moment of time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 6, E'And the devil said unto him, All this power will I give thee, and the glory of them: for that is delivered unto me; and to whomsoever I will I give it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 7, E'If thou therefore wilt worship me, all shall be thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 8, E'And Jesus answered and said unto him, Get thee behind me, Satan: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 9, E'And he brought him to Jerusalem, and set him on a pinnacle of the temple, and said unto him, If thou be the Son of God, cast thyself down from hence:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 10, E'For it is written, He shall give his angels charge over thee, to keep thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 11, E'And in their hands they shall bear thee up, lest at any time thou dash thy foot against a stone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 12, E'And Jesus answering said unto him, It is said, Thou shalt not tempt the Lord thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 13, E'And when the devil had ended all the temptation, he departed from him for a season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 14, E'And Jesus returned in the power of the Spirit into Galilee: and there went out a fame of him through all the region round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 15, E'And he taught in their synagogues, being glorified of all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 16, E'And he came to Nazareth, where he had been brought up: and, as his custom was, he went into the synagogue on the sabbath day, and stood up for to read.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 17, E'And there was delivered unto him the book of the prophet Esaias. And when he had opened the book, he found the place where it was written,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 18, E'The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 19, E'To preach the acceptable year of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 20, E'And he closed the book, and he gave it again to the minister, and sat down. And the eyes of all them that were in the synagogue were fastened on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 21, E'And he began to say unto them, This day is this scripture fulfilled in your ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 22, E'And all bare him witness, and wondered at the gracious words which proceeded out of his mouth. And they said, Is not this Josephâ€™s son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 23, E'And he said unto them, Ye will surely say unto me this proverb, Physician, heal thyself: whatsoever we have heard done in Capernaum, do also here in thy country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 24, E'And he said, Verily I say unto you, No prophet is accepted in his own country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 25, E'But I tell you of a truth, many widows were in Israel in the days of Elias, when the heaven was shut up three years and six months, when great famine was throughout all the land;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 26, E'But unto none of them was Elias sent, save unto Sarepta, a city of Sidon, unto a woman that was a widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 27, E'And many lepers were in Israel in the time of Eliseus the prophet; and none of them was cleansed, saving Naaman the Syrian.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 28, E'And all they in the synagogue, when they heard these things, were filled with wrath,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 29, E'And rose up, and thrust him out of the city, and led him unto the brow of the hill whereon their city was built, that they might cast him down headlong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 30, E'But he passing through the midst of them went his way,')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 31, E'And came down to Capernaum, a city of Galilee, and taught them on the sabbath days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 32, E'And they were astonished at his doctrine: for his word was with power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 33, E'And in the synagogue there was a man, which had a spirit of an unclean devil, and cried out with a loud voice,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 34, E'Saying, Let us alone; what have we to do with thee, thou Jesus of Nazareth? art thou come to destroy us? I know thee who thou art; the Holy One of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 35, E'And Jesus rebuked him, saying, Hold thy peace, and come out of him. And when the devil had thrown him in the midst, he came out of him, and hurt him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 36, E'And they were all amazed, and spake among themselves, saying, What a word is this! for with authority and power he commandeth the unclean spirits, and they come out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 37, E'And the fame of him went out into every place of the country round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 38, E'And he arose out of the synagogue, and entered into Simonâ€™s house. And Simonâ€™s wifeâ€™s mother was taken with a great fever; and they besought him for her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 39, E'And he stood over her, and rebuked the fever; and it left her: and immediately she arose and ministered unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 40, E'Now when the sun was setting, all they that had any sick with divers diseases brought them unto him; and he laid his hands on every one of them, and healed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 41, E'And devils also came out of many, crying out, and saying, Thou art Christ the Son of God. And he rebuking them suffered them not to speak: for they knew that he was Christ.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 42, E'And when it was day, he departed and went into a desert place: and the people sought him, and came unto him, and stayed him, that he should not depart from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 43, E'And he said unto them, I must preach the kingdom of God to other cities also: for therefore am I sent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 4, 44, E'And he preached in the synagogues of Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 1, E'And it came to pass, that, as the people pressed upon him to hear the word of God, he stood by the lake of Gennesaret,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 2, E'And saw two ships standing by the lake: but the fishermen were gone out of them, and were washing their nets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 3, E'And he entered into one of the ships, which was Simonâ€™s, and prayed him that he would thrust out a little from the land. And he sat down, and taught the people out of the ship.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 4, E'Now when he had left speaking, he said unto Simon, Launch out into the deep, and let down your nets for a draught.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 5, E'And Simon answering said unto him, Master, we have toiled all the night, and have taken nothing: nevertheless at thy word I will let down the net.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 6, E'And when they had this done, they inclosed a great multitude of fishes: and their net brake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 7, E'And they beckoned unto their partners, which were in the other ship, that they should come and help them. And they came, and filled both the ships, so that they began to sink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 8, E'When Simon Peter saw it, he fell down at Jesusâ€™ knees, saying, Depart from me; for I am a sinful man, O Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 9, E'For he was astonished, and all that were with him, at the draught of the fishes which they had taken:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 10, E'And so was also James, and John, the sons of Zebedee, which were partners with Simon. And Jesus said unto Simon, Fear not; from henceforth thou shalt catch men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 11, E'And when they had brought their ships to land, they forsook all, and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 12, E'And it came to pass, when he was in a certain city, behold a man full of leprosy: who seeing Jesus fell on his face, and besought him, saying, Lord, if thou wilt, thou canst make me clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 13, E'And he put forth his hand, and touched him, saying, I will: be thou clean. And immediately the leprosy departed from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 14, E'And he charged him to tell no man: but go, and shew thyself to the priest, and offer for thy cleansing, according as Moses commanded, for a testimony unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 15, E'But so much the more went there a fame abroad of him: and great multitudes came together to hear, and to be healed by him of their infirmities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 16, E'And he withdrew himself into the wilderness, and prayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 17, E'And it came to pass on a certain day, as he was teaching, that there were Pharisees and doctors of the law sitting by, which were come out of every town of Galilee, and Judaea, and Jerusalem: and the power of the Lord was present to heal them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 18, E'And, behold, men brought in a bed a man which was taken with a palsy: and they sought means to bring him in, and to lay him before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 19, E'And when they could not find by what way they might bring him in because of the multitude, they went upon the housetop, and let him down through the tiling with his couch into the midst before Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 20, E'And when he saw their faith, he said unto him, Man, thy sins are forgiven thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 21, E'And the scribes and the Pharisees began to reason, saying, Who is this which speaketh blasphemies? Who can forgive sins, but God alone?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 22, E'But when Jesus perceived their thoughts, he answering said unto them, What reason ye in your hearts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 23, E'Whether is easier, to say, Thy sins be forgiven thee; or to say, Rise up and walk?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 24, E'But that ye may know that the Son of man hath power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto thee, Arise, and take up thy couch, and go into thine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 25, E'And immediately he rose up before them, and took up that whereon he lay, and departed to his own house, glorifying God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 26, E'And they were all amazed, and they glorified God, and were filled with fear, saying, We have seen strange things to day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 27, E'And after these things he went forth, and saw a publican, named Levi, sitting at the receipt of custom: and he said unto him, Follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 28, E'And he left all, rose up, and followed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 29, E'And Levi made him a great feast in his own house: and there was a great company of publicans and of others that sat down with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 30, E'But their scribes and Pharisees murmured against his disciples, saying, Why do ye eat and drink with publicans and sinners?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 31, E'And Jesus answering said unto them, They that are whole need not a physician; but they that are sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 32, E'I came not to call the righteous, but sinners to repentance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 33, E'And they said unto him, Why do the disciples of John fast often, and make prayers, and likewise the disciples of the Pharisees; but thine eat and drink?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 34, E'And he said unto them, Can ye make the children of the bridechamber fast, while the bridegroom is with them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 35, E'But the days will come, when the bridegroom shall be taken away from them, and then shall they fast in those days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 36, E'And he spake also a parable unto them; No man putteth a piece of a new garment upon an old; if otherwise, then both the new maketh a rent, and the piece that was taken out of the new agreeth not with the old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 37, E'And no man putteth new wine into old bottles; else the new wine will burst the bottles, and be spilled, and the bottles shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 38, E'But new wine must be put into new bottles; and both are preserved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 5, 39, E'No man also having drunk old wine straightway desireth new: for he saith, The old is better.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 1, E'And it came to pass on the second sabbath after the first, that he went through the corn fields; and his disciples plucked the ears of corn, and did eat, rubbing them in their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 2, E'And certain of the Pharisees said unto them, Why do ye that which is not lawful to do on the sabbath days?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 3, E'And Jesus answering them said, Have ye not read so much as this, what David did, when himself was an hungred, and they which were with him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 4, E'How he went into the house of God, and did take and eat the shewbread, and gave also to them that were with him; which it is not lawful to eat but for the priests alone?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 5, E'And he said unto them, That the Son of man is Lord also of the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 6, E'And it came to pass also on another sabbath, that he entered into the synagogue and taught: and there was a man whose right hand was withered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 7, E'And the scribes and Pharisees watched him, whether he would heal on the sabbath day; that they might find an accusation against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 8, E'But he knew their thoughts, and said to the man which had the withered hand, Rise up, and stand forth in the midst. And he arose and stood forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 9, E'Then said Jesus unto them, I will ask you one thing; Is it lawful on the sabbath days to do good, or to do evil? to save life, or to destroy it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 10, E'And looking round about upon them all, he said unto the man, Stretch forth thy hand. And he did so: and his hand was restored whole as the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 11, E'And they were filled with madness; and communed one with another what they might do to Jesus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 12, E'And it came to pass in those days, that he went out into a mountain to pray, and continued all night in prayer to God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 13, E'And when it was day, he called unto him his disciples: and of them he chose twelve, whom also he named apostles;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 14, E'Simon, (whom he also named Peter,) and Andrew his brother, James and John, Philip and Bartholomew,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 15, E'Matthew and Thomas, James the son of Alphaeus, and Simon called Zelotes,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 16, E'And Judas the brother of James, and Judas Iscariot, which also was the traitor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 17, E'And he came down with them, and stood in the plain, and the company of his disciples, and a great multitude of people out of all Judaea and Jerusalem, and from the sea coast of Tyre and Sidon, which came to hear him, and to be healed of their diseases;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 18, E'And they that were vexed with unclean spirits: and they were healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 19, E'And the whole multitude sought to touch him: for there went virtue out of him, and healed them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 20, E'And he lifted up his eyes on his disciples, and said, Blessed be ye poor: for yours is the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 21, E'Blessed are ye that hunger now: for ye shall be filled. Blessed are ye that weep now: for ye shall laugh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 22, E'Blessed are ye, when men shall hate you, and when they shall separate you from their company, and shall reproach you, and cast out your name as evil, for the Son of manâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 23, E'Rejoice ye in that day, and leap for joy: for, behold, your reward is great in heaven: for in the like manner did their fathers unto the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 24, E'But woe unto you that are rich! for ye have received your consolation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 25, E'Woe unto you that are full! for ye shall hunger. Woe unto you that laugh now! for ye shall mourn and weep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 26, E'Woe unto you, when all men shall speak well of you! for so did their fathers to the false prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 27, E'But I say unto you which hear, Love your enemies, do good to them which hate you,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 28, E'Bless them that curse you, and pray for them which despitefully use you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 29, E'And unto him that smiteth thee on the one cheek offer also the other; and him that taketh away thy cloak forbid not to take thy coat also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 30, E'Give to every man that asketh of thee; and of him that taketh away thy goods ask them not again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 31, E'And as ye would that men should do to you, do ye also to them likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 32, E'For if ye love them which love you, what thank have ye? for sinners also love those that love them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 33, E'And if ye do good to them which do good to you, what thank have ye? for sinners also do even the same.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 34, E'And if ye lend to them of whom ye hope to receive, what thank have ye? for sinners also lend to sinners, to receive as much again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 35, E'But love ye your enemies, and do good, and lend, hoping for nothing again; and your reward shall be great, and ye shall be the children of the Highest: for he is kind unto the unthankful and to the evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 36, E'Be ye therefore merciful, as your Father also is merciful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 37, E'Judge not, and ye shall not be judged: condemn not, and ye shall not be condemned: forgive, and ye shall be forgiven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 38, E'Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 39, E'And he spake a parable unto them, Can the blind lead the blind? shall they not both fall into the ditch?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 40, E'The disciple is not above his master: but every one that is perfect shall be as his master.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 41, E'And why beholdest thou the mote that is in thy brotherâ€™s eye, but perceivest not the beam that is in thine own eye?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 42, E'Either how canst thou say to thy brother, Brother, let me pull out the mote that is in thine eye, when thou thyself beholdest not the beam that is in thine own eye? Thou hypocrite, cast out first the beam out of thine own eye, and then shalt thou see clearly to pull out the mote that is in thy brotherâ€™s eye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 43, E'For a good tree bringeth not forth corrupt fruit; neither doth a corrupt tree bring forth good fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 44, E'For every tree is known by his own fruit. For of thorns men do not gather figs, nor of a bramble bush gather they grapes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 45, E'A good man out of the good treasure of his heart bringeth forth that which is good; and an evil man out of the evil treasure of his heart bringeth forth that which is evil: for of the abundance of the heart his mouth speaketh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 46, E'And why call ye me, Lord, Lord, and do not the things which I say?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 47, E'Whosoever cometh to me, and heareth my sayings, and doeth them, I will shew you to whom he is like:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 48, E'He is like a man which built an house, and digged deep, and laid the foundation on a rock: and when the flood arose, the stream beat vehemently upon that house, and could not shake it: for it was founded upon a rock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 6, 49, E'But he that heareth, and doeth not, is like a man that without a foundation built an house upon the earth; against which the stream did beat vehemently, and immediately it fell; and the ruin of that house was great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 1, E'Now when he had ended all his sayings in the audience of the people, he entered into Capernaum.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 2, E'And a certain centurionâ€™s servant, who was dear unto him, was sick, and ready to die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 3, E'And when he heard of Jesus, he sent unto him the elders of the Jews, beseeching him that he would come and heal his servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 4, E'And when they came to Jesus, they besought him instantly, saying, That he was worthy for whom he should do this:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 5, E'For he loveth our nation, and he hath built us a synagogue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 6, E'Then Jesus went with them. And when he was now not far from the house, the centurion sent friends to him, saying unto him, Lord, trouble not thyself: for I am not worthy that thou shouldest enter under my roof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 7, E'Wherefore neither thought I myself worthy to come unto thee: but say in a word, and my servant shall be healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 8, E'For I also am a man set under authority, having under me soldiers, and I say unto one, Go, and he goeth; and to another, Come, and he cometh; and to my servant, Do this, and he doeth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 9, E'When Jesus heard these things, he marvelled at him, and turned him about, and said unto the people that followed him, I say unto you, I have not found so great faith, no, not in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 10, E'And they that were sent, returning to the house, found the servant whole that had been sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 11, E'And it came to pass the day after, that he went into a city called Nain; and many of his disciples went with him, and much people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 12, E'Now when he came nigh to the gate of the city, behold, there was a dead man carried out, the only son of his mother, and she was a widow: and much people of the city was with her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 13, E'And when the Lord saw her, he had compassion on her, and said unto her, Weep not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 14, E'And he came and touched the bier: and they that bare him stood still. And he said, Young man, I say unto thee, Arise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 15, E'And he that was dead sat up, and began to speak. And he delivered him to his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 16, E'And there came a fear on all: and they glorified God, saying, That a great prophet is risen up among us; and, That God hath visited his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 17, E'And this rumour of him went forth throughout all Judaea, and throughout all the region round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 18, E'And the disciples of John shewed him of all these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 19, E'And John calling unto him two of his disciples sent them to Jesus, saying, Art thou he that should come? or look we for another?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 20, E'When the men were come unto him, they said, John Baptist hath sent us unto thee, saying, Art thou he that should come? or look we for another?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 21, E'And in that same hour he cured many of their infirmities and plagues, and of evil spirits; and unto many that were blind he gave sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 22, E'Then Jesus answering said unto them, Go your way, and tell John what things ye have seen and heard; how that the blind see, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised, to the poor the gospel is preached.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 23, E'And blessed is he, whosoever shall not be offended in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 24, E'And when the messengers of John were departed, he began to speak unto the people concerning John, What went ye out into the wilderness for to see? A reed shaken with the wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 25, E'But what went ye out for to see? A man clothed in soft raiment? Behold, they which are gorgeously apparelled, and live delicately, are in kingsâ€™ courts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 26, E'But what went ye out for to see? A prophet? Yea, I say unto you, and much more than a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 27, E'This is he, of whom it is written, Behold, I send my messenger before thy face, which shall prepare thy way before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 28, E'For I say unto you, Among those that are born of women there is not a greater prophet than John the Baptist: but he that is least in the kingdom of God is greater than he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 29, E'And all the people that heard him, and the publicans, justified God, being baptized with the baptism of John.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 30, E'But the Pharisees and lawyers rejected the counsel of God against themselves, being not baptized of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 31, E'And the Lord said, Whereunto then shall I liken the men of this generation? and to what are they like?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 32, E'They are like unto children sitting in the marketplace, and calling one to another, and saying, We have piped unto you, and ye have not danced; we have mourned to you, and ye have not wept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 33, E'For John the Baptist came neither eating bread nor drinking wine; and ye say, He hath a devil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 34, E'The Son of man is come eating and drinking; and ye say, Behold a gluttonous man, and a winebibber, a friend of publicans and sinners!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 35, E'But wisdom is justified of all her children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 36, E'And one of the Pharisees desired him that he would eat with him. And he went into the Phariseeâ€™s house, and sat down to meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 37, E'And, behold, a woman in the city, which was a sinner, when she knew that Jesus sat at meat in the Phariseeâ€™s house, brought an alabaster box of ointment,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 38, E'And stood at his feet behind him weeping, and began to wash his feet with tears, and did wipe them with the hairs of her head, and kissed his feet, and anointed them with the ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 39, E'Now when the Pharisee which had bidden him saw it, he spake within himself, saying, This man, if he were a prophet, would have known who and what manner of woman this is that toucheth him: for she is a sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 40, E'And Jesus answering said unto him, Simon, I have somewhat to say unto thee. And he saith, Master, say on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 41, E'There was a certain creditor which had two debtors: the one owed five hundred pence, and the other fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 42, E'And when they had nothing to pay, he frankly forgave them both. Tell me therefore, which of them will love him most?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 43, E'Simon answered and said, I suppose that he, to whom he forgave most. And he said unto him, Thou hast rightly judged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 44, E'And he turned to the woman, and said unto Simon, Seest thou this woman? I entered into thine house, thou gavest me no water for my feet: but she hath washed my feet with tears, and wiped them with the hairs of her head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 45, E'Thou gavest me no kiss: but this woman since the time I came in hath not ceased to kiss my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 46, E'My head with oil thou didst not anoint: but this woman hath anointed my feet with ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 47, E'Wherefore I say unto thee, Her sins, which are many, are forgiven; for she loved much: but to whom little is forgiven, the same loveth little.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 48, E'And he said unto her, Thy sins are forgiven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 49, E'And they that sat at meat with him began to say within themselves, Who is this that forgiveth sins also?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 7, 50, E'And he said to the woman, Thy faith hath saved thee; go in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 1, E'And it came to pass afterward, that he went throughout every city and village, preaching and shewing the glad tidings of the kingdom of God: and the twelve were with him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 2, E'And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 3, E'And Joanna the wife of Chuza Herodâ€™s steward, and Susanna, and many others, which ministered unto him of their substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 4, E'And when much people were gathered together, and were come to him out of every city, he spake by a parable:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 5, E'A sower went out to sow his seed: and as he sowed, some fell by the way side; and it was trodden down, and the fowls of the air devoured it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 6, E'And some fell upon a rock; and as soon as it was sprung up, it withered away, because it lacked moisture.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 7, E'And some fell among thorns; and the thorns sprang up with it, and choked it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 8, E'And other fell on good ground, and sprang up, and bare fruit an hundredfold. And when he had said these things, he cried, He that hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 9, E'And his disciples asked him, saying, What might this parable be?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 10, E'And he said, Unto you it is given to know the mysteries of the kingdom of God: but to others in parables; that seeing they might not see, and hearing they might not understand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 11, E'Now the parable is this: The seed is the word of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 12, E'Those by the way side are they that hear; then cometh the devil, and taketh away the word out of their hearts, lest they should believe and be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 13, E'They on the rock are they, which, when they hear, receive the word with joy; and these have no root, which for a while believe, and in time of temptation fall away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 14, E'And that which fell among thorns are they, which, when they have heard, go forth, and are choked with cares and riches and pleasures of this life, and bring no fruit to perfection.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 15, E'But that on the good ground are they, which in an honest and good heart, having heard the word, keep it, and bring forth fruit with patience.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 16, E'No man, when he hath lighted a candle, covereth it with a vessel, or putteth it under a bed; but setteth it on a candlestick, that they which enter in may see the light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 17, E'For nothing is secret, that shall not be made manifest; neither any thing hid, that shall not be known and come abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 18, E'Take heed therefore how ye hear: for whosoever hath, to him shall be given; and whosoever hath not, from him shall be taken even that which he seemeth to have.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 19, E'Then came to him his mother and his brethren, and could not come at him for the press.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 20, E'And it was told him by certain which said, Thy mother and thy brethren stand without, desiring to see thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 21, E'And he answered and said unto them, My mother and my brethren are these which hear the word of God, and do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 22, E'Now it came to pass on a certain day, that he went into a ship with his disciples: and he said unto them, Let us go over unto the other side of the lake. And they launched forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 23, E'But as they sailed he fell asleep: and there came down a storm of wind on the lake; and they were filled with water, and were in jeopardy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 24, E'And they came to him, and awoke him, saying, Master, master, we perish. Then he arose, and rebuked the wind and the raging of the water: and they ceased, and there was a calm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 25, E'And he said unto them, Where is your faith? And they being afraid wondered, saying one to another, What manner of man is this! for he commandeth even the winds and water, and they obey him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 26, E'And they arrived at the country of the Gadarenes, which is over against Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 27, E'And when he went forth to land, there met him out of the city a certain man, which had devils long time, and ware no clothes, neither abode in any house, but in the tombs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 28, E'When he saw Jesus, he cried out, and fell down before him, and with a loud voice said, What have I to do with thee, Jesus, thou Son of God most high? I beseech thee, torment me not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 29, E'(For he had commanded the unclean spirit to come out of the man. For oftentimes it had caught him: and he was kept bound with chains and in fetters; and he brake the bands, and was driven of the devil into the wilderness.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 30, E'And Jesus asked him, saying, What is thy name? And he said, Legion: because many devils were entered into him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 31, E'And they besought him that he would not command them to go out into the deep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 32, E'And there was there an herd of many swine feeding on the mountain: and they besought him that he would suffer them to enter into them. And he suffered them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 33, E'Then went the devils out of the man, and entered into the swine: and the herd ran violently down a steep place into the lake, and were choked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 34, E'When they that fed them saw what was done, they fled, and went and told it in the city and in the country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 35, E'Then they went out to see what was done; and came to Jesus, and found the man, out of whom the devils were departed, sitting at the feet of Jesus, clothed, and in his right mind: and they were afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 36, E'They also which saw it told them by what means he that was possessed of the devils was healed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 37, E'Then the whole multitude of the country of the Gadarenes round about besought him to depart from them; for they were taken with great fear: and he went up into the ship, and returned back again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 38, E'Now the man out of whom the devils were departed besought him that he might be with him: but Jesus sent him away, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 39, E'Return to thine own house, and shew how great things God hath done unto thee. And he went his way, and published throughout the whole city how great things Jesus had done unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 40, E'And it came to pass, that, when Jesus was returned, the people gladly received him: for they were all waiting for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 41, E'And, behold, there came a man named Jairus, and he was a ruler of the synagogue: and he fell down at Jesusâ€™ feet, and besought him that he would come into his house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 42, E'For he had one only daughter, about twelve years of age, and she lay a dying. But as he went the people thronged him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 43, E'And a woman having an issue of blood twelve years, which had spent all her living upon physicians, neither could be healed of any,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 44, E'Came behind him, and touched the border of his garment: and immediately her issue of blood stanched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 45, E'And Jesus said, Who touched me? When all denied, Peter and they that were with him said, Master, the multitude throng thee and press thee, and sayest thou, Who touched me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 46, E'And Jesus said, Somebody hath touched me: for I perceive that virtue is gone out of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 47, E'And when the woman saw that she was not hid, she came trembling, and falling down before him, she declared unto him before all the people for what cause she had touched him, and how she was healed immediately.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 48, E'And he said unto her, Daughter, be of good comfort: thy faith hath made thee whole; go in peace.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 49, E'While he yet spake, there cometh one from the ruler of the synagogueâ€™s house, saying to him, Thy daughter is dead; trouble not the Master.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 50, E'But when Jesus heard it, he answered him, saying, Fear not: believe only, and she shall be made whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 51, E'And when he came into the house, he suffered no man to go in, save Peter, and James, and John, and the father and the mother of the maiden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 52, E'And all wept, and bewailed her: but he said, Weep not; she is not dead, but sleepeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 53, E'And they laughed him to scorn, knowing that she was dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 54, E'And he put them all out, and took her by the hand, and called, saying, Maid, arise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 55, E'And her spirit came again, and she arose straightway: and he commanded to give her meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 8, 56, E'And her parents were astonished: but he charged them that they should tell no man what was done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 1, E'Then he called his twelve disciples together, and gave them power and authority over all devils, and to cure diseases.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 2, E'And he sent them to preach the kingdom of God, and to heal the sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 3, E'And he said unto them, Take nothing for your journey, neither staves, nor scrip, neither bread, neither money; neither have two coats apiece.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 4, E'And whatsoever house ye enter into, there abide, and thence depart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 5, E'And whosoever will not receive you, when ye go out of that city, shake off the very dust from your feet for a testimony against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 6, E'And they departed, and went through the towns, preaching the gospel, and healing every where.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 7, E'Now Herod the tetrarch heard of all that was done by him: and he was perplexed, because that it was said of some, that John was risen from the dead;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 8, E'And of some, that Elias had appeared; and of others, that one of the old prophets was risen again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 9, E'And Herod said, John have I beheaded: but who is this, of whom I hear such things? And he desired to see him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 10, E'And the apostles, when they were returned, told him all that they had done. And he took them, and went aside privately into a desert place belonging to the city called Bethsaida.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 11, E'And the people, when they knew it, followed him: and he received them, and spake unto them of the kingdom of God, and healed them that had need of healing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 12, E'And when the day began to wear away, then came the twelve, and said unto him, Send the multitude away, that they may go into the towns and country round about, and lodge, and get victuals: for we are here in a desert place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 13, E'But he said unto them, Give ye them to eat. And they said, We have no more but five loaves and two fishes; except we should go and buy meat for all this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 14, E'For they were about five thousand men. And he said to his disciples, Make them sit down by fifties in a company.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 15, E'And they did so, and made them all sit down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 16, E'Then he took the five loaves and the two fishes, and looking up to heaven, he blessed them, and brake, and gave to the disciples to set before the multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 17, E'And they did eat, and were all filled: and there was taken up of fragments that remained to them twelve baskets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 18, E'And it came to pass, as he was alone praying, his disciples were with him: and he asked them, saying, Whom say the people that I am?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 19, E'They answering said, John the Baptist; but some say, Elias; and others say, that one of the old prophets is risen again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 20, E'He said unto them, But whom say ye that I am? Peter answering said, The Christ of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 21, E'And he straitly charged them, and commanded them to tell no man that thing;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 22, E'Saying, The Son of man must suffer many things, and be rejected of the elders and chief priests and scribes, and be slain, and be raised the third day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 23, E'And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 24, E'For whosoever will save his life shall lose it: but whosoever will lose his life for my sake, the same shall save it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 25, E'For what is a man advantaged, if he gain the whole world, and lose himself, or be cast away?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 26, E'For whosoever shall be ashamed of me and of my words, of him shall the Son of man be ashamed, when he shall come in his own glory, and in his Fatherâ€™s, and of the holy angels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 27, E'But I tell you of a truth, there be some standing here, which shall not taste of death, till they see the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 28, E'And it came to pass about an eight days after these sayings, he took Peter and John and James, and went up into a mountain to pray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 29, E'And as he prayed, the fashion of his countenance was altered, and his raiment was white and glistering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 30, E'And, behold, there talked with him two men, which were Moses and Elias:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 31, E'Who appeared in glory, and spake of his decease which he should accomplish at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 32, E'But Peter and they that were with him were heavy with sleep: and when they were awake, they saw his glory, and the two men that stood with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 33, E'And it came to pass, as they departed from him, Peter said unto Jesus, Master, it is good for us to be here: and let us make three tabernacles; one for thee, and one for Moses, and one for Elias: not knowing what he said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 34, E'While he thus spake, there came a cloud, and overshadowed them: and they feared as they entered into the cloud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 35, E'And there came a voice out of the cloud, saying, This is my beloved Son: hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 36, E'And when the voice was past, Jesus was found alone. And they kept it close, and told no man in those days any of those things which they had seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 37, E'And it came to pass, that on the next day, when they were come down from the hill, much people met him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 38, E'And, behold, a man of the company cried out, saying, Master, I beseech thee, look upon my son: for he is mine only child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 39, E'And, lo, a spirit taketh him, and he suddenly crieth out; and it teareth him that he foameth again, and bruising him hardly departeth from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 40, E'And I besought thy disciples to cast him out; and they could not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 41, E'And Jesus answering said, O faithless and perverse generation, how long shall I be with you, and suffer you? Bring thy son hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 42, E'And as he was yet a coming, the devil threw him down, and tare him. And Jesus rebuked the unclean spirit, and healed the child, and delivered him again to his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 43, E'And they were all amazed at the mighty power of God. But while they wondered every one at all things which Jesus did, he said unto his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 44, E'Let these sayings sink down into your ears: for the Son of man shall be delivered into the hands of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 45, E'But they understood not this saying, and it was hid from them, that they perceived it not: and they feared to ask him of that saying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 46, E'Then there arose a reasoning among them, which of them should be greatest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 47, E'And Jesus, perceiving the thought of their heart, took a child, and set him by him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 48, E'And said unto them, Whosoever shall receive this child in my name receiveth me: and whosoever shall receive me receiveth him that sent me: for he that is least among you all, the same shall be great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 49, E'And John answered and said, Master, we saw one casting out devils in thy name; and we forbad him, because he followeth not with us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 50, E'And Jesus said unto him, Forbid him not: for he that is not against us is for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 51, E'And it came to pass, when the time was come that he should be received up, he stedfastly set his face to go to Jerusalem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 52, E'And sent messengers before his face: and they went, and entered into a village of the Samaritans, to make ready for him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 53, E'And they did not receive him, because his face was as though he would go to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 54, E'And when his disciples James and John saw this, they said, Lord, wilt thou that we command fire to come down from heaven, and consume them, even as Elias did?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 55, E'But he turned, and rebuked them, and said, Ye know not what manner of spirit ye are of.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 56, E'For the Son of man is not come to destroy menâ€™s lives, but to save them. And they went to another village.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 57, E'And it came to pass, that, as they went in the way, a certain man said unto him, Lord, I will follow thee whithersoever thou goest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 58, E'And Jesus said unto him, Foxes have holes, and birds of the air have nests; but the Son of man hath not where to lay his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 59, E'And he said unto another, Follow me. But he said, Lord, suffer me first to go and bury my father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 60, E'Jesus said unto him, Let the dead bury their dead: but go thou and preach the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 61, E'And another also said, Lord, I will follow thee; but let me first go bid them farewell, which are at home at my house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 9, 62, E'And Jesus said unto him, No man, having put his hand to the plough, and looking back, is fit for the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 1, E'After these things the LORD appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 2, E'Therefore said he unto them, The harvest truly is great, but the labourers are few: pray ye therefore the Lord of the harvest, that he would send forth labourers into his harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 3, E'Go your ways: behold, I send you forth as lambs among wolves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 4, E'Carry neither purse, nor scrip, nor shoes: and salute no man by the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 5, E'And into whatsoever house ye enter, first say, Peace be to this house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 6, E'And if the son of peace be there, your peace shall rest upon it: if not, it shall turn to you again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 7, E'And in the same house remain, eating and drinking such things as they give: for the labourer is worthy of his hire. Go not from house to house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 8, E'And into whatsoever city ye enter, and they receive you, eat such things as are set before you:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 9, E'And heal the sick that are therein, and say unto them, The kingdom of God is come nigh unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 10, E'But into whatsoever city ye enter, and they receive you not, go your ways out into the streets of the same, and say,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 11, E'Even the very dust of your city, which cleaveth on us, we do wipe off against you: notwithstanding be ye sure of this, that the kingdom of God is come nigh unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 12, E'But I say unto you, that it shall be more tolerable in that day for Sodom, than for that city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 13, E'Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works had been done in Tyre and Sidon, which have been done in you, they had a great while ago repented, sitting in sackcloth and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 14, E'But it shall be more tolerable for Tyre and Sidon at the judgment, than for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 15, E'And thou, Capernaum, which art exalted to heaven, shalt be thrust down to hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 16, E'He that heareth you heareth me; and he that despiseth you despiseth me; and he that despiseth me despiseth him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 17, E'And the seventy returned again with joy, saying, Lord, even the devils are subject unto us through thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 18, E'And he said unto them, I beheld Satan as lightning fall from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 19, E'Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 20, E'Notwithstanding in this rejoice not, that the spirits are subject unto you; but rather rejoice, because your names are written in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 21, E'In that hour Jesus rejoiced in spirit, and said, I thank thee, O Father, Lord of heaven and earth, that thou hast hid these things from the wise and prudent, and hast revealed them unto babes: even so, Father; for so it seemed good in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 22, E'All things are delivered to me of my Father: and no man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 23, E'And he turned him unto his disciples, and said privately, Blessed are the eyes which see the things that ye see:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 24, E'For I tell you, that many prophets and kings have desired to see those things which ye see, and have not seen them; and to hear those things which ye hear, and have not heard them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 25, E'And, behold, a certain lawyer stood up, and tempted him, saying, Master, what shall I do to inherit eternal life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 26, E'He said unto him, What is written in the law? how readest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 27, E'And he answering said, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy strength, and with all thy mind; and thy neighbour as thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 28, E'And he said unto him, Thou hast answered right: this do, and thou shalt live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 29, E'But he, willing to justify himself, said unto Jesus, And who is my neighbour?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 30, E'And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 31, E'And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 32, E'And likewise a Levite, when he was at the place, came and looked on him, and passed by on the other side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 33, E'But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion on him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 34, E'And went to him, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 35, E'And on the morrow when he departed, he took out two pence, and gave them to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 36, E'Which now of these three, thinkest thou, was neighbour unto him that fell among the thieves?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 37, E'And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 38, E'Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 39, E'And she had a sister called Mary, which also sat at Jesusâ€™ feet, and heard his word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 40, E'But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 41, E'And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 10, 42, E'But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 1, E'And it came to pass, that, as he was praying in a certain place, when he ceased, one of his disciples said unto him, Lord, teach us to pray, as John also taught his disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 2, E'And he said unto them, When ye pray, say, Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done, as in heaven, so in earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 3, E'Give us day by day our daily bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 4, E'And forgive us our sins; for we also forgive every one that is indebted to us. And lead us not into temptation; but deliver us from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 5, E'And he said unto them, Which of you shall have a friend, and shall go unto him at midnight, and say unto him, Friend, lend me three loaves;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 6, E'For a friend of mine in his journey is come to me, and I have nothing to set before him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 7, E'And he from within shall answer and say, Trouble me not: the door is now shut, and my children are with me in bed; I cannot rise and give thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 8, E'I say unto you, Though he will not rise and give him, because he is his friend, yet because of his importunity he will rise and give him as many as he needeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 9, E'And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 10, E'For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 11, E'If a son shall ask bread of any of you that is a father, will he give him a stone? or if he ask a fish, will he for a fish give him a serpent?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 12, E'Or if he shall ask an egg, will he offer him a scorpion?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 13, E'If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 14, E'And he was casting out a devil, and it was dumb. And it came to pass, when the devil was gone out, the dumb spake; and the people wondered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 15, E'But some of them said, He casteth out devils through Beelzebub the chief of the devils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 16, E'And others, tempting him, sought of him a sign from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 17, E'But he, knowing their thoughts, said unto them, Every kingdom divided against itself is brought to desolation; and a house divided against a house falleth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 18, E'If Satan also be divided against himself, how shall his kingdom stand? because ye say that I cast out devils through Beelzebub.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 19, E'And if I by Beelzebub cast out devils, by whom do your sons cast them out? therefore shall they be your judges.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 20, E'But if I with the finger of God cast out devils, no doubt the kingdom of God is come upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 21, E'When a strong man armed keepeth his palace, his goods are in peace:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 22, E'But when a stronger than he shall come upon him, and overcome him, he taketh from him all his armour wherein he trusted, and divideth his spoils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 23, E'He that is not with me is against me: and he that gathereth not with me scattereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 24, E'When the unclean spirit is gone out of a man, he walketh through dry places, seeking rest; and finding none, he saith, I will return unto my house whence I came out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 25, E'And when he cometh, he findeth it swept and garnished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 26, E'Then goeth he, and taketh to him seven other spirits more wicked than himself; and they enter in, and dwell there: and the last state of that man is worse than the first.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 27, E'And it came to pass, as he spake these things, a certain woman of the company lifted up her voice, and said unto him, Blessed is the womb that bare thee, and the paps which thou hast sucked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 28, E'But he said, Yea rather, blessed are they that hear the word of God, and keep it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 29, E'And when the people were gathered thick together, he began to say, This is an evil generation: they seek a sign; and there shall no sign be given it, but the sign of Jonas the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 30, E'For as Jonas was a sign unto the Ninevites, so shall also the Son of man be to this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 31, E'The queen of the south shall rise up in the judgment with the men of this generation, and condemn them: for she came from the utmost parts of the earth to hear the wisdom of Solomon; and, behold, a greater than Solomon is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 32, E'The men of Nineve shall rise up in the judgment with this generation, and shall condemn it: for they repented at the preaching of Jonas; and, behold, a greater than Jonas is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 33, E'No man, when he hath lighted a candle, putteth it in a secret place, neither under a bushel, but on a candlestick, that they which come in may see the light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 34, E'The light of the body is the eye: therefore when thine eye is single, thy whole body also is full of light; but when thine eye is evil, thy body also is full of darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 35, E'Take heed therefore that the light which is in thee be not darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 36, E'If thy whole body therefore be full of light, having no part dark, the whole shall be full of light, as when the bright shining of a candle doth give thee light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 37, E'And as he spake, a certain Pharisee besought him to dine with him: and he went in, and sat down to meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 38, E'And when the Pharisee saw it, he marvelled that he had not first washed before dinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 39, E'And the Lord said unto him, Now do ye Pharisees make clean the outside of the cup and the platter; but your inward part is full of ravening and wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 40, E'Ye fools, did not he that made that which is without make that which is within also?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 41, E'But rather give alms of such things as ye have; and, behold, all things are clean unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 42, E'But woe unto you, Pharisees! for ye tithe mint and rue and all manner of herbs, and pass over judgment and the love of God: these ought ye to have done, and not to leave the other undone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 43, E'Woe unto you, Pharisees! for ye love the uppermost seats in the synagogues, and greetings in the markets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 44, E'Woe unto you, scribes and Pharisees, hypocrites! for ye are as graves which appear not, and the men that walk over them are not aware of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 45, E'Then answered one of the lawyers, and said unto him, Master, thus saying thou reproachest us also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 46, E'And he said, Woe unto you also, ye lawyers! for ye lade men with burdens grievous to be borne, and ye yourselves touch not the burdens with one of your fingers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 47, E'Woe unto you! for ye build the sepulchres of the prophets, and your fathers killed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 48, E'Truly ye bear witness that ye allow the deeds of your fathers: for they indeed killed them, and ye build their sepulchres.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 49, E'Therefore also said the wisdom of God, I will send them prophets and apostles, and some of them they shall slay and persecute:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 50, E'That the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 51, E'From the blood of Abel unto the blood of Zacharias, which perished between the altar and the temple: verily I say unto you, It shall be required of this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 52, E'Woe unto you, lawyers! for ye have taken away the key of knowledge: ye entered not in yourselves, and them that were entering in ye hindered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 53, E'And as he said these things unto them, the scribes and the Pharisees began to urge him vehemently, and to provoke him to speak of many things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 11, 54, E'Laying wait for him, and seeking to catch something out of his mouth, that they might accuse him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 1, E'In the mean time, when there were gathered together an innumerable multitude of people, insomuch that they trode one upon another, he began to say unto his disciples first of all, Beware ye of the leaven of the Pharisees, which is hypocrisy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 2, E'For there is nothing covered, that shall not be revealed; neither hid, that shall not be known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 3, E'Therefore whatsoever ye have spoken in darkness shall be heard in the light; and that which ye have spoken in the ear in closets shall be proclaimed upon the housetops.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 4, E'And I say unto you my friends, Be not afraid of them that kill the body, and after that have no more that they can do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 5, E'But I will forewarn you whom ye shall fear: Fear him, which after he hath killed hath power to cast into hell; yea, I say unto you, Fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 6, E'Are not five sparrows sold for two farthings, and not one of them is forgotten before God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 7, E'But even the very hairs of your head are all numbered. Fear not therefore: ye are of more value than many sparrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 8, E'Also I say unto you, Whosoever shall confess me before men, him shall the Son of man also confess before the angels of God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 9, E'But he that denieth me before men shall be denied before the angels of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 10, E'And whosoever shall speak a word against the Son of man, it shall be forgiven him: but unto him that blasphemeth against the Holy Ghost it shall not be forgiven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 11, E'And when they bring you unto the synagogues, and unto magistrates, and powers, take ye no thought how or what thing ye shall answer, or what ye shall say:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 12, E'For the Holy Ghost shall teach you in the same hour what ye ought to say.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 13, E'And one of the company said unto him, Master, speak to my brother, that he divide the inheritance with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 14, E'And he said unto him, Man, who made me a judge or a divider over you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 15, E'And he said unto them, Take heed, and beware of covetousness: for a manâ€™s life consisteth not in the abundance of the things which he possesseth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 16, E'And he spake a parable unto them, saying, The ground of a certain rich man brought forth plentifully:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 17, E'And he thought within himself, saying, What shall I do, because I have no room where to bestow my fruits?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 18, E'And he said, This will I do: I will pull down my barns, and build greater; and there will I bestow all my fruits and my goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 19, E'And I will say to my soul, Soul, thou hast much goods laid up for many years; take thine ease, eat, drink, and be merry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 20, E'But God said unto him, Thou fool, this night thy soul shall be required of thee: then whose shall those things be, which thou hast provided?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 21, E'So is he that layeth up treasure for himself, and is not rich toward God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 22, E'And he said unto his disciples, Therefore I say unto you, Take no thought for your life, what ye shall eat; neither for the body, what ye shall put on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 23, E'The life is more than meat, and the body is more than raiment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 24, E'Consider the ravens: for they neither sow nor reap; which neither have storehouse nor barn; and God feedeth them: how much more are ye better than the fowls?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 25, E'And which of you with taking thought can add to his stature one cubit?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 26, E'If ye then be not able to do that thing which is least, why take ye thought for the rest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 27, E'Consider the lilies how they grow: they toil not, they spin not; and yet I say unto you, that Solomon in all his glory was not arrayed like one of these.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 28, E'If then God so clothe the grass, which is to day in the field, and to morrow is cast into the oven; how much more will he clothe you, O ye of little faith?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 29, E'And seek not ye what ye shall eat, or what ye shall drink, neither be ye of doubtful mind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 30, E'For all these things do the nations of the world seek after: and your Father knoweth that ye have need of these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 31, E'But rather seek ye the kingdom of God; and all these things shall be added unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 32, E'Fear not, little flock; for it is your Fatherâ€™s good pleasure to give you the kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 33, E'Sell that ye have, and give alms; provide yourselves bags which wax not old, a treasure in the heavens that faileth not, where no thief approacheth, neither moth corrupteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 34, E'For where your treasure is, there will your heart be also.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 35, E'Let your loins be girded about, and your lights burning;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 36, E'And ye yourselves like unto men that wait for their lord, when he will return from the wedding; that when he cometh and knocketh, they may open unto him immediately.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 37, E'Blessed are those servants, whom the lord when he cometh shall find watching: verily I say unto you, that he shall gird himself, and make them to sit down to meat, and will come forth and serve them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 38, E'And if he shall come in the second watch, or come in the third watch, and find them so, blessed are those servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 39, E'And this know, that if the goodman of the house had known what hour the thief would come, he would have watched, and not have suffered his house to be broken through.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 40, E'Be ye therefore ready also: for the Son of man cometh at an hour when ye think not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 41, E'Then Peter said unto him, Lord, speakest thou this parable unto us, or even to all?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 42, E'And the Lord said, Who then is that faithful and wise steward, whom his lord shall make ruler over his household, to give them their portion of meat in due season?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 43, E'Blessed is that servant, whom his lord when he cometh shall find so doing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 44, E'Of a truth I say unto you, that he will make him ruler over all that he hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 45, E'But and if that servant say in his heart, My lord delayeth his coming; and shall begin to beat the menservants and maidens, and to eat and drink, and to be drunken;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 46, E'The lord of that servant will come in a day when he looketh not for him, and at an hour when he is not aware, and will cut him in sunder, and will appoint him his portion with the unbelievers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 47, E'And that servant, which knew his lordâ€™s will, and prepared not himself, neither did according to his will, shall be beaten with many stripes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 48, E'But he that knew not, and did commit things worthy of stripes, shall be beaten with few stripes. For unto whomsoever much is given, of him shall be much required: and to whom men have committed much, of him they will ask the more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 49, E'I am come to send fire on the earth; and what will I, if it be already kindled?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 50, E'But I have a baptism to be baptized with; and how am I straitened till it be accomplished!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 51, E'Suppose ye that I am come to give peace on earth? I tell you, Nay; but rather division:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 52, E'For from henceforth there shall be five in one house divided, three against two, and two against three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 53, E'The father shall be divided against the son, and the son against the father; the mother against the daughter, and the daughter against the mother; the mother in law against her daughter in law, and the daughter in law against her mother in law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 54, E'And he said also to the people, When ye see a cloud rise out of the west, straightway ye say, There cometh a shower; and so it is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 55, E'And when ye see the south wind blow, ye say, There will be heat; and it cometh to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 56, E'Ye hypocrites, ye can discern the face of the sky and of the earth; but how is it that ye do not discern this time?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 57, E'Yea, and why even of yourselves judge ye not what is right?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 58, E'When thou goest with thine adversary to the magistrate, as thou art in the way, give diligence that thou mayest be delivered from him; lest he hale thee to the judge, and the judge deliver thee to the officer, and the officer cast thee into prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 12, 59, E'I tell thee, thou shalt not depart thence, till thou hast paid the very last mite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 1, E'There were present at that season some that told him of the Galilaeans, whose blood Pilate had mingled with their sacrifices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 2, E'And Jesus answering said unto them, Suppose ye that these Galilaeans were sinners above all the Galilaeans, because they suffered such things?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 3, E'I tell you, Nay: but, except ye repent, ye shall all likewise perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 4, E'Or those eighteen, upon whom the tower in Siloam fell, and slew them, think ye that they were sinners above all men that dwelt in Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 5, E'I tell you, Nay: but, except ye repent, ye shall all likewise perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 6, E'He spake also this parable; A certain man had a fig tree planted in his vineyard; and he came and sought fruit thereon, and found none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 7, E'Then said he unto the dresser of his vineyard, Behold, these three years I come seeking fruit on this fig tree, and find none: cut it down; why cumbereth it the ground?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 8, E'And he answering said unto him, Lord, let it alone this year also, till I shall dig about it, and dung it:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 9, E'And if it bear fruit, well: and if not, then after that thou shalt cut it down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 10, E'And he was teaching in one of the synagogues on the sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 11, E'And, behold, there was a woman which had a spirit of infirmity eighteen years, and was bowed together, and could in no wise lift up herself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 12, E'And when Jesus saw her, he called her to him, and said unto her, Woman, thou art loosed from thine infirmity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 13, E'And he laid his hands on her: and immediately she was made straight, and glorified God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 14, E'And the ruler of the synagogue answered with indignation, because that Jesus had healed on the sabbath day, and said unto the people, There are six days in which men ought to work: in them therefore come and be healed, and not on the sabbath day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 15, E'The Lord then answered him, and said, Thou hypocrite, doth not each one of you on the sabbath loose his ox or his ass from the stall, and lead him away to watering?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 16, E'And ought not this woman, being a daughter of Abraham, whom Satan hath bound, lo, these eighteen years, be loosed from this bond on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 17, E'And when he had said these things, all his adversaries were ashamed: and all the people rejoiced for all the glorious things that were done by him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 18, E'Then said he, Unto what is the kingdom of God like? and whereunto shall I resemble it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 19, E'It is like a grain of mustard seed, which a man took, and cast into his garden; and it grew, and waxed a great tree; and the fowls of the air lodged in the branches of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 20, E'And again he said, Whereunto shall I liken the kingdom of God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 21, E'It is like leaven, which a woman took and hid in three measures of meal, till the whole was leavened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 22, E'And he went through the cities and villages, teaching, and journeying toward Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 23, E'Then said one unto him, Lord, are there few that be saved? And he said unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 24, E'Strive to enter in at the strait gate: for many, I say unto you, will seek to enter in, and shall not be able.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 25, E'When once the master of the house is risen up, and hath shut to the door, and ye begin to stand without, and to knock at the door, saying, Lord, Lord, open unto us; and he shall answer and say unto you, I know you not whence ye are:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 26, E'Then shall ye begin to say, We have eaten and drunk in thy presence, and thou hast taught in our streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 27, E'But he shall say, I tell you, I know you not whence ye are; depart from me, all ye workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 28, E'There shall be weeping and gnashing of teeth, when ye shall see Abraham, and Isaac, and Jacob, and all the prophets, in the kingdom of God, and you yourselves thrust out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 29, E'And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 30, E'And, behold, there are last which shall be first, and there are first which shall be last.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 31, E'The same day there came certain of the Pharisees, saying unto him, Get thee out, and depart hence: for Herod will kill thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 32, E'And he said unto them, Go ye, and tell that fox, Behold, I cast out devils, and I do cures to day and to morrow, and the third day I shall be perfected.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 33, E'Nevertheless I must walk to day, and to morrow, and the day following: for it cannot be that a prophet perish out of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 34, E'O Jerusalem, Jerusalem, which killest the prophets, and stonest them that are sent unto thee; how often would I have gathered thy children together, as a hen doth gather her brood under her wings, and ye would not!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 13, 35, E'Behold, your house is left unto you desolate: and verily I say unto you, Ye shall not see me, until the time come when ye shall say, Blessed is he that cometh in the name of the Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 1, E'And it came to pass, as he went into the house of one of the chief Pharisees to eat bread on the sabbath day, that they watched him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 2, E'And, behold, there was a certain man before him which had the dropsy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 3, E'And Jesus answering spake unto the lawyers and Pharisees, saying, Is it lawful to heal on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 4, E'And they held their peace. And he took him, and healed him, and let him go;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 5, E'And answered them, saying, Which of you shall have an ass or an ox fallen into a pit, and will not straightway pull him out on the sabbath day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 6, E'And they could not answer him again to these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 7, E'And he put forth a parable to those which were bidden, when he marked how they chose out the chief rooms; saying unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 8, E'When thou art bidden of any man to a wedding, sit not down in the highest room; lest a more honourable man than thou be bidden of him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 9, E'And he that bade thee and him come and say to thee, Give this man place; and thou begin with shame to take the lowest room.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 10, E'But when thou art bidden, go and sit down in the lowest room; that when he that bade thee cometh, he may say unto thee, Friend, go up higher: then shalt thou have worship in the presence of them that sit at meat with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 11, E'For whosoever exalteth himself shall be abased; and he that humbleth himself shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 12, E'Then said he also to him that bade him, When thou makest a dinner or a supper, call not thy friends, nor thy brethren, neither thy kinsmen, nor thy rich neighbours; lest they also bid thee again, and a recompence be made thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 13, E'But when thou makest a feast, call the poor, the maimed, the lame, the blind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 14, E'And thou shalt be blessed; for they cannot recompense thee: for thou shalt be recompensed at the resurrection of the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 15, E'And when one of them that sat at meat with him heard these things, he said unto him, Blessed is he that shall eat bread in the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 16, E'Then said he unto him, A certain man made a great supper, and bade many:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 17, E'And sent his servant at supper time to say to them that were bidden, Come; for all things are now ready.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 18, E'And they all with one consent began to make excuse. The first said unto him, I have bought a piece of ground, and I must needs go and see it: I pray thee have me excused.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 19, E'And another said, I have bought five yoke of oxen, and I go to prove them: I pray thee have me excused.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 20, E'And another said, I have married a wife, and therefore I cannot come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 21, E'So that servant came, and shewed his lord these things. Then the master of the house being angry said to his servant, Go out quickly into the streets and lanes of the city, and bring in hither the poor, and the maimed, and the halt, and the blind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 22, E'And the servant said, Lord, it is done as thou hast commanded, and yet there is room.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 23, E'And the lord said unto the servant, Go out into the highways and hedges, and compel them to come in, that my house may be filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 24, E'For I say unto you, That none of those men which were bidden shall taste of my supper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 25, E'And there went great multitudes with him: and he turned, and said unto them,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 26, E'If any man come to me, and hate not his father, and mother, and wife, and children, and brethren, and sisters, yea, and his own life also, he cannot be my disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 27, E'And whosoever doth not bear his cross, and come after me, cannot be my disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 28, E'For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 29, E'Lest haply, after he hath laid the foundation, and is not able to finish it, all that behold it begin to mock him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 30, E'Saying, This man began to build, and was not able to finish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 31, E'Or what king, going to make war against another king, sitteth not down first, and consulteth whether he be able with ten thousand to meet him that cometh against him with twenty thousand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 32, E'Or else, while the other is yet a great way off, he sendeth an ambassage, and desireth conditions of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 33, E'So likewise, whosoever he be of you that forsaketh not all that he hath, he cannot be my disciple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 34, E'Salt is good: but if the salt have lost his savour, wherewith shall it be seasoned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 14, 35, E'It is neither fit for the land, nor yet for the dunghill; but men cast it out. He that hath ears to hear, let him hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 1, E'Then drew near unto him all the publicans and sinners for to hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 2, E'And the Pharisees and scribes murmured, saying, This man receiveth sinners, and eateth with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 3, E'And he spake this parable unto them, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 4, E'What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 5, E'And when he hath found it, he layeth it on his shoulders, rejoicing.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 6, E'And when he cometh home, he calleth together his friends and neighbours, saying unto them, Rejoice with me; for I have found my sheep which was lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 7, E'I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 8, E'Either what woman having ten pieces of silver, if she lose one piece, doth not light a candle, and sweep the house, and seek diligently till she find it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 9, E'And when she hath found it, she calleth her friends and her neighbours together, saying, Rejoice with me; for I have found the piece which I had lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 10, E'Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 11, E'And he said, A certain man had two sons:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 12, E'And the younger of them said to his father, Father, give me the portion of goods that falleth to me. And he divided unto them his living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 13, E'And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 14, E'And when he had spent all, there arose a mighty famine in that land; and he began to be in want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 15, E'And he went and joined himself to a citizen of that country; and he sent him into his fields to feed swine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 16, E'And he would fain have filled his belly with the husks that the swine did eat: and no man gave unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 17, E'And when he came to himself, he said, How many hired servants of my fatherâ€™s have bread enough and to spare, and I perish with hunger!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 18, E'I will arise and go to my father, and will say unto him, Father, I have sinned against heaven, and before thee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 19, E'And am no more worthy to be called thy son: make me as one of thy hired servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 20, E'And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 21, E'And the son said unto him, Father, I have sinned against heaven, and in thy sight, and am no more worthy to be called thy son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 22, E'But the father said to his servants, Bring forth the best robe, and put it on him; and put a ring on his hand, and shoes on his feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 23, E'And bring hither the fatted calf, and kill it; and let us eat, and be merry:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 24, E'For this my son was dead, and is alive again; he was lost, and is found. And they began to be merry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 25, E'Now his elder son was in the field: and as he came and drew nigh to the house, he heard musick and dancing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 26, E'And he called one of the servants, and asked what these things meant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 27, E'And he said unto him, Thy brother is come; and thy father hath killed the fatted calf, because he hath received him safe and sound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 28, E'And he was angry, and would not go in: therefore came his father out, and intreated him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 29, E'And he answering said to his father, Lo, these many years do I serve thee, neither transgressed I at any time thy commandment: and yet thou never gavest me a kid, that I might make merry with my friends:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 30, E'But as soon as this thy son was come, which hath devoured thy living with harlots, thou hast killed for him the fatted calf.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 31, E'And he said unto him, Son, thou art ever with me, and all that I have is thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 15, 32, E'It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 1, E'And he said also unto his disciples, There was a certain rich man, which had a steward; and the same was accused unto him that he had wasted his goods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 2, E'And he called him, and said unto him, How is it that I hear this of thee? give an account of thy stewardship; for thou mayest be no longer steward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 3, E'Then the steward said within himself, What shall I do? for my lord taketh away from me the stewardship: I cannot dig; to beg I am ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 4, E'I am resolved what to do, that, when I am put out of the stewardship, they may receive me into their houses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 5, E'So he called every one of his lordâ€™s debtors unto him, and said unto the first, How much owest thou unto my lord?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 6, E'And he said, An hundred measures of oil. And he said unto him, Take thy bill, and sit down quickly, and write fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 7, E'Then said he to another, And how much owest thou? And he said, An hundred measures of wheat. And he said unto him, Take thy bill, and write fourscore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 8, E'And the lord commended the unjust steward, because he had done wisely: for the children of this world are in their generation wiser than the children of light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 9, E'And I say unto you, Make to yourselves friends of the mammon of unrighteousness; that, when ye fail, they may receive you into everlasting habitations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 10, E'He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 11, E'If therefore ye have not been faithful in the unrighteous mammon, who will commit to your trust the true riches?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 12, E'And if ye have not been faithful in that which is another manâ€™s, who shall give you that which is your own?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 13, E'No servant can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 14, E'And the Pharisees also, who were covetous, heard all these things: and they derided him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 15, E'And he said unto them, Ye are they which justify yourselves before men; but God knoweth your hearts: for that which is highly esteemed among men is abomination in the sight of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 16, E'The law and the prophets were until John: since that time the kingdom of God is preached, and every man presseth into it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 17, E'And it is easier for heaven and earth to pass, than one tittle of the law to fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 18, E'Whosoever putteth away his wife, and marrieth another, committeth adultery: and whosoever marrieth her that is put away from her husband committeth adultery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 19, E'There was a certain rich man, which was clothed in purple and fine linen, and fared sumptuously every day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 20, E'And there was a certain beggar named Lazarus, which was laid at his gate, full of sores,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 21, E'And desiring to be fed with the crumbs which fell from the rich manâ€™s table: moreover the dogs came and licked his sores.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 22, E'And it came to pass, that the beggar died, and was carried by the angels into Abrahamâ€™s bosom: the rich man also died, and was buried;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 23, E'And in hell he lift up his eyes, being in torments, and seeth Abraham afar off, and Lazarus in his bosom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 24, E'And he cried and said, Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, and cool my tongue; for I am tormented in this flame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 25, E'But Abraham said, Son, remember that thou in thy lifetime receivedst thy good things, and likewise Lazarus evil things: but now he is comforted, and thou art tormented.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 26, E'And beside all this, between us and you there is a great gulf fixed: so that they which would pass from hence to you cannot; neither can they pass to us, that would come from thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 27, E'Then he said, I pray thee therefore, father, that thou wouldest send him to my fatherâ€™s house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 28, E'For I have five brethren; that he may testify unto them, lest they also come into this place of torment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 29, E'Abraham saith unto him, They have Moses and the prophets; let them hear them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 30, E'And he said, Nay, father Abraham: but if one went unto them from the dead, they will repent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 16, 31, E'And he said unto him, If they hear not Moses and the prophets, neither will they be persuaded, though one rose from the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 1, E'Then said he unto the disciples, It is impossible but that offences will come: but woe unto him, through whom they come!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 2, E'It were better for him that a millstone were hanged about his neck, and he cast into the sea, than that he should offend one of these little ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 3, E'Take heed to yourselves: If thy brother trespass against thee, rebuke him; and if he repent, forgive him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 4, E'And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 5, E'And the apostles said unto the Lord, Increase our faith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 6, E'And the Lord said, If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 7, E'But which of you, having a servant plowing or feeding cattle, will say unto him by and by, when he is come from the field, Go and sit down to meat?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 8, E'And will not rather say unto him, Make ready wherewith I may sup, and gird thyself, and serve me, till I have eaten and drunken; and afterward thou shalt eat and drink?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 9, E'Doth he thank that servant because he did the things that were commanded him? I trow not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 10, E'So likewise ye, when ye shall have done all those things which are commanded you, say, We are unprofitable servants: we have done that which was our duty to do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 11, E'And it came to pass, as he went to Jerusalem, that he passed through the midst of Samaria and Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 12, E'And as he entered into a certain village, there met him ten men that were lepers, which stood afar off:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 13, E'And they lifted up their voices, and said, Jesus, Master, have mercy on us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 14, E'And when he saw them, he said unto them, Go shew yourselves unto the priests. And it came to pass, that, as they went, they were cleansed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 15, E'And one of them, when he saw that he was healed, turned back, and with a loud voice glorified God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 16, E'And fell down on his face at his feet, giving him thanks: and he was a Samaritan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 17, E'And Jesus answering said, Were there not ten cleansed? but where are the nine?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 18, E'There are not found that returned to give glory to God, save this stranger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 19, E'And he said unto him, Arise, go thy way: thy faith hath made thee whole.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 20, E'And when he was demanded of the Pharisees, when the kingdom of God should come, he answered them and said, The kingdom of God cometh not with observation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 21, E'Neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 22, E'And he said unto the disciples, The days will come, when ye shall desire to see one of the days of the Son of man, and ye shall not see it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 23, E'And they shall say to you, See here; or, see there: go not after them, nor follow them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 24, E'For as the lightning, that lighteneth out of the one part under heaven, shineth unto the other part under heaven; so shall also the Son of man be in his day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 25, E'But first must he suffer many things, and be rejected of this generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 26, E'And as it was in the days of Noe, so shall it be also in the days of the Son of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 27, E'They did eat, they drank, they married wives, they were given in marriage, until the day that Noe entered into the ark, and the flood came, and destroyed them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 28, E'Likewise also as it was in the days of Lot; they did eat, they drank, they bought, they sold, they planted, they builded;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 29, E'But the same day that Lot went out of Sodom it rained fire and brimstone from heaven, and destroyed them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 30, E'Even thus shall it be in the day when the Son of man is revealed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 31, E'In that day, he which shall be upon the housetop, and his stuff in the house, let him not come down to take it away: and he that is in the field, let him likewise not return back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 32, E'Remember Lotâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 33, E'Whosoever shall seek to save his life shall lose it; and whosoever shall lose his life shall preserve it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 34, E'I tell you, in that night there shall be two men in one bed; the one shall be taken, and the other shall be left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 35, E'Two women shall be grinding together; the one shall be taken, and the other left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 36, E'Two men shall be in the field; the one shall be taken, and the other left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 17, 37, E'And they answered and said unto him, Where, Lord? And he said unto them, Wheresoever the body is, thither will the eagles be gathered together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 1, E'And he spake a parable unto them to this end, that men ought always to pray, and not to faint;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 2, E'Saying, There was in a city a judge, which feared not God, neither regarded man:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 3, E'And there was a widow in that city; and she came unto him, saying, Avenge me of mine adversary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 4, E'And he would not for a while: but afterward he said within himself, Though I fear not God, nor regard man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 5, E'Yet because this widow troubleth me, I will avenge her, lest by her continual coming she weary me.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 6, E'And the Lord said, Hear what the unjust judge saith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 7, E'And shall not God avenge his own elect, which cry day and night unto him, though he bear long with them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 8, E'I tell you that he will avenge them speedily. Nevertheless when the Son of man cometh, shall he find faith on the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 9, E'And he spake this parable unto certain which trusted in themselves that they were righteous, and despised others:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 10, E'Two men went up into the temple to pray; the one a Pharisee, and the other a publican.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 11, E'The Pharisee stood and prayed thus with himself, God, I thank thee, that I am not as other men are, extortioners, unjust, adulterers, or even as this publican.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 12, E'I fast twice in the week, I give tithes of all that I possess.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 13, E'And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 14, E'I tell you, this man went down to his house justified rather than the other: for every one that exalteth himself shall be abased; and he that humbleth himself shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 15, E'And they brought unto him also infants, that he would touch them: but when his disciples saw it, they rebuked them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 16, E'But Jesus called them unto him, and said, Suffer little children to come unto me, and forbid them not: for of such is the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 17, E'Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child shall in no wise enter therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 18, E'And a certain ruler asked him, saying, Good Master, what shall I do to inherit eternal life?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 19, E'And Jesus said unto him, Why callest thou me good? none is good, save one, that is, God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 20, E'Thou knowest the commandments, Do not commit adultery, Do not kill, Do not steal, Do not bear false witness, Honour thy father and thy mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 21, E'And he said, All these have I kept from my youth up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 22, E'Now when Jesus heard these things, he said unto him, Yet lackest thou one thing: sell all that thou hast, and distribute unto the poor, and thou shalt have treasure in heaven: and come, follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 23, E'And when he heard this, he was very sorrowful: for he was very rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 24, E'And when Jesus saw that he was very sorrowful, he said, How hardly shall they that have riches enter into the kingdom of God!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 25, E'For it is easier for a camel to go through a needleâ€™s eye, than for a rich man to enter into the kingdom of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 26, E'And they that heard it said, Who then can be saved?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 27, E'And he said, The things which are impossible with men are possible with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 28, E'Then Peter said, Lo, we have left all, and followed thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 29, E'And he said unto them, Verily I say unto you, There is no man that hath left house, or parents, or brethren, or wife, or children, for the kingdom of Godâ€™s sake,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 30, E'Who shall not receive manifold more in this present time, and in the world to come life everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 31, E'Then he took unto him the twelve, and said unto them, Behold, we go up to Jerusalem, and all things that are written by the prophets concerning the Son of man shall be accomplished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 32, E'For he shall be delivered unto the Gentiles, and shall be mocked, and spitefully entreated, and spitted on:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 33, E'And they shall scourge him, and put him to death: and the third day he shall rise again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 34, E'And they understood none of these things: and this saying was hid from them, neither knew they the things which were spoken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 35, E'And it came to pass, that as he was come nigh unto Jericho, a certain blind man sat by the way side begging:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 36, E'And hearing the multitude pass by, he asked what it meant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 37, E'And they told him, that Jesus of Nazareth passeth by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 38, E'And he cried, saying, Jesus, thou son of David, have mercy on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 39, E'And they which went before rebuked him, that he should hold his peace: but he cried so much the more, Thou son of David, have mercy on me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 40, E'And Jesus stood, and commanded him to be brought unto him: and when he was come near, he asked him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 41, E'Saying, What wilt thou that I shall do unto thee? And he said, Lord, that I may receive my sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 42, E'And Jesus said unto him, Receive thy sight: thy faith hath saved thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 18, 43, E'And immediately he received his sight, and followed him, glorifying God: and all the people, when they saw it, gave praise unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 1, E'And Jesus entered and passed through Jericho.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 2, E'And, behold, there was a man named Zacchaeus, which was the chief among the publicans, and he was rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 3, E'And he sought to see Jesus who he was; and could not for the press, because he was little of stature.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 4, E'And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 5, E'And when Jesus came to the place, he looked up, and saw him, and said unto him, Zacchaeus, make haste, and come down; for to day I must abide at thy house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 6, E'And he made haste, and came down, and received him joyfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 7, E'And when they saw it, they all murmured, saying, That he was gone to be guest with a man that is a sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 8, E'And Zacchaeus stood, and said unto the Lord; Behold, Lord, the half of my goods I give to the poor; and if I have taken any thing from any man by false accusation, I restore him fourfold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 9, E'And Jesus said unto him, This day is salvation come to this house, forsomuch as he also is a son of Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 10, E'For the Son of man is come to seek and to save that which was lost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 11, E'And as they heard these things, he added and spake a parable, because he was nigh to Jerusalem, and because they thought that the kingdom of God should immediately appear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 12, E'He said therefore, A certain nobleman went into a far country to receive for himself a kingdom, and to return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 13, E'And he called his ten servants, and delivered them ten pounds, and said unto them, Occupy till I come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 14, E'But his citizens hated him, and sent a message after him, saying, We will not have this man to reign over us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 15, E'And it came to pass, that when he was returned, having received the kingdom, then he commanded these servants to be called unto him, to whom he had given the money, that he might know how much every man had gained by trading.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 16, E'Then came the first, saying, Lord, thy pound hath gained ten pounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 17, E'And he said unto him, Well, thou good servant: because thou hast been faithful in a very little, have thou authority over ten cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 18, E'And the second came, saying, Lord, thy pound hath gained five pounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 19, E'And he said likewise to him, Be thou also over five cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 20, E'And another came, saying, Lord, behold, here is thy pound, which I have kept laid up in a napkin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 21, E'For I feared thee, because thou art an austere man: thou takest up that thou layedst not down, and reapest that thou didst not sow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 22, E'And he saith unto him, Out of thine own mouth will I judge thee, thou wicked servant. Thou knewest that I was an austere man, taking up that I laid not down, and reaping that I did not sow:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 23, E'Wherefore then gavest not thou my money into the bank, that at my coming I might have required mine own with usury?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 24, E'And he said unto them that stood by, Take from him the pound, and give it to him that hath ten pounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 25, E'(And they said unto him, Lord, he hath ten pounds.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 26, E'For I say unto you, That unto every one which hath shall be given; and from him that hath not, even that he hath shall be taken away from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 27, E'But those mine enemies, which would not that I should reign over them, bring hither, and slay them before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 28, E'And when he had thus spoken, he went before, ascending up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 29, E'And it came to pass, when he was come nigh to Bethphage and Bethany, at the mount called the mount of Olives, he sent two of his disciples,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 30, E'Saying, Go ye into the village over against you; in the which at your entering ye shall find a colt tied, whereon yet never man sat: loose him, and bring him hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 31, E'And if any man ask you, Why do ye loose him? thus shall ye say unto him, Because the Lord hath need of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 32, E'And they that were sent went their way, and found even as he had said unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 33, E'And as they were loosing the colt, the owners thereof said unto them, Why loose ye the colt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 34, E'And they said, The Lord hath need of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 35, E'And they brought him to Jesus: and they cast their garments upon the colt, and they set Jesus thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 36, E'And as he went, they spread their clothes in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 37, E'And when he was come nigh, even now at the descent of the mount of Olives, the whole multitude of the disciples began to rejoice and praise God with a loud voice for all the mighty works that they had seen;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 38, E'Saying, Blessed be the King that cometh in the name of the Lord: peace in heaven, and glory in the highest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 39, E'And some of the Pharisees from among the multitude said unto him, Master, rebuke thy disciples.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 40, E'And he answered and said unto them, I tell you that, if these should hold their peace, the stones would immediately cry out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 41, E'And when he was come near, he beheld the city, and wept over it,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 42, E'Saying, If thou hadst known, even thou, at least in this thy day, the things which belong unto thy peace! but now they are hid from thine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 43, E'For the days shall come upon thee, that thine enemies shall cast a trench about thee, and compass thee round, and keep thee in on every side,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 44, E'And shall lay thee even with the ground, and thy children within thee; and they shall not leave in thee one stone upon another; because thou knewest not the time of thy visitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 45, E'And he went into the temple, and began to cast out them that sold therein, and them that bought;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 46, E'Saying unto them, It is written, My house is the house of prayer: but ye have made it a den of thieves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 47, E'And he taught daily in the temple. But the chief priests and the scribes and the chief of the people sought to destroy him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 19, 48, E'And could not find what they might do: for all the people were very attentive to hear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 1, E'And it came to pass, that on one of those days, as he taught the people in the temple, and preached the gospel, the chief priests and the scribes came upon him with the elders,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 2, E'And spake unto him, saying, Tell us, by what authority doest thou these things? or who is he that gave thee this authority?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 3, E'And he answered and said unto them, I will also ask you one thing; and answer me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 4, E'The baptism of John, was it from heaven, or of men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 5, E'And they reasoned with themselves, saying, If we shall say, From heaven; he will say, Why then believed ye him not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 6, E'But and if we say, Of men; all the people will stone us: for they be persuaded that John was a prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 7, E'And they answered, that they could not tell whence it was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 8, E'And Jesus said unto them, Neither tell I you by what authority I do these things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 9, E'Then began he to speak to the people this parable; A certain man planted a vineyard, and let it forth to husbandmen, and went into a far country for a long time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 10, E'And at the season he sent a servant to the husbandmen, that they should give him of the fruit of the vineyard: but the husbandmen beat him, and sent him away empty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 11, E'And again he sent another servant: and they beat him also, and entreated him shamefully, and sent him away empty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 12, E'And again he sent a third: and they wounded him also, and cast him out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 13, E'Then said the lord of the vineyard, What shall I do? I will send my beloved son: it may be they will reverence him when they see him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '10674417-8d4e-4e13-9239-d9c2b761917e', 20, 14, E'But when the husbandmen saw him, they reasoned among themselves, saying, This is the heir: come, let us kill him, that the inheritance may be ours.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Luke') b
ON CONFLICT DO NOTHING;

